local config = {
  ui_story_5032_50320101_1_dialog_content = "<color=#e8d9bb>PlayerName, Vice y Carleen, que se siente perdida en la búsqueda del poder, se dirigen al bullicioso puerto de Harbor City.</color>",
  ui_story_5032_50320101_2_dialog_content = "<color=#e8d9bb>En su camino para visitar a Laird Elvis, Caelestite se encuentra una vez más con Fia, la extrozoóloga.</color>",
  ui_story_5032_50320101_3_dialog_content = "<color=#e8d9bb>Laird Elvis da una calurosa bienvenida al grupo, pero parece estar escondiendo algo debajo de su cuerpo frágil y rostro lleno de cicatrices.</color>",
  ui_story_5032_50320101_4_dialog_content = "<color=#e8d9bb>Un giro del destino lleva al grupo al Emerald, un barco donde se lleva a cabo un gran festival.</color>",
  ui_story_5032_50320101_5_dialog_content = "<color=#e8d9bb>Aquí, PlayerName y otros conocen a Jeno, el misterioso y distante maestro de ceremonias.</color>",
  ui_story_5032_50320101_6_dialog_content = "<color=#e8d9bb>El alegre y entusiasta Rainbow, que es el maestro de ceremonias del circo, el enlace con el cliente, el director de seguridad y el aprendiz de ingeniero marino.</color>",
  ui_story_5032_50320101_7_dialog_content = "<color=#e8d9bb>Y los tres emocionantes trapecistas de altos vuelos, Merylt, Subli y Frimet.</color>",
  ui_story_5032_50320101_8_dialog_content = "<color=#e8d9bb>Fia está convencida de que la maravillosa bestia que está buscando, una <color=#FFB400>ballenanube</color>, está en algún lugar a bordo del Emerald.</color>",
  ui_story_5032_50320101_9_dialog_content = "<color=#e8d9bb>Para saber si tiene razón, el escuadrón Caelestite decide inscribirse en una competencia y ganar más tiempo para explorar el circo.</color>",
  ui_story_5032_50320101_10_dialog_content = "<color=#e8d9bb>Mientras tanto, Carleen, todavía perdida, le pregunta a Vice cómo puede volverse más fuerte.</color>",
  ui_story_5032_50320101_11_dialog_content = "<color=#e8d9bb>La Esmeralda se llena de alegría y risas, pero Laird Elvis, que se sienta entre los jueces, está perdido en sus pensamientos.</color>",
  ui_story_5032_50320101_12_dialog_content = "<color=#e8d9bb>Frustrada durante la competencia, Carleen obtiene nuevos conocimientos gracias al apoyo de PlayerName.</color>",
  ui_story_5032_50320101_13_dialog_content = "<color=#e8d9bb>Al final, el escuadrón Caelestite sale victorioso. Pero el premio no es una Ballena Nube.</color>",
  ui_story_5032_50320101_14_dialog_content = "<color=#e8d9bb>En cambio, el premio es Kyllo, la maravillosa bestia compañera de Fia, que ella había enviado a buscar a Cloudwhale en las aguas cercanas.</color>",
  ui_story_5032_50320101_15_dialog_content = "<color=#e8d9bb>Decepcionado, el grupo se prepara para despedirse de Jeno y continuar su búsqueda de Cloudwhale.</color>",
  ui_story_5032_50320101_16_dialog_content = "<color=#e8d9bb>Pero cuando buscan a Jeno, lo encuentran desmayado en la cabina del Emerald.</color>",
  ui_story_5032_50320101_17_dialog_content = "<color=#e8d9bb>Justo cuando logran despertarlo, el barco se sacude violentamente.</color>",
  ui_story_5032_50320101_18_dialog_content = "<color=#e8d9bb>Jeno guía al equipo mientras corren hacia la cámara central de Emerald.</color>",
  ui_story_5032_50320101_19_dialog_content = "<color=#e8d9bb>Pero en el camino, los guardias que llevan el sello de la familia Elvis bloquean su paso.</color>",
  ui_story_5032_50320101_20_dialog_content = "<color=#e8d9bb>Después de superar varios obstáculos, el grupo de Caelestite llega a la cámara central y finalmente encuentra a Elvis allí.</color>",
  ui_story_5032_50320101_21_dialog_content = "<color=#e8d9bb>Y está usando algún dispositivo en su bastón para absorber energía del núcleo de energía.</color>",
  ui_story_5032_50320101_22_dialog_content = "<color=#e8d9bb>Tal acción despierta a la enorme máquina que custodia el núcleo, que comienza a atacar al grupo.</color>",
  ui_story_5032_50320101_23_dialog_content = "<color=#e8d9bb>El poderoso Guardián lleva al equipo Colossus al borde de la derrota. Incluso Carleen queda inmovilizada por la trampa de Elvis.</color>",
  ui_story_5032_50320101_24_dialog_content = "<color=#e8d9bb>Pero en un momento decisivo, un nuevo poder despierta dentro de Carleen, haciendo retroceder al Guardián.</color>",
  ui_story_5032_50320101_25_dialog_content = "<color=#e8d9bb>El grupo derrota a The Guardian, pero Elvis escapa, solo para ser atrapado por Matthieu, un juez de Lumopolis.</color>",
  ui_story_5032_50320101_26_dialog_content = "<color=#e8d9bb>Pero parece que todo esto... está lejos de terminar.</color>",
  ui_story_5032_50320101_27_dialog_content = "<color=#e8d9bb>El aire ruge en la lluvia fría, y el cielo se enciende en el viento salvaje. ¡Se acerca una tormenta que destrozará Harbor City!</color>",
  ui_story_5032_50320101_28_dialog_content = "¡Rápido rápido! ¡La vista desde aquí es increíble!",
  ui_story_5032_50320101_29_dialog_content = "E-Elvis! ¡Estás corriendo demasiado rápido!",
  ui_story_5032_50320101_30_dialog_content = "Guau...",
  ui_story_5032_50320101_31_dialog_content = "¿Qué hay sobre eso? No puedes ver este tipo de vista quedándote en casa.",
  ui_story_5032_50320101_32_dialog_content = "No te preocupes por esos pequeños matones que causan problemas. Puedo manejarlos y más.",
  ui_story_5032_50320101_33_dialog_content = "Esta playa, este océano, un día todo nos pertenecerá a ti ya mí.",
  ui_story_5032_50320101_34_dialog_content = "¡Sí!",
  ui_story_5032_50320101_35_dialog_content = "A veces sueño con hacer esto. Salir de mi habitación y pintar el mundo exterior.",
  ui_story_5032_50320101_36_dialog_content = "Tal vez... Tal vez debería pintar este momento nuestro.",
  ui_story_5032_50320101_37_dialog_content = "¿En serio? ¿Me pintarías?",
  ui_story_5032_50320101_38_dialog_content = "Sí, pero soy lento y tampoco muy bueno en eso.",
  ui_story_5032_50320101_39_dialog_content = "Está bien. Tus dibujos son los mejores para mi!",
  ui_story_5032_50320101_40_dialog_content = "Entonces... ¿por qué no nos encontramos mañana temprano en el puerto?",
  ui_story_5032_50320101_41_dialog_content = "Podemos recoger algo de marisco de la playa. ¡Entonces puedes pintarme y te haré sopa de mariscos!",
  ui_story_5032_50320101_42_dialog_content = "¡Guau, la sopa de mariscos de Elvis!",
  ui_story_5032_50320101_43_dialog_content = "¡Impresionante! ¡Es un trato, entonces!",
  ui_story_5032_50320101_44_dialog_content = "¡Acuerdo!",
  ui_story_5032_50320101_45_dialog_content = "Teniamos un trato...",
  ui_story_5032_50320101_46_dialog_content = "Habíamos quedado en encontrarnos...",
  ui_story_5032_50320101_47_dialog_content = "Entonces, ¿cómo pudiste irte sin despedirte?",
  ui_story_5032_50320101_48_dialog_content = "¿Por qué me traicionaste? ¿Por qué destruiste mi hogar? ¿Por qué rompiste mi juramento a True Order?",
  ui_story_5032_50320101_49_dialog_content = "¿Y por qué te ves... tan doloroso?",
  ui_story_5032_50320101_50_dialog_content = "Jefe.",
  ui_story_5032_50320101_51_dialog_content = "¡Jefe!",
  ui_story_5032_50320101_52_dialog_content = "¡¡Jefe!!",
  ui_story_5032_50320101_53_dialog_content = "¿Qué?",
  ui_story_5032_50320101_54_dialog_content = "¿Qué estabas mirando? Estabas a kilómetros de distancia.",
  ui_story_5032_50320101_55_dialog_content = "Nada. Estaba pensando en cómo reparar la Esmeralda.",
  ui_story_5032_50320101_56_dialog_content = "¿Ah, de verdad? Pensé que nos habías dado esa tarea a Ciel ya mí.",
  ui_story_5032_50320101_57_dialog_content = "...",
  ui_story_5032_50320101_58_dialog_content = "Hola jefe.",
  ui_story_5032_50320101_59_dialog_content = "Realmente no sé qué pasó entre tú y Laird Elvis.",
  ui_story_5032_50320101_60_dialog_content = "Pero escuché a Caelestite decir que Elvis pidió verte muchas veces después de que lo detuvieran.",
  ui_story_5032_50320101_61_dialog_content = "Hmph.",
  ui_story_5032_50320101_62_dialog_content = "No tengo nada que decirle a alguien que casi destruye la Esmeralda.",
  ui_story_5032_50320101_63_dialog_content = "¿Ah, entonces es así?",
  ui_story_5032_50320101_64_dialog_content = "Pero me siento un poco mal por él. Escuché que su Síndrome Modali está empeorando.",
  ui_story_5032_50320101_65_dialog_content = "Y se niega a comer...",
  ui_story_5032_50320101_66_dialog_content = "Si esto continúa... no creo que dure mucho con ese frágil cuerpo suyo.",
  ui_story_5032_50320101_67_dialog_content = "¿¡Qué dijiste!?",
  ui_story_5032_50320101_68_dialog_content = "¿eh? ¿Jefe?",
  ui_story_5032_50320101_69_dialog_content = "Ahora, ¿adónde vas?",
  ui_story_5032_50320101_70_dialog_content = "Acabo de recordar que nos hemos quedado sin globos.",
  ui_story_5032_50320101_71_dialog_content = "Voy a comprar algunos.",
  ui_story_5032_50320101_72_dialog_content = "¿eh? ¿Qué?",
  ui_story_5032_50320101_73_dialog_content = "Hay una caja entera justo donde estabas parado...",
  ui_story_5032_50320101_74_dialog_content = "Juez Matthieu, Asistente del Juez Loewe.",
  ui_story_5032_50320101_75_dialog_content = "Lamento haberte hecho esperar.",
  ui_story_5032_50320101_76_dialog_content = "No tengo idea de que Elvis tenía tantas tareas que atender cada día.",
  ui_story_5032_50320101_77_dialog_content = "¿Y cómo está?",
  ui_story_5032_50320101_78_dialog_content = "Lo mismo. Se niega a comer o incluso a beber.",
  ui_story_5032_50320101_79_dialog_content = "¿En serio? Debo admirar su fuerza de voluntad.",
  ui_story_5032_50320101_80_dialog_content = "Er, ¿puedo preguntar, Su Alteza, cuánto tiempo planea continuar con esto?",
  ui_story_5032_50320101_81_dialog_content = "Hemos, como usted instruyó, hecho el informe al Consejo de Ancianos. Pero eso no los satisfará por mucho tiempo.",
  ui_story_5032_50320101_82_dialog_content = "Debemos descubrir pronto los verdaderos motivos de Elvis y arrancar de raíz las semillas de la rebelión.",
  ui_story_5032_50320101_83_dialog_content = "De lo contrario, el desorden en Harbour City puede terminar convirtiéndose en nuestro problema a arreglar.",
  ui_story_5032_50320101_84_dialog_content = "Lord Schwartz está enfurecido y los plebeyos han perdido a su amado laird. Todo el mundo está inquieto.",
  ui_story_5032_50320101_85_dialog_content = "Sería preferible regresar a Lumopolis de inmediato. Y que Lord Schwartz envíe a sus hombres a investigar.",
  ui_story_5032_50320101_86_dialog_content = "No. Primero, no me rendiré a la mitad.",
  ui_story_5032_50320101_87_dialog_content = "En segundo lugar, no puedo irme así.",
  ui_story_5032_50320101_88_dialog_content = "Si lo hago, ¿cómo puedo estar seguro de que Lord Schwartz y los ciudadanos de Harbor City obtendrán las respuestas que se merecen?",
  ui_story_5032_50320101_89_dialog_content = "Bien, bien. Entiendo. Olvida lo que dije.",
  ui_story_5032_50320101_90_dialog_content = "Sin embargo, le doy las gracias, juez Matthieu.",
  ui_story_5032_50320101_91_dialog_content = "Eso es nuevo.",
  ui_story_5032_50320101_92_dialog_content = "¿Eh? ¿Que es eso? Puedo decir cosas útiles de vez en cuando, ¿de acuerdo?",
  ui_story_5032_50320101_93_dialog_content = "Seguro.",
  ui_story_5032_50320101_94_dialog_content = "¡Espere hasta que termine de escribir mi informe y le enseñaré por qué soy el juez y usted es mi asistente!",
  ui_story_5032_50320101_95_dialog_content = "Entonces, dejaré la tarea de proteger a Elvis en tus hábiles manos.",
  ui_story_5032_50320101_96_dialog_content = "Como usted ordene.",
  ui_story_5032_50320101_97_dialog_content = "Carleen, estamos de vuelta.",
  ui_story_5032_50320101_98_dialog_content = "¿Cómo te sientes? ¿Todavia duele?",
  ui_story_5032_50320101_99_dialog_content = "Bienvenido de nuevo. Mis heridas y mi Lumina se han recuperado más rápido de lo que esperaba.",
  ui_story_5032_50320101_100_dialog_content = "Ya estoy lo suficientemente bien como para manejar cualquier pelea ordinaria. No te preocupes por mí.",
  ui_story_5032_50320101_101_dialog_content = "¿Qué hay de esas personas que protestan por la detención de Elvis? ¿Se han ido?",
  ui_story_5032_50320101_102_dialog_content = "¿Estás seguro que funcionará?",
  ui_story_5032_50320101_103_dialog_content = "La mayoría de los manifestantes estaban dispuestos a irse en silencio una vez que escucharon que la Princesa Carleen de Lumopolis estaba dirigiendo la investigación.",
  ui_story_5032_50320101_104_dialog_content = "Pero hay algunos reticentes que no escucharían.",
  ui_story_5032_50320101_105_dialog_content = "Tus heridas parecían graves después de la batalla, Carleen. Me diste bastante susto.",
  ui_story_5032_50320101_106_dialog_content = "Por favor, no te esfuerces tanto en el futuro.",
  ui_story_5032_50320101_107_dialog_content = "Lo sé. Perdón por preocuparlos, chicos, Vice, y PlayerName.",
  ui_story_5032_50320101_108_dialog_content = "Ah, y nos encontramos con un guardia en el camino de regreso que nos contó sobre el avistamiento de Eclipsites dispersos en la playa.",
  ui_story_5032_50320101_109_dialog_content = "¿Eclipsitos otra vez? Ha habido informes de apariciones últimamente.",
  ui_story_5032_50320101_110_dialog_content = "Pero nuestras investigaciones de seguimiento no llegaron a nada.",
  ui_story_5032_50320101_111_dialog_content = "Quizás Patou sepa algo. Es el experto en las defensas de la ciudad.",
  ui_story_5032_50320101_112_dialog_content = "Mmm. Patou y el resto de los guardias de Elvis han sido encerrados a su lado, pero no cooperan.",
  ui_story_5032_50320101_113_dialog_content = "Elvis ha estado advirtiendo de una crisis inminente. ¿Crees que eso tuvo algo que ver con los eclipses?",
  ui_story_5032_50320101_114_dialog_content = "Posiblemente. Pero tal como están las cosas, su número no es lo suficientemente alto como para representar una amenaza.",
  ui_story_5032_50320101_115_dialog_content = "Y se niega a decir cuál será la crisis. Todo lo que hace es exigir ver a Jeno.",
  ui_story_5032_50320101_116_dialog_content = "¿Su amigo de la infancia? Bueno, eso es conmovedor...",
  ui_story_5032_50320101_117_dialog_content = "PlayerName, ¿podrían Vice y tú ir a visitar a Elvis una vez más? A ver si puedes encontrar alguna pista en lo que dice.",
  ui_story_5032_50320101_118_dialog_content = "Y habla con Jeno también. Si estuviera dispuesto a hablar con Elvis... Bueno, quizás podamos aprender algo más.",
  ui_story_5032_50320101_119_dialog_content = "Por supuesto. Déjalo con nosotros.",
  ui_story_5032_50320201_1_dialog_content = "Rainbow, ¿quieres intentar reiniciar el sistema?",
  ui_story_5032_50320201_2_dialog_content = "roger Le daré otra oportunidad.",
  ui_story_5032_50320201_3_dialog_content = "<color=#e8d9bb>... Sistema reiniciando. Iniciando la autocomprobación.</color>",
  ui_story_5032_50320201_4_dialog_content = "<color=#e8d9bb>Anomalías detectadas.</color>",
  ui_story_5032_50320201_5_dialog_content = "<color=#e8d9bb>Error del sistema del motor.</color>",
  ui_story_5032_50320201_6_dialog_content = "<color=#e8d9bb>Error del sistema de transmisión.</color>",
  ui_story_5032_50320201_7_dialog_content = "No es bueno. Todavía no arranca.",
  ui_story_5032_50320201_8_dialog_content = "Lo siento...",
  ui_story_5032_50320201_9_dialog_content = "¡Deja de disculparte!",
  ui_story_5032_50320201_10_dialog_content = "Sé que estás haciendo tu mejor esfuerzo. Me has estado ayudando a arreglar el sistema del motor durante mucho tiempo y no puedo recordar la última vez que tuviste un descanso.",
  ui_story_5032_50320201_11_dialog_content = "Está bien.",
  ui_story_5032_50320201_12_dialog_content = "Me ayudaste a actualizar Styx. Así que ahora necesito ayudarte a poner tu Emerald en funcionamiento nuevamente.",
  ui_story_5032_50320201_13_dialog_content = "Porque para eso están los amigos, ¿no?",
  ui_story_5032_50320201_14_dialog_content = "¡Sí! Y tú eres un muy buen amigo, Ciel.",
  ui_story_5032_50320201_15_dialog_content = "Estoy muy agradecida de tenerte aquí ayudándome a arreglar la Esmeralda.",
  ui_story_5032_50320201_16_dialog_content = "Oye, estás demasiado cerca y no puedo leer los datos.",
  ui_story_5032_50320201_17_dialog_content = "Aférrate. Mirando estos registros que acabo de extraer... ¿se ha retirado alguna maquinaria de esta nave?",
  ui_story_5032_50320201_18_dialog_content = "Podría ser. Recuerdo al viejo ingeniero diciéndome que el barco tiene una historia larga y compleja.",
  ui_story_5032_50320201_19_dialog_content = "Desafortunadamente, ya no está con nosotros. Si él era-",
  ui_story_5032_50320201_20_dialog_content = "*Sollozando* Si tan solo estuviera aquí—",
  ui_story_5032_50320201_21_dialog_content = "¿Qué sucedió? ¿Le pasó algo malo?",
  ui_story_5032_50320201_22_dialog_content = "No. Dijo que finalmente encontró un sucesor. Y luego nos fuimos cuando atracamos sin despedirnos.",
  ui_story_5032_50320201_23_dialog_content = "Escuché que ahora está casado y tiene hijos, y tiene una parrillada.",
  ui_story_5032_50320201_24_dialog_content = "Pero todavía no había aprendido mucho de él. Así que tuve que estudiarlo todo yo mismo. Por suerte lo disfruto.",
  ui_story_5032_50320201_25_dialog_content = "Y afortunadamente, el núcleo no requiere mucho mantenimiento y no ha tenido ningún problema desde que asumí el control.",
  ui_story_5032_50320201_26_dialog_content = "Eso es realmente increíblemente confiable. Me hace preguntarme para qué se usó originalmente el barco...",
  ui_story_5032_50320201_27_dialog_content = "Y con The Guardian, simplemente se suma al misterio.",
  ui_story_5032_50320201_28_dialog_content = "De hecho, una vez le pregunté a mi predecesor qué era ese Guardián.",
  ui_story_5032_50320201_29_dialog_content = "Pero él simplemente me ignoró, diciendo que probablemente solo era una decoración que se ve genial.",
  ui_story_5032_50320201_30_dialog_content = "Ja. Suena como si fuera un tipo raro.",
  ui_story_5032_50320201_31_dialog_content = "¿Yo se, verdad? Pero la Esmeralda sigue funcionando, aunque no cuente con los mejores ingenieros. ¡Es un gran barco!",
  ui_story_5032_50320201_32_dialog_content = "... Graagh!",
  ui_story_5032_50320201_33_dialog_content = "Esperar. ¿Escuchaste algo en la distancia?",
  ui_story_5032_50320201_34_dialog_content = "¿eh? Merylt, realmente escribiste PlayerName ¿una carta?",
  ui_story_5032_50320201_35_dialog_content = "¡Deja que te ayude! Puedo dárselo por ti.",
  ui_story_5032_50320201_36_dialog_content = "Ya sabes, en caso de que seas demasiado tímido para entregarlo.",
  ui_story_5032_50320201_37_dialog_content = "Pero... creo que debería dárselo personalmente.",
  ui_story_5032_50320201_38_dialog_content = "¡No no! ¡Debes dejarme hacerlo, Merylt!",
  ui_story_5032_50320201_39_dialog_content = "¡Subli definitivamente lo abrirá y lo leerá! Su curiosidad le impide hacer otra cosa.",
  ui_story_5032_50320201_40_dialog_content = "Incluso podría agregarle algunas cosas.",
  ui_story_5032_50320201_41_dialog_content = "¿eh? Ella no lo haría, ¿verdad?",
  ui_story_5032_50320201_42_dialog_content = "Lo siento, Merylt, pero Frimet me conoce demasiado bien.",
  ui_story_5032_50320201_43_dialog_content = "¡Ah, devuélveme la carta!",
  ui_story_5032_50320201_44_dialog_content = "Bica, tómalo por mí.",
  ui_story_5032_50320201_45_dialog_content = "¿Hola?",
  ui_story_5032_50320201_46_dialog_content = "¡Alto ahí!",
  ui_story_5032_50320201_47_dialog_content = "Aquí está tu carta.",
  ui_story_5032_50320201_48_dialog_content = "G-gracias, señorita Fia.",
  ui_story_5032_50320201_49_dialog_content = "Qué montón de niños ruidosos.",
  ui_story_5032_50320201_50_dialog_content = "¿No puedes ser más maduro? Como yo.",
  ui_story_5032_50320201_51_dialog_content = "Oh, eres maduro? no me habia dado cuenta",
  ui_story_5032_50320201_52_dialog_content = "Y si hablamos de fuerza, incluso Merylt probablemente podría vencerte.",
  ui_story_5032_50320201_53_dialog_content = "¿¡Qué dijiste!? ¿Quieres saber qué tan fuerte soy?",
  ui_story_5032_50320201_54_dialog_content = "Subli, Frimet, dejen de molestar a la señorita Fia. Es una invitada del circo, ¿recuerdas?",
  ui_story_5032_50320201_55_dialog_content = "Bien, bien.",
  ui_story_5032_50320201_56_dialog_content = "Hmph. Oigan, ¿cómo es que ustedes tres no se quedan en tierra como el resto de la tripulación?",
  ui_story_5032_50320201_57_dialog_content = "Yo mismo puedo cuidar de las maravillosas bestias.",
  ui_story_5032_50320201_58_dialog_content = "Soy un miembro temporal del circo, después de todo, y el cuidado de los animales es mi área de especialización.",
  ui_story_5032_50320201_59_dialog_content = "¿Cómo podríamos?",
  ui_story_5032_50320201_60_dialog_content = "La gente de la ciudad piensa que fuimos nosotros, la gente del circo, los que dañamos a su amado Laird Elvis.",
  ui_story_5032_50320201_61_dialog_content = "En el mejor de los casos, nos tratarán con frialdad e incluso podrían intentar iniciar una pelea.",
  ui_story_5032_50320201_62_dialog_content = "Además, preferimos estar en el Emerald de todos modos.",
  ui_story_5032_50320201_63_dialog_content = "Después de todo, esta es nuestra casa, ¿sabes?",
  ui_story_5032_50320201_64_dialog_content = "Sí...",
  ui_story_5032_50320201_65_dialog_content = "Creo que puedo entender cómo te sientes.",
  ui_story_5032_50320201_66_dialog_content = "Mi trabajo como extrozoólogo consiste en recorrer todos los rincones del continente, pero a veces, todavía extraño el guiso de carne de mi madre.",
  ui_story_5032_50320201_67_dialog_content = "Y hablando de bestias maravillosas, todavía no he logrado el objetivo que me trajo a Harbor City.",
  ui_story_5032_50320201_68_dialog_content = "¿Qué es eso?",
  ui_story_5032_50320201_69_dialog_content = "Vamos, cuéntanos. Deberíamos ser capaces de ayudar.",
  ui_story_5032_50320201_70_dialog_content = "Bueno, supongo que no tiene sentido ser reservado ahora.",
  ui_story_5032_50320201_71_dialog_content = "Está bien.",
  ui_story_5032_50320201_72_dialog_content = "De hecho, estoy en busca de una bestia maravillosa exótica. los <color=#FFB400>ballenanube</color>!",
  ui_story_5032_50320201_73_dialog_content = "¿Qué es eso, una especie de ballena?",
  ui_story_5032_50320201_74_dialog_content = "S-Sí, supongo que sí.",
  ui_story_5032_50320201_75_dialog_content = "Quiero decir, no es que no lo sepa. Es que mi pésimo maestro no se explicó bien.",
  ui_story_5032_50320201_76_dialog_content = "Me dijo que el rastro de energía de Cloudwhale desapareció en algún lugar del océano cerca de aquí, luego me envió a investigar.",
  ui_story_5032_50320201_77_dialog_content = "Todo lo que sé es que su poderosa Lumina puede hacer que los Eclipsites se encojan de miedo y disipar incluso el Darkflow más espeso.",
  ui_story_5032_50320201_78_dialog_content = "¿Ballenas? Nunca he visto uno, pero he oído a gente mayor del circo hablar de ellos.",
  ui_story_5032_50320201_79_dialog_content = "Todos son enormes y pasan la mayor parte de su tiempo en lo profundo del océano.",
  ui_story_5032_50320201_80_dialog_content = "Parece que se quedarán varados fácilmente si llegan a aguas poco profundas.",
  ui_story_5032_50320201_81_dialog_content = "Sí, ¿y los peces no tienen miedo de los barcos? No esperaría que nadie nadase cerca de aquí.",
  ui_story_5032_50320201_82_dialog_content = "¡Argh! ¿Ese hombre me ha enviado a una búsqueda inútil?",
  ui_story_5032_50320201_83_dialog_content = "¡Entonces estoy teniendo una crisis!",
  ui_story_5032_50320201_84_dialog_content = "¡Ah!",
  ui_story_5032_50320201_85_dialog_content = "Vaya, perdón por gritar así de repente. ¿Te asuste?",
  ui_story_5032_50320201_86_dialog_content = "Está bien. Acabo de dejar caer todas mis cosas, eso es todo.",
  ui_story_5032_50320201_87_dialog_content = "No te muevas, yo los recogeré por ti.",
  ui_story_5032_50320201_88_dialog_content = "¡Hah!",
  ui_story_5032_50320201_89_dialog_content = "jaja!!",
  ui_story_5032_50320201_90_dialog_content = "¿Eso es todo? ¿Y qué es esto? ¿Algún tipo de bocadillo sabroso?",
  ui_story_5032_50320201_91_dialog_content = "¡Así es, como todos esos deliciosos dulces que tomaste la última vez! Y te ayudará a ser más alto.",
  ui_story_5032_50320201_92_dialog_content = "Subli, no intentes hacer que Fia se coma la comida para peces.",
  ui_story_5032_50320201_93_dialog_content = "En realidad, esa es la comida para peces que hice yo mismo.",
  ui_story_5032_50320201_94_dialog_content = "Pero si te gustó el dulce que comimos la última vez... ¡Puedo hacerte uno!",
  ui_story_5032_50320201_95_dialog_content = "¿Por qué a mi? No, soy demasiado viejo para cosas como dulces. ¡Solo tenía curiosidad!",
  ui_story_5032_50320201_96_dialog_content = "Oye, Merylt, ¿tú crías pescado? ¡Déjame ayudarte a identificar qué razas son!",
  ui_story_5032_50320201_97_dialog_content = "Es ese pequeño, allá.",
  ui_story_5032_50320201_98_dialog_content = "Mmm. Sólo este pequeño hombre gris. No puedo decir que raza es.",
  ui_story_5032_50320201_99_dialog_content = "¡Eep!",
  ui_story_5032_50320201_100_dialog_content = "¿Puede realmente comer todo eso en una comida? ¡Eso es increíble!",
  ui_story_5032_50320201_101_dialog_content = "Nuestro maestro de ceremonias encontró a este pequeño en la playa...",
  ui_story_5032_50320201_102_dialog_content = "Dijo que parecía herido y me lo trajo para que lo cuidara.",
  ui_story_5032_50320201_103_dialog_content = "Ah, y dijo que ya estaba en esta botella cuando la encontró.",
  ui_story_5032_50320201_104_dialog_content = "Pedí una pecera adecuada, pero aún no está lista. Así que nuestro pequeño está atrapado allí por ahora.",
  ui_story_5032_50320201_105_dialog_content = "Nunca pensé que ese feroz maestro de ceremonias sería tan amable con los animales.",
  ui_story_5032_50320201_106_dialog_content = "Sí... Incluso le dio un nombre: <color=#FFB400>Geedo</color>.",
  ui_story_5032_50320201_107_dialog_content = "Oye, Fia... ¿Podría ser esta la ballena nubosa que estás buscando?",
  ui_story_5032_50320201_108_dialog_content = "¡Eep!",
  ui_story_5032_50320201_109_dialog_content = "Geedo es demasiado pequeño para ser un Cloudwhale.",
  ui_story_5032_50320201_110_dialog_content = "El maestro de ceremonias Jeno me dijo que incluso una cría de ballena sería demasiado grande para este barco.",
  ui_story_5032_50320201_111_dialog_content = "Y las ballenas no hacen \"eep eep\". Hacen \"croak croak\".",
  ui_story_5032_50320201_112_dialog_content = "¿En serio? ¿No es \"hoot hoot\".",
  ui_story_5032_50320201_113_dialog_content = "Completamente equivocado. Es \"guau, guau\".",
  ui_story_5032_50320201_114_dialog_content = "¿No es \"chirrido chirrido\"?",
  ui_story_5032_50320201_115_dialog_content = "Graagh—",
  ui_story_5032_50320201_116_dialog_content = "¡Estás completamente equivocado! Así no es como suenan las ballenas. es totalmente...",
  ui_story_5032_50320201_117_dialog_content = "Graagh—",
  ui_story_5032_50320201_118_dialog_content = "¡Eclipsitos! ¿¡Cómo subieron a bordo los Eclipsites!?",
  ui_story_5032_50320202_1_dialog_content = "Decir ah-!",
  ui_story_5032_50320202_2_dialog_content = "¡Oye!",
  ui_story_5032_50320202_3_dialog_content = "¡Hay más de ellos!",
  ui_story_5032_50320202_4_dialog_content = "Graagh...",
  ui_story_5032_50320202_5_dialog_content = "¡Cuidado, Fía!",
  ui_story_5032_50320202_6_dialog_content = "¡Menudos eclipses! ¡Toma esto!",
  ui_story_5032_50320202_7_dialog_content = "<color=#e8d9bb>¡Bang, bang!</color>",
  ui_story_5032_50320202_8_dialog_content = "Graagh—",
  ui_story_5032_50320202_9_dialog_content = "Vaya, nunca esperé que fueras tan buena luchadora, Fia.",
  ui_story_5032_50320202_10_dialog_content = "Jejeje. Estos débiles eclipses no son rival para mí.",
  ui_story_5032_50320202_11_dialog_content = "Eran obviamente muy débiles.",
  ui_story_5032_50320202_12_dialog_content = "¡Tipo! ¿Estás bien?",
  ui_story_5032_50320202_13_dialog_content = "Huff, huff... C-Ciel, no puedes precipitarte así.",
  ui_story_5032_50320202_14_dialog_content = "Es demasiado peligroso ahora que no tienes a Styx contigo.",
  ui_story_5032_50320202_15_dialog_content = "Lo siento. Pero sabía que estabas justo detrás de mí, Rainbow.",
  ui_story_5032_50320202_16_dialog_content = "Bien, eso es cierto.",
  ui_story_5032_50320202_17_dialog_content = "Pero sigue siendo demasiado peligroso. No lo hagas de nuevo.",
  ui_story_5032_50320202_18_dialog_content = "Está bien, entiendo.",
  ui_story_5032_50320202_19_dialog_content = "Está bien, nadie está herido. Eso es lo importante.",
  ui_story_5032_50320202_20_dialog_content = "Pero, ¿de dónde vienen estos eclipses?",
  ui_story_5032_50320202_21_dialog_content = "Ni idea.",
  ui_story_5032_50320202_22_dialog_content = "Normalmente, podríamos comprobar los registros del sistema de Emerald y averiguarlo.",
  ui_story_5032_50320202_23_dialog_content = "Pero el sistema sigue caído, así que me temo que tendremos que realizar una búsqueda lugar por lugar.",
  ui_story_5032_50320202_24_dialog_content = "Supongo que esa es nuestra única opción.",
  ui_story_5032_50320202_25_dialog_content = "Pero un grupo de seis es demasiado grande para andar cargando en el barco.",
  ui_story_5032_50320202_26_dialog_content = "Y un grupo demasiado pequeño podría ser peligroso si aparecen más Eclipsites.",
  ui_story_5032_50320202_27_dialog_content = "Así que dividámonos en dos equipos.",
  ui_story_5032_50320202_28_dialog_content = "Merylt, tú y tus hermanas sois fuertes luchadoras. Ustedes tres pueden ser un equipo.",
  ui_story_5032_50320202_29_dialog_content = "¡Entendido!",
  ui_story_5032_50320202_30_dialog_content = "No estamos muy familiarizados con las cosas que hay dentro del barco, así que deberíamos subir a comprobar la cubierta y sus alrededores.",
  ui_story_5032_50320202_31_dialog_content = "Está bien, eso te lo dejamos a ti.",
  ui_story_5032_50320202_32_dialog_content = "Luego seguiré a Rainbow y Ciel para revisar el interior de la nave.",
  ui_story_5032_50320202_33_dialog_content = "Bueno. Pero no deambules y toques cosas al azar solo porque tienes curiosidad.",
  ui_story_5032_50320202_34_dialog_content = "Todavía podría haber Eclipsites dando vueltas.",
  ui_story_5032_50320202_35_dialog_content = "Está bien, no lo haré.",
  ui_story_5032_50320301_1_dialog_content = "Elvis sigue sin hablar.",
  ui_story_5032_50320301_2_dialog_content = "Sigue murmurando sobre querer ver a Jeno. Supongo que tenemos que hablar con Jeno.",
  ui_story_5032_50320301_3_dialog_content = "Pero la última vez que lo intenté, se encerró en su cabaña y se negó a salir.",
  ui_story_5032_50320301_4_dialog_content = "Lo que pasó con Elvis lo afectó mucho. Parece que fueron amigos cercanos en el pasado.",
  ui_story_5032_50320301_5_dialog_content = "Sí. Entonces, si podemos persuadirlo para que ayude, tal vez pueda hacer que Elvis hable.",
  ui_story_5032_50320301_6_dialog_content = "...",
  ui_story_5032_50320301_7_dialog_content = "Oye, ese tipo que camina por ahí luciendo perdido... ¿podría ser Jeno?",
  ui_story_5032_50320301_8_dialog_content = "¡Oye! Jeno!",
  ui_story_5032_50320301_9_dialog_content = "Oh, son ustedes.",
  ui_story_5032_50320301_10_dialog_content = "Eres tú, Jeno.",
  ui_story_5032_50320301_11_dialog_content = "Vine a verte antes, pero... no quisiste salir.",
  ui_story_5032_50320301_12_dialog_content = "Lo siento. No estaba de buen humor.",
  ui_story_5032_50320301_13_dialog_content = "Está bien. Pero, ¿adónde vas? Pareces perdido.",
  ui_story_5032_50320301_14_dialog_content = "Decir la verdad...",
  ui_story_5032_50320301_15_dialog_content = "Quiero hablar con Elvis.",
  ui_story_5032_50320301_16_dialog_content = "¿Es aquí donde lo tienen retenido?",
  ui_story_5032_50320301_17_dialog_content = "No es lo que esperaba.",
  ui_story_5032_50320301_18_dialog_content = "\"Era noble y un laird. Tenemos que tratarlo con dignidad, al menos hasta que sea declarado culpable\".",
  ui_story_5032_50320301_19_dialog_content = "Eso es lo que dijo Carleen. Así que lo dejamos quedarse aquí.",
  ui_story_5032_50320301_20_dialog_content = "Está custodiado por Matthieu y Loewe del Salón de la Justicia y algunos guardias.",
  ui_story_5032_50320301_21_dialog_content = "Juez Matthieu, este es el hombre que Elvis ha estado pidiendo ver.",
  ui_story_5032_50320301_22_dialog_content = "Tsk, ¿este es el plebeyo? Ha estado hablando y hablando de ti. Jeno esto, Jeno aquello. Estoy harto de escucharlo.",
  ui_story_5032_50320301_23_dialog_content = "...",
  ui_story_5032_50320301_24_dialog_content = "Te lo advierto ahora, sin trucos. Si intenta algo, atacaremos sin previo aviso.",
  ui_story_5032_50320301_25_dialog_content = "Hmph.",
  ui_story_5032_50320301_26_dialog_content = "<color=#e8d9bb>Hacer clic</color>",
  ui_story_5032_50320301_27_dialog_content = "Jeno? ¿¡Eres tú, Jeno!?",
  ui_story_5032_50320301_28_dialog_content = "Por fin has venido a verme.",
  ui_story_5032_50320301_29_dialog_content = "Mmm.",
  ui_story_5032_50320301_30_dialog_content = "No malinterpretes. Solo estoy aquí para ver qué pasa con los traidores traidores.",
  ui_story_5032_50320301_31_dialog_content = "No esperaba encontrarte en un alojamiento tan cómodo.",
  ui_story_5032_50320301_32_dialog_content = "Parece injusto cuando piensas en todo el daño que le hiciste a mi Emerald.",
  ui_story_5032_50320301_33_dialog_content = "¿Sabes lo duro que tiene que trabajar todo el mundo para repararlo?",
  ui_story_5032_50320301_34_dialog_content = "Y te sientas aquí, descansando en tu habitación limpia y cómoda.",
  ui_story_5032_50320301_35_dialog_content = "Jeno, lo siento mucho.",
  ui_story_5032_50320301_36_dialog_content = "Por favor, créeme, y si tuviera otra opción, no te habría hecho daño.",
  ui_story_5032_50320301_37_dialog_content = "Pero lo hiciste. ¿No es así?",
  ui_story_5032_50320301_38_dialog_content = "Los hechos son los hechos, y no podemos cambiarlos. Entonces, ¿cuál es el punto de decir lo siento?",
  ui_story_5032_50320301_39_dialog_content = "Escuché que te negaste a comer y beber e insististe en verme.",
  ui_story_5032_50320301_40_dialog_content = "¿Qué esperas? ¿Que escucharé tus tediosas disculpas y te perdonaré por todo lo que has hecho?",
  ui_story_5032_50320301_41_dialog_content = "¿Decirme en persona cuánto te arrepientes de todo esto aliviará un poco tu conciencia?",
  ui_story_5032_50320301_42_dialog_content = "Jeno... Sé cuánto te debo.",
  ui_story_5032_50320301_43_dialog_content = "Pero hay algunas cosas que solo puedo contarte a ti.",
  ui_story_5032_50320301_44_dialog_content = "Cosas que serán significativas solo para ti.",
  ui_story_5032_50320301_45_dialog_content = "No espero que nada de lo que diga sea significativo.",
  ui_story_5032_50320301_46_dialog_content = "Mírate, Elvis. Eres patético.",
  ui_story_5032_50320301_47_dialog_content = "Sí. Sé lo bajo que he caído.",
  ui_story_5032_50320301_48_dialog_content = "Debo lucir como lo hice <color=#FFB400>esa vez me lastimé la pierna</color>, luchando contra esos matones.",
  ui_story_5032_50320301_49_dialog_content = "Recuerdo cómo te burlaste de mí.",
  ui_story_5032_50320301_50_dialog_content = "No vine aquí para recordar.",
  ui_story_5032_50320301_51_dialog_content = "Lo siento. Pensé que una vez dijiste que eras una persona nostálgica... Pensé que te gustaría recordar viejos tiempos.",
  ui_story_5032_50320301_52_dialog_content = "Después de todo, todos tienen pequeños secretos escondidos en sus recuerdos.",
  ui_story_5032_50320301_53_dialog_content = "No estoy de humor para recordar el pasado. Y ni siquiera recuerdo que te lastimaras la pierna.",
  ui_story_5032_50320301_54_dialog_content = "No, lo haces. Estoy seguro que sí.",
  ui_story_5032_50320301_55_dialog_content = "Así como sabes el significado de los secretos.",
  ui_story_5032_50320301_56_dialog_content = "¡Tonterías!",
  ui_story_5032_50320301_57_dialog_content = "Esto es inutil. Si esto es todo lo que tienes que decir, ahórrate el aliento. No me interesa.",
  ui_story_5032_50320301_58_dialog_content = "Jeno!",
  ui_story_5032_50320301_59_dialog_content = "¿Jeno salió furioso así?",
  ui_story_5032_50320301_60_dialog_content = "Parecía furioso...",
  ui_story_5032_50320301_61_dialog_content = "No conozco la historia entre ustedes dos, pero tal vez deberías intentar una disculpa más sincera.",
  ui_story_5032_50320301_62_dialog_content = "De todos modos, ¿comerás algo ahora que te dejamos ver a Jeno?",
  ui_story_5032_50320301_63_dialog_content = "Mmm. Gracias por el consejo, PlayerName.",
  ui_story_5032_50320301_64_dialog_content = "¡Elvis! ¿Estás bien?",
  ui_story_5032_50320301_65_dialog_content = "No te preocupes. Es solo mi pierna. Y no volverán a intimidarte así.",
  ui_story_5032_50320301_66_dialog_content = "Lo siento... Todo es mi culpa.",
  ui_story_5032_50320301_67_dialog_content = "Te dije que no te preocuparas por eso. Entonces, ¿es esta la base secreta que encontraste?",
  ui_story_5032_50320301_68_dialog_content = "Sí. No hay casi nadie aquí y es perfecto para pintar.",
  ui_story_5032_50320301_69_dialog_content = "¡Entremos entonces! También podría ser un lugar genial para esconder cosas. Tal vez mantendré mi diario aquí.",
  ui_story_5032_50320301_70_dialog_content = "¿eh? No sabía que tenías un diario.",
  ui_story_5032_50320301_71_dialog_content = "Sí, pero quizás empiece uno.",
  ui_story_5032_50320301_72_dialog_content = "Después de todo, una base secreta es perfecta para guardar secretos.",
  ui_story_5032_50320301_73_dialog_content = "<color=#e8d9bb>Las afueras de Harbour City</color>",
  ui_story_5032_50320301_74_dialog_content = "¿Qué has dejado aquí que tanto quieres que encuentre?",
  ui_story_5032_50320301_75_dialog_content = "Seguramente no puede ser ese estúpido diario...",
  ui_story_5032_50320301_76_dialog_content = "Graagh-!",
  ui_story_5032_50320301_77_dialog_content = "No puedo creer que haya eclipses aquí.",
  ui_story_5032_50320301_78_dialog_content = "¡Graagh!",
  ui_story_5032_50320301_79_dialog_content = "¡Muévete del camino!",
  ui_story_5032_50320302_1_dialog_content = "Graagh—",
  ui_story_5032_50320302_2_dialog_content = "Creo que ese fue el último.",
  ui_story_5032_50320302_3_dialog_content = "El árbol contra el que chocó Eclipsite era el mismo contra el que descansaba Elvis cuando se lastimó la pierna.",
  ui_story_5032_50320302_4_dialog_content = "Ha crecido tanto.",
  ui_story_5032_50320302_5_dialog_content = "Realmente hay una carta. Que cliché.",
  ui_story_5032_50320302_6_dialog_content = "¿Y se supone que debo leerlo?",
  ui_story_5032_50320302_7_dialog_content = "Las tramas secretas deberían ser un poco más creativas que esto.",
  ui_story_5032_50320302_8_dialog_content = "Debería destrozar este ridículo plan tuyo...",
  ui_story_5032_50320302_9_dialog_content = "No, tal vez debería leerlo. Podría proporcionar una buena risa.",
  ui_story_5032_50320302_10_dialog_content = "Como ya he decidido no perdonarte, ¿qué va a hacer una carta para cambiar eso?",
  ui_story_5032_50320302_11_dialog_content = "Incluso ahora, Jeno, todavía quieres saber qué patéticas excusas tiene, ¿no?",
  ui_story_5032_50320302_12_dialog_content = "Eres tan ridículo como él.",
  ui_story_5032_50320302_13_dialog_content = "Muy bien. Veré qué más tienes que decir por ti mismo.",
  ui_story_5032_50320302_14_dialog_content = "A mi querido amigo Jeno",
  ui_story_5032_50320302_15_dialog_content = "Para cuando leas esto, es posible que haya liberado a la gente de Harbor City de la maldición que sufren.",
  ui_story_5032_50320302_16_dialog_content = "O, si mi plan ha fallado, puede que me haya convertido en un prisionero.",
  ui_story_5032_50320302_17_dialog_content = "Pero cualquiera que sea el caso, necesito urgentemente su ayuda.",
  ui_story_5032_50320302_18_dialog_content = "Te lo ruego, lee esta carta hasta el final.",
  ui_story_5032_50320302_19_dialog_content = "Probablemente ya sepas que mi objetivo era el núcleo de energía de la Esmeralda.",
  ui_story_5032_50320302_20_dialog_content = "Me he preguntado una y otra vez si debo revelarte mis planes. Después de todo, hubo un tiempo en que no teníamos secretos el uno para el otro.",
  ui_story_5032_50320302_21_dialog_content = "Pero después de tantos años separados, es posible que ambos nos hayamos convertido en personas muy diferentes.",
  ui_story_5032_50320302_22_dialog_content = "Y años de jugar juegos políticos me han hecho desconfiar de confiar en los demás.",
  ui_story_5032_50320302_23_dialog_content = "Incluso cuando nos volvimos a encontrar, todavía no me atrevía a confiar plenamente en ti.",
  ui_story_5032_50320302_24_dialog_content = "Fue entonces cuando lo vi en tus ojos: la Esmeralda es más que un mero barco para ti.",
  ui_story_5032_50320302_25_dialog_content = "Se ha convertido en un hogar. Un hogar para ti, para tu familia y para tus amigos.",
  ui_story_5032_50320302_26_dialog_content = "Y te has convertido en miembro de True Order.",
  ui_story_5032_50320302_27_dialog_content = "No puedo decirte la verdad, ni asumir las consecuencias si otras fuerzas aprenden sobre el núcleo de energía.",
  ui_story_5032_50320302_28_dialog_content = "Es la última esperanza para Harbor City y esas pobres almas malditas que viven aquí.",
  ui_story_5032_50320302_29_dialog_content = "los <color=#FFB400>Piedra de viento</color>El sello de se está debilitando. Si eso continúa, Harbour City está condenada a la destrucción.",
  ui_story_5032_50320302_30_dialog_content = "Necesito tu ayuda y prometo explicarte todo en persona. Pero debo completar el ritual tan pronto como puedas.",
  ui_story_5032_50320302_31_dialog_content = "Espero que le eches una mano a este lugar, tu antiguo hogar. Y yo, tu antiguo amigo.",
  ui_story_5032_50320302_32_dialog_content = "¿Era esto lo que querías decir?",
  ui_story_5032_50320302_33_dialog_content = "¿Crees que puedes volver a engañarme con una simple carta?",
  ui_story_5032_50320302_34_dialog_content = "¿Crees que te perdonaré ahora?",
  ui_story_5032_50320302_35_dialog_content = "<color=#e8d9bb>Tzzst—</color>",
  ui_story_5032_50320302_36_dialog_content = "Tonto, Elvis.",
  ui_story_5032_50320401_1_dialog_content = "Carleen, estamos de vuelta.",
  ui_story_5032_50320401_2_dialog_content = "Bienvenido de nuevo. ¿Como le fue?",
  ui_story_5032_50320401_3_dialog_content = "¿Y dónde está Jeno? Pensé que estaría contigo.",
  ui_story_5032_50320401_4_dialog_content = "Luchó con Elvis y luego se fue. No pudimos detenerlo.",
  ui_story_5032_50320401_5_dialog_content = "Supuse tanto. Debe tener muchas cosas en mente en este momento...",
  ui_story_5032_50320401_6_dialog_content = "Después de todo lo que ha pasado, probablemente necesite un tiempo a solas para pensar bien las cosas.",
  ui_story_5032_50320401_7_dialog_content = "Deberíamos darle ese espacio.",
  ui_story_5032_50320401_8_dialog_content = "Sigo pensando que Elvis nos está ocultando algo importante.",
  ui_story_5032_50320401_9_dialog_content = "Pero no tenemos idea de lo que está pasando dentro de su cabeza.",
  ui_story_5032_50320401_10_dialog_content = "Sí...",
  ui_story_5032_50320401_11_dialog_content = "Carleen, ¿tienes alguna idea?",
  ui_story_5032_50320401_12_dialog_content = "Lo más importante en este momento es descubrir qué estaba haciendo Elvis y por qué los Eclipsites comenzaron a aparecer.",
  ui_story_5032_50320401_13_dialog_content = "Aquí hay una conjetura. El aumento de eclipses podría estar relacionado con ese sello que mencionó Elvis.",
  ui_story_5032_50320401_14_dialog_content = "Bueno, como no nos va a decir nada, tendremos que encontrar otra manera de llegar al fondo de esto.",
  ui_story_5032_50320401_15_dialog_content = "Pero donde empezamos?",
  ui_story_5032_50320401_16_dialog_content = "Recuerdo algo que Elvis dijo una vez:",
  ui_story_5032_50320401_17_dialog_content = "También encontrará la información que necesita, una vez que haya leído detenidamente todos los libros de este mundo.",
  ui_story_5032_50320401_18_dialog_content = "Entonces, ¿qué se supone que debemos hacer? ¿Leer todos los libros de Astra?",
  ui_story_5032_50320401_19_dialog_content = "No. Sólo todos los libros que Elvis leyó alguna vez.",
  ui_story_5032_50320401_20_dialog_content = "Recuerdo que había una pequeña biblioteca en su mansión. Deberíamos poder encontrar algunas pistas allí.",
  ui_story_5032_50320401_21_dialog_content = "Vendré y ayudaré. Un par de ojos extra acelerará las cosas.",
  ui_story_5032_50320401_22_dialog_content = "Sí yo también.",
  ui_story_5032_50320401_23_dialog_content = "<color=#e8d9bb>La biblioteca, la mansión de Elvis</color>",
  ui_story_5032_50320401_24_dialog_content = "Tú... ¿¡Llamas a esto una pequeña biblioteca!?",
  ui_story_5032_50320401_25_dialog_content = "Quiero decir, la habitación no es muy grande...",
  ui_story_5032_50320401_26_dialog_content = "Pero está lleno de estanterías. Y las estanterías están repletas de libros.",
  ui_story_5032_50320401_27_dialog_content = "Nos tomará un año leer todo esto. ¡No, dos años, mínimo!",
  ui_story_5032_50320401_28_dialog_content = "Y mira, los libros se están cayendo a pedazos. Elvis debe haberlos leído una y otra vez.",
  ui_story_5032_50320401_29_dialog_content = "¿Qué esperaba aprender de ellos?",
  ui_story_5032_50320401_30_option_content = "¿Quizás estaba estudiando historia?",
  ui_story_5032_50320401_31_dialog_content = "Elvis quería curar el síndrome de Modali, por lo que probablemente estaba buscando pistas sobre el linaje heroico.",
  ui_story_5032_50320401_32_dialog_content = "El linaje heroico tiene profundas raíces en la historia de Harbor City.",
  ui_story_5032_50320401_33_dialog_content = "Si quisiera aprender sobre el síndrome de Modali, comenzaría con la historia de Harbor City.",
  ui_story_5032_50320401_34_dialog_content = "Eso es cierto. Es una historia llena de misterios sin resolver.",
  ui_story_5032_50320401_35_dialog_content = "¿Quizás uno de esos misterios tiene algo que ver con el síndrome de Modali?",
  ui_story_5032_50320401_36_option_content = "¿Quizás estaba investigando el síndrome de Modali?",
  ui_story_5032_50320401_37_dialog_content = "Le importaba más eso que cualquier otra cosa, ¿no?",
  ui_story_5032_50320401_38_dialog_content = "La enfermedad que padece él, así como quién sabe cuántos ciudadanos de Harbor City.",
  ui_story_5032_50320401_39_dialog_content = "Pero los académicos han estado tratando de descubrir qué lo causa durante años y aún no han llegado a ninguna parte.",
  ui_story_5032_50320401_40_dialog_content = "¿Dónde empezaría a mirar Elvis?",
  ui_story_5032_50320401_41_dialog_content = "Bueno, es una enfermedad local. Entonces, el mejor enfoque podría ser mirar la historia local.",
  ui_story_5032_50320401_42_dialog_content = "Entonces empecemos con los libros de historia.",
  ui_story_5032_50320401_43_dialog_content = "Bueno. ¡Reuniré todos los libros de historia y ustedes pueden comenzar a leerlos!",
  ui_story_5032_50320401_44_dialog_content = "¡Dejanoslo a nosotros!",
  ui_story_5032_50320401_45_dialog_content = "Las Crónicas de Astra, La Enciclopedia de la Historia, La Historia Secreta de Lumopolis...",
  ui_story_5032_50320401_46_dialog_content = "¿Eh? ¿Y por qué hay una copia de The Legendary Heroes of Harbour City en el estante de historia?",
  ui_story_5032_50320401_47_dialog_content = "¿No es esto más un libro de mitología? Lo que sea, lo traeré.",
  ui_story_5032_50320401_48_dialog_content = "Vice, Carleen, aquí están los libros.",
  ui_story_5032_50320401_49_dialog_content = "Vale, ponlas aquí y empezamos a leer.",
  ui_story_5032_50320401_50_dialog_content = "Gracias, PlayerName.",
  ui_story_5032_50320401_51_dialog_content = "No hay problema. Creo que hay más libros de historia por ahí. Iré y comprobaré.",
  ui_story_5032_50320401_52_dialog_content = "<color=#e8d9bb>Algún tiempo después</color>",
  ui_story_5032_50320401_53_dialog_content = "Uf. Vale, estos son todos los libros con la palabra \"historia\" en el título y todo lo que parezca... ya sabes, histórico.",
  ui_story_5032_50320401_54_dialog_content = "¿Cómo va? ¿Ya encontraste algo?",
  ui_story_5032_50320401_55_dialog_content = "Hay algo extraño en estos libros. Los de Harbor City están todos de acuerdo en su historia temprana.",
  ui_story_5032_50320401_56_dialog_content = "Pero tan pronto como leemos los fragmentos más recientes, todos divergen.",
  ui_story_5032_50320401_57_dialog_content = "Y ni siquiera se lee como historia. Es más como historias inventadas.",
  ui_story_5032_50320401_58_dialog_content = "Sí. Como este, The Chronicles of Astra, dice esto:",
  ui_story_5032_50320401_59_dialog_content = "\"Había una vez una sangrienta batalla entre los antiguos héroes y los Eclipsites cerca de Harbor City\".",
  ui_story_5032_50320401_60_dialog_content = "\"Los odiosos espíritus de los Eclipsites se convirtieron en una maldición que atormentó a los descendientes de los héroes\".",
  ui_story_5032_50320401_61_dialog_content = "¿No es esa la leyenda que escuchamos inicialmente?",
  ui_story_5032_50320401_62_dialog_content = "Pero es solo una leyenda, ¿verdad? Si las maldiciones realmente existieran, el mundo entero caería en el caos...",
  ui_story_5032_50320401_63_dialog_content = "Ese al menos suena medio creíble. Este, The Legendary Heroes of Harbour City, es aún más raro.",
  ui_story_5032_50320401_64_dialog_content = "\"Harbor City está protegida por los héroes de antaño y, por lo tanto, los Eclipsites no la molestan\".",
  ui_story_5032_50320401_65_dialog_content = "\"Aunque los eclipses pueden acercarse a la ciudad, pronto los héroes los eliminan silenciosamente\".",
  ui_story_5032_50320401_66_dialog_content = "¡Eso es extraño!",
  ui_story_5032_50320401_67_dialog_content = "Lo sé, ¿cierto?",
  ui_story_5032_50320401_68_dialog_content = "¿eh? Este libro dice...",
  ui_story_5032_50320401_69_dialog_content = "Vice, ¿qué tienes?",
  ui_story_5032_50320401_70_dialog_content = "Es La historia secreta de Lumopolis. Dice que los residentes de Harbor City excavaron una vez un sitio de ruinas antiguas.",
  ui_story_5032_50320401_71_dialog_content = "Y en ruinas, encontraron una piedra extraña. Y si la piedra estuviera infundida con Lumina, podría <color=#FFB400>repeler eclipses cercanos</color>.",
  ui_story_5032_50320401_72_dialog_content = "Eso suena familiar. Sería como una versión en miniatura de la barrera de Lumopolis.",
  ui_story_5032_50320401_73_dialog_content = "no interrumpas, PlayerName. no he terminado",
  ui_story_5032_50320401_74_dialog_content = "Oh, lo siento. ¿Qué pasó después?",
  ui_story_5032_50320401_75_dialog_content = "Esto es lo que dice—",
  ui_story_5032_50320401_76_dialog_content = "\"Pero como la piedra requería <color=#FFB400>demasiada lumina</color> funcionar, ninguna fuente podría mantenerlo funcionando constantemente\".",
  ui_story_5032_50320401_77_dialog_content = "\"Y así llegó a considerarse sin valor y luego se perdió\".",
  ui_story_5032_50320401_78_dialog_content = "Suena como una leyenda sin sentido. Seguir mirando.",
  ui_story_5032_50320401_79_dialog_content = "Aunque... ¿El poder que repele a los Eclipsitos? Eso me recuerda algo que leí en un libro en Lumopolis.",
  ui_story_5032_50320401_80_dialog_content = "En algún momento del pasado, una horda de Eclipsites se reunió en el área de Harbor City. Los residentes lucharon y sufrieron por ellos durante años.",
  ui_story_5032_50320401_81_dialog_content = "Entonces, un día, los Eclipsites de repente desaparecieron y la ciudad fue libre para prosperar.",
  ui_story_5032_50320401_82_dialog_content = "Entonces, ¿qué los hizo desaparecer?",
  ui_story_5032_50320401_83_dialog_content = "Ni idea. Supongo que es solo uno de esos misterios sin resolver de Harbor City.",
  ui_story_5032_50320401_84_dialog_content = "Ay, mi cuello. He estado leyendo tanto tiempo que se ha vuelto rígido.",
  ui_story_5032_50320401_85_dialog_content = "Tomar un descanso. Leeré el resto por ti.",
  ui_story_5032_50320401_86_dialog_content = "Oh gracias, PlayerName.",
  ui_story_5032_50320401_87_dialog_content = "Voy a tomar una siesta contra este libro cas—¡¡woah!!",
  ui_story_5032_50320401_88_dialog_content = "¿Qué ocurre? ¿Te chocaste con algo?",
  ui_story_5032_50320401_89_dialog_content = "N-no. Acabo de empujar accidentalmente uno de estos libros.",
  ui_story_5032_50320401_90_dialog_content = "¿Es un terremoto?",
  ui_story_5032_50320401_91_dialog_content = "No, no lo es.",
  ui_story_5032_50320401_92_dialog_content = "Mira, es esa pared de allí. ¡Se está moviendo!",
  ui_story_5032_50320401_93_dialog_content = "Y mira, hay algo detrás de la pared. Su...",
  ui_story_5032_50320401_94_dialog_content = "¿Una mesa llena de documentos escritos a mano?",
  ui_story_5032_50320401_95_dialog_content = "Si Elvis los escondió con tanto cuidado, deben ser importantes.",
  ui_story_5032_50320401_96_dialog_content = "Y nunca hubiéramos encontrado la habitación secreta si no fuera por la buena suerte de Vice.",
  ui_story_5032_50320401_97_dialog_content = "Veamos qué dicen estos documentos.",
  ui_story_5032_50320401_98_dialog_content = "Las páginas de arriba han sido amarillentas. Deben ser mayores.",
  ui_story_5032_50320401_99_dialog_content = "Por la presente empiezo mi investigación sobre Windstone. No solo por mí sino por el futuro de los ciudadanos de Harbor City.",
  ui_story_5032_50320401_100_dialog_content = "Es la letra de Elvis. Realmente estaba haciendo una investigación secreta. Pero, ¿qué es el Windstone?",
  ui_story_5032_50320401_101_dialog_content = "No sé. Pero si lo está estudiando, ¡debería haber más información más adelante!",
  ui_story_5032_50320401_102_dialog_content = "Mi investigación ha encontrado que Windstone contiene un dispositivo que puede almacenar energía.",
  ui_story_5032_50320401_103_dialog_content = "Su reserva de energía y los suministros intermitentes de Lumina de los Aurorianos han logrado mantenerlo operativo hasta la fecha.",
  ui_story_5032_50320401_104_dialog_content = "Pero está consumiendo más energía de la que puede suministrar, y su reserva de energía está casi agotada.",
  ui_story_5032_50320401_105_dialog_content = "Puedo sentir que el poder de Windstone se debilita, y estamos empezando a ver aparecer eclipses cerca de Harbor City.",
  ui_story_5032_50320401_106_dialog_content = "Si esto continúa, no pasará mucho tiempo antes de que la ciudad vuelva a verse plagada de eclipses.",
  ui_story_5032_50320401_107_dialog_content = "El tiempo corre. Debo pensar en algo.",
  ui_story_5032_50320401_108_dialog_content = "Entonces parece que Windstone es una especie de aparato con poderes especiales.",
  ui_story_5032_50320401_109_dialog_content = "Entonces, ¿podría ser por eso que Harbor City estuvo a salvo de los eclipses durante tanto tiempo?",
  ui_story_5032_50320401_110_dialog_content = "Lo que se describe aquí ciertamente coincide con la situación real de Harbor City.",
  ui_story_5032_50320401_111_dialog_content = "En el pasado, ningún Eclipsite ha puesto un pie en Harbor City. Pero recientemente, ha habido muchos informes de Eclipsitas atacando aurorianos.",
  ui_story_5032_50320401_112_dialog_content = "Si el debilitamiento del llamado Windstone es la causa, este fenómeno no es un buen augurio.",
  ui_story_5032_50320401_113_dialog_content = "Sigamos leyendo. Los documentos a continuación parecen más nuevos, por lo que la escritura debería ser más reciente.",
  ui_story_5032_50320401_114_dialog_content = "Hojeé todos los libros de historia que pude encontrar, buscando el origen de Windstone.",
  ui_story_5032_50320401_115_dialog_content = "Mis antepasados desenterraron Windstone en las ruinas y descubrieron que tiene un gran poder, suficiente para sellar los Eclipsites.",
  ui_story_5032_50320401_116_dialog_content = "Para proteger la patria, hicieron un pacto de sangre con Windstone y suministraron el Lumina que necesitaba para operar.",
  ui_story_5032_50320401_117_dialog_content = "Y así, el poder de Windstone puso a los Eclipsites que acosaban a Harbour City en un sueño profundo.",
  ui_story_5032_50320401_118_dialog_content = "Pero si Windstone deja de funcionar, los Eclipsites se despertarán y saquearán Harbour City nuevamente.",
  ui_story_5032_50320401_119_dialog_content = "El sello y el pacto de sangre... Eso suena como el poder mencionado en ese libro.",
  ui_story_5032_50320401_120_dialog_content = "¿No es un rumor sin fundamento?",
  ui_story_5032_50320401_121_dialog_content = "Y supuestamente, Windstone necesitaba un enorme Lumina para funcionar, así que lo abandonaron.",
  ui_story_5032_50320401_122_dialog_content = "Sigamos avanzando.",
  ui_story_5032_50320401_123_dialog_content = "La investigación finalmente avanzó.",
  ui_story_5032_50320401_124_dialog_content = "Windstone puede identificar a los contratistas y sus parientes consanguíneos, así como absorber automáticamente Lumina de dichos Aurorianos.",
  ui_story_5032_50320401_125_dialog_content = "Ahora que la piedra está casi agotada, comienza a absorber a Lumina sin restricciones.",
  ui_story_5032_50320401_126_dialog_content = "Pero incluso si pudiera tomar todo de esos Aurorianos, aún no tendrá suficiente Lumina.",
  ui_story_5032_50320401_127_dialog_content = "Cuando finalmente se agote el suministro, todos los Aurorianos nacidos de esa línea de sangre morirán por la pérdida de Lumina.",
  ui_story_5032_50320401_128_dialog_content = "Eh... no me digas...",
  ui_story_5032_50320401_129_dialog_content = "Esa es probablemente la raíz del síndrome de Modali.",
  ui_story_5032_50320401_130_dialog_content = "Elvis... y su clan están usando su Lumina e incluso sus vidas para alimentar el Windstone.",
  ui_story_5032_50320401_131_dialog_content = "¿Pero por qué? ¿No hay mejor manera?",
  ui_story_5032_50320401_132_dialog_content = "Elvis nunca se lo informó a Lumopolis como el laird de Harbor City.",
  ui_story_5032_50320401_133_dialog_content = "¿Por qué tendría que hacer eso?",
  ui_story_5032_50320401_134_dialog_content = "El Windstone se está debilitando aún más. Peor aún, Lumopolis ha iniciado una investigación encubierta de Harbor City.",
  ui_story_5032_50320401_135_dialog_content = "Windstone es probablemente solo un juguete interesante para los nobles de Lumo.",
  ui_story_5032_50320401_136_dialog_content = "Lo mismo ocurre con los científicos de Illumina. Una vez que se conozca la presencia de Windstone, seguramente enviarán gente para apoderarse de ella.",
  ui_story_5032_50320401_137_dialog_content = "Para Harbor City, la piedra es la base de su existencia, lo fundamental que evita que las personas sean desplazadas.",
  ui_story_5032_50320401_138_dialog_content = "Debo guardarlo en un lugar absolutamente seguro e insospechado para que los extraños no se enteren.",
  ui_story_5032_50320401_139_dialog_content = "La buena noticia es que hay un gran avance en el estudio.",
  ui_story_5032_50320401_140_dialog_content = "Después de innumerables fallas, finalmente encontré una manera de que la piedra fuera alimentada por otra fuente.",
  ui_story_5032_50320401_141_dialog_content = "Todo lo que queda ahora es ir al terreno sellado para reiniciarlo.",
  ui_story_5032_50320401_142_dialog_content = "Ese es el último pasaje, escrito a toda prisa.",
  ui_story_5032_50320401_143_dialog_content = "En algún lugar absolutamente seguro... ¿Puede esa extraña roca en el cetro de Elvis ser el Windstone real?",
  ui_story_5032_50320401_144_dialog_content = "¿Es Lumopolis tan poco fiable para ti, Elvis?",
  ui_story_5032_50320401_145_dialog_content = "Carleen...",
  ui_story_5032_50320401_146_dialog_content = "Explícaselo a Elvis cuando tengas la oportunidad.",
  ui_story_5032_50320401_147_dialog_content = "¡Vice y yo podemos demostrar que eres una persona de confianza!",
  ui_story_5032_50320401_148_dialog_content = "Muy bien, gracias.",
  ui_story_5032_50320401_149_dialog_content = "El manuscrito terminaba con Elvis diciendo que encontró una manera de que Windstone usara otra fuente de energía.",
  ui_story_5032_50320401_150_dialog_content = "Windstone, Lumina, energía masiva...",
  ui_story_5032_50320401_151_dialog_content = "Lo tengo. Quería que el núcleo de energía de la nave del circo alimentara la piedra.",
  ui_story_5032_50320401_152_dialog_content = "Por eso buscó el núcleo aun a costa de romper con amigos...",
  ui_story_5032_50320401_153_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5032_50320401_154_dialog_content = "¡Rápido, allí!",
  ui_story_5032_50320401_155_dialog_content = "¿Que esta pasando? ¿Por qué todo el ruido?",
  ui_story_5032_50320401_156_dialog_content = "¡Detén a ese hombre! ¡Se escapó de la cárcel!",
  ui_story_5032_50320401_157_dialog_content = "¿Una fuga de la prisión?",
  ui_story_5032_50320401_158_dialog_content = "¡¿No me digas que es Elvis?!",
  ui_story_5032_50320401_159_dialog_content = "¡Vamos, vamos a comprobar!",
  ui_story_5032_50320501_1_dialog_content = "Por favor, mantenga sus ojos en el sospechoso.",
  ui_story_5032_50320501_2_dialog_content = "Tengo que salir por media hora.",
  ui_story_5032_50320501_3_dialog_content = "¿Vas a ducharte de nuevo?",
  ui_story_5032_50320501_4_dialog_content = "Harbour City está tan húmedo y sofocante ahora.",
  ui_story_5032_50320501_5_dialog_content = "De todos modos, estarás cubierto de sudor pegajoso después de tomar una ducha.",
  ui_story_5032_50320501_6_dialog_content = "¿La cuarta vez? ¿Para hoy?",
  ui_story_5032_50320501_7_dialog_content = "No me importa que tomes uno y lo agregues a mi cuenta.",
  ui_story_5032_50320501_8_dialog_content = "Soy juez auxiliar.",
  ui_story_5032_50320501_9_dialog_content = "No no. Técnicamente, eres un asistente de juez bastante maloliente.",
  ui_story_5032_50320501_10_dialog_content = "¡¡!!",
  ui_story_5032_50320501_11_dialog_content = "¿Eh? ¿Estás nervioso?",
  ui_story_5032_50320501_12_dialog_content = "No importa. Me voy a duchar, te guste o no.",
  ui_story_5032_50320501_13_dialog_content = "Mantén tus ojos pegados al laird.",
  ui_story_5032_50320501_14_dialog_content = "Sin embargo, eso podría ser discutible. Incluso tiene problemas para ponerse de pie sin su cetro.",
  ui_story_5032_50320501_15_dialog_content = "Quién sabe si podría llegar a la corte...",
  ui_story_5032_50320501_16_dialog_content = "...",
  ui_story_5032_50320501_17_dialog_content = "¿Jeno recogerá la carta que le dejé?",
  ui_story_5032_50320501_18_dialog_content = "O nada en absoluto, o tal vez todavía no me perdonará después de leerlo.",
  ui_story_5032_50320501_19_dialog_content = "Sé que sigo traicionando tu confianza, así que no debería tener ninguna esperanza.",
  ui_story_5032_50320501_20_dialog_content = "Lo siento, Jeno... Pero eres el único que puede ayudarnos a la gente de Harbor City ya mí.",
  ui_story_5032_50320501_21_dialog_content = "<color=#e8d9bb>Clic.</color>",
  ui_story_5032_50320501_22_dialog_content = "¿Terminaste de murmurar?",
  ui_story_5032_50320501_23_dialog_content = "Si es así, ven conmigo.",
  ui_story_5032_50320501_24_dialog_content = "Jeno!",
  ui_story_5032_50320501_25_dialog_content = "No te emociones demasiado allí.",
  ui_story_5032_50320501_26_dialog_content = "Tienes que decirme todo, además de lo que planeas hacer a continuación.",
  ui_story_5032_50320501_27_dialog_content = "O te arrojaré de vuelta aquí yo mismo.",
  ui_story_5032_50320501_28_dialog_content = "...",
  ui_story_5032_50320501_29_dialog_content = "¿Por qué los guardias no atacan ni dan las alarmas?",
  ui_story_5032_50320501_30_dialog_content = "Ni siquiera nos miran, como si no pasara nada.",
  ui_story_5032_50320501_31_dialog_content = "Tal es el poder de la Baraja Origen. Les hace alucinar.",
  ui_story_5032_50320501_32_dialog_content = "Pero los guardias, sin embargo, son demasiado complacientes, y eso me dio la apertura.",
  ui_story_5032_50320501_33_dialog_content = "Solo el juez de Lumopolis me hizo trabajar un poco.",
  ui_story_5032_50320501_34_dialog_content = "Supongo que no esperaban que nadie te sacara.",
  ui_story_5032_50320501_35_dialog_content = "Jaja, lástima que se equivocaron.",
  ui_story_5032_50320501_36_dialog_content = "Alucinación, dijiste. Entonces, ¿qué otras cosas interesantes puedes hacer con el poder \"Origen\"?",
  ui_story_5032_50320501_37_dialog_content = "Deja de endulzarme. Todavía quiero una explicación tuya.",
  ui_story_5032_50320501_38_dialog_content = "Ni siquiera estoy seguro de que te perdonaré todavía.",
  ui_story_5032_50320501_39_dialog_content = "Pero por lo que dijo Lady Victoria...",
  ui_story_5032_50320501_40_dialog_content = "El Origin Deck es polivalente cuando se trata de <color=#FFB400>conversión de energía</color>.",
  ui_story_5032_50320501_41_dialog_content = "Todavía tengo que dominar muchos usos. Es verdaderamente una buena herramienta para el mago.",
  ui_story_5032_50320501_42_dialog_content = "Pero los guardias se despertarán pronto y se darán cuenta de que te has ido.",
  ui_story_5032_50320501_43_dialog_content = "Muy interesante. Realmente me gustaría ver una actuación en algún momento.",
  ui_story_5032_50320501_44_dialog_content = "Seguro que tendré una oportunidad en el futuro.",
  ui_story_5032_50320501_45_dialog_content = "Tenga la seguridad de que he decidido sincerarse con usted.",
  ui_story_5032_50320501_46_dialog_content = "El solo hecho de saber que no tengo que esconder nada cuando te hable de ahora en adelante me hace muy feliz.",
  ui_story_5032_50320501_47_dialog_content = "Deberías saber que sigues siendo el laird y que tenemos un gran lío que arreglar.",
  ui_story_5032_50320501_48_dialog_content = "Así que deja de tratar de resolver los problemas por la fuerza como cuando eras niño.",
  ui_story_5032_50320501_49_dialog_content = "Por supuesto. ¡Ya te dije que te lo contaría todo!",
  ui_story_5032_50320501_50_dialog_content = "¡Oye! ¡Despierta, Loewe!",
  ui_story_5032_50320501_51_dialog_content = "Humph, no se levanta.",
  ui_story_5032_50320501_52_dialog_content = "El malvado Elvis... ¡Ese payaso Jeno debe haber hecho esto!",
  ui_story_5032_50320501_53_dialog_content = "Avergonzarme así... ¡No escapará aunque seas el laird!",
  ui_story_5032_50320501_54_dialog_content = "Lo atraparé y luego lo romperé en pedazos.",
  ui_story_5032_50320501_55_dialog_content = "¡Entonces limpia mis zapatos con esa molesta cara suya!",
  ui_story_5032_50320501_56_dialog_content = "¡Todos los guardias, recojan a Loewe y vengan conmigo a cazar al fugitivo!",
  ui_story_5032_50320501_57_dialog_content = "¡Sí señor!",
  ui_story_5032_50320501_58_dialog_content = "¡Juez Matthieu!",
  ui_story_5032_50320501_59_dialog_content = "¿Qué está pasando?",
  ui_story_5032_50320501_60_dialog_content = "¿Qué está pasando, preguntas?",
  ui_story_5032_50320501_61_dialog_content = "No sentenciar a un criminal sino tratarlo como un invitado de honor.",
  ui_story_5032_50320501_62_dialog_content = "¿Hay algo peor que dejarlo escapar?",
  ui_story_5032_50320501_63_dialog_content = "Tu estas diciendo...",
  ui_story_5032_50320501_64_dialog_content = "Sí, Elvis escapó.",
  ui_story_5032_50320501_65_dialog_content = "¡Y es muy probable que Jeno haya ayudado!",
  ui_story_5032_50320501_66_dialog_content = "Le recordé, Su Alteza, trasladar al criminal a Lumopolis lo antes posible.",
  ui_story_5032_50320501_67_dialog_content = "Disculpe, pero tenemos que atrapar a un fugitivo, ¡así que no se interpongan en mi camino!",
  ui_story_5032_50320501_68_dialog_content = "El juez Matthieu parece lívido.",
  ui_story_5032_50320501_69_dialog_content = "Eso es comprensible. También ha asumido muchas responsabilidades por apoyar mi investigación sobre Elvis.",
  ui_story_5032_50320501_70_dialog_content = "Debemos actuar ahora y atrapar a Elvis.",
  ui_story_5032_50320501_71_dialog_content = "Según las pistas que tenemos, Elvis debería estar buscando reiniciar Windstone.",
  ui_story_5032_50320501_72_dialog_content = "Sí, ya que por eso fue tras el núcleo de energía antes de que lo frustraran.",
  ui_story_5032_50320501_73_dialog_content = "Ahora que está libre, debe dirigirse al terreno sellado.",
  ui_story_5032_50320501_74_dialog_content = "Eso no es definitivo, podría estar escondiéndose porque pensó que nos enteramos de su plan.",
  ui_story_5032_50320501_75_dialog_content = "De todos modos, tenemos que ir allí también.",
  ui_story_5032_50320501_76_dialog_content = "¿Estás dispuesta a esto, Carleen?",
  ui_story_5032_50320501_77_dialog_content = "Estoy bien, no te preocupes.",
  ui_story_5032_50320501_78_dialog_content = "Sin mencionar que tenemos cosas que decirle en persona.",
  ui_story_5032_50320502_1_dialog_content = "¡Cuidado!",
  ui_story_5032_50320502_2_dialog_content = "¡Graaah!",
  ui_story_5032_50320502_3_dialog_content = "Tenemos más eclipses que antes.",
  ui_story_5032_50320502_4_dialog_content = "Aunque no estamos muy lejos de Harbor City.",
  ui_story_5032_50320502_5_dialog_content = "Estos eclipses... ¿Podría ser que Windstone se esté debilitando?",
  ui_story_5032_50320502_6_dialog_content = "¡Enfoque! Estamos casi en el <color=#FFB400>tierra sellada</color> marcado en las notas de Elvis!",
  ui_story_5032_50320502_7_dialog_content = "¡Entendido!",
  ui_story_5032_50320502_8_dialog_content = "Todos los misterios se resolverán allí.",
  ui_story_5032_50320502_9_dialog_content = "¿Es esto?",
  ui_story_5032_50320502_10_dialog_content = "Sí. Los ancestros iniciaron la Piedra del Viento aquí para sellar los Eclipsitos.",
  ui_story_5032_50320502_11_dialog_content = "Confío en reiniciar la piedra a través del dispositivo aquí.",
  ui_story_5032_50320502_12_dialog_content = "Pero no seré molestado durante el proceso, así que necesito su ayuda.",
  ui_story_5032_50320502_13_dialog_content = "Entiendo.",
  ui_story_5032_50320502_14_dialog_content = "Creeré que estás haciendo esto por el bien de la gente de Harbor City, por ahora.",
  ui_story_5032_50320502_15_dialog_content = "<size=30>Al menos se ajusta a lo que siempre he pensado de ti en mi mente.</size>",
  ui_story_5032_50320502_16_dialog_content = "¿Qué es eso, Jeno?",
  ui_story_5032_50320502_17_dialog_content = "Nada. Si lo que dices es cierto, te ayudaré por ti y por Harbor City.",
  ui_story_5032_50320502_18_dialog_content = "Ahora no tengo nada que ocultarte, así que confía en mí, Jeno.",
  ui_story_5032_50320502_19_dialog_content = "También, gracias, Jeno.",
  ui_story_5032_50320502_20_dialog_content = "¡Elvis! Jeno!",
  ui_story_5032_50320502_21_dialog_content = "Ahí está, Su Alteza.",
  ui_story_5032_50320502_22_dialog_content = "Viniste aquí después de todo, Elvis.",
  ui_story_5032_50320502_23_dialog_content = "Veo Vice y PlayerName han venido también, todos rostros familiares y tranquilizadores.",
  ui_story_5032_50320502_24_dialog_content = "No deberías moverte en tu condición, Elvis.",
  ui_story_5032_50320502_25_dialog_content = "Lo sé, Señorita Antivicio. Aprecio tu preocupación por un criminal como yo.",
  ui_story_5032_50320502_26_dialog_content = "Pero tengo algo que debo hacer.",
  ui_story_5032_50320502_27_dialog_content = "Ya que estás aquí, supongo que has leído mis notas en la biblioteca.",
  ui_story_5032_50320502_28_dialog_content = "En seguida.",
  ui_story_5032_50320502_29_dialog_content = "Conocemos su intención de utilizar el núcleo de energía de la Esmeralda para impulsar la Piedra del Viento.",
  ui_story_5032_50320502_30_dialog_content = "También conocemos el propósito de la piedra, específicamente lo importante que es para Harbor City.",
  ui_story_5032_50320502_31_dialog_content = "Pero tu buena intención no puede cubrir tu culpa.",
  ui_story_5032_50320502_32_dialog_content = "Sabía que no podía ocultártelo.",
  ui_story_5032_50320502_33_dialog_content = "Sin embargo, dado que ya descubriste mi plan, no tengo nada más que ocultar.",
  ui_story_5032_50320502_34_dialog_content = "Estás bien. soy un criminal",
  ui_story_5032_50320502_35_dialog_content = "Pero no tengo muchas opciones cuando se trata de proteger a la gente de Harbour City, los cimientos de la ciudad y Windstone.",
  ui_story_5032_50320502_36_dialog_content = "Si no fuera por la disminución del poder de la línea de sangre y el Windstone corriendo en humo...",
  ui_story_5032_50320502_37_dialog_content = "Tal vez podría encontrar otra manera mejor.",
  ui_story_5032_50320502_38_dialog_content = "Pero me estoy quedando sin tiempo con mi propio cuerpo, así como con Eclipsites.",
  ui_story_5032_50320502_39_dialog_content = "No puedo arriesgarme a encontrar la solución óptima o morir primero del síndrome de Modali.",
  ui_story_5032_50320502_40_dialog_content = "Lo único que sé es cambiar mis últimos momentos por el futuro de Harbor City.",
  ui_story_5032_50320502_41_dialog_content = "Usted y Caelestite son la mayor variable en mi plan, Su Alteza.",
  ui_story_5032_50320502_42_dialog_content = "Esperaba retrasarte antes de venir aquí a recargar la piedra.",
  ui_story_5032_50320502_43_dialog_content = "Pero ni siquiera el <color=#FFB400>lumothread</color> diseñado específicamente para usted podría detenerlo.",
  ui_story_5032_50320502_44_dialog_content = "...",
  ui_story_5032_50320502_45_dialog_content = "Disculpe, pero ¿sigue usando ese vestido?",
  ui_story_5032_50320502_46_dialog_content = "Todavía debería estar absorbiendo tu Lumina.",
  ui_story_5032_50320502_47_dialog_content = "Sí, probablemente alcanzó el límite la última vez.",
  ui_story_5032_50320502_48_dialog_content = "PlayerName Podía sentir la Lumina dentro del vestido disiparse en parte todos los días antes de que absorbiera más de mí.",
  ui_story_5032_50320502_49_dialog_content = "De hecho, trato una absorción tan débil como un medio para ejercer control sobre Lumina ahora.",
  ui_story_5032_50320502_50_dialog_content = "Entonces, ¿Lumothread ahora es solo una parte del entrenamiento para controlar Lumina para ti...?",
  ui_story_5032_50320502_51_dialog_content = "Qué asombroso...",
  ui_story_5032_50320502_52_dialog_content = "Sé que no tengo derecho a hacer ningún pedido por lo que he hecho, Su Alteza.",
  ui_story_5032_50320502_53_dialog_content = "Pero igual te lo ruego...",
  ui_story_5032_50320502_54_dialog_content = "Permíteme recargar el Windstone antes de llevarme.",
  ui_story_5032_50320502_55_dialog_content = "Creo que usted y el Salón de Justicia me darán un juicio justo.",
  ui_story_5032_50320502_56_dialog_content = "Pero tengo una misión que yo, Elvis Modali, debo cumplir.",
  ui_story_5032_50320502_57_dialog_content = "Y esa es mi última petición como laird de Harbor City.",
  ui_story_5032_50320502_58_dialog_content = "Entendido.",
  ui_story_5032_50320502_59_dialog_content = "Teniendo en cuenta su historial de gestión de Harbor City y la protección de su gente...",
  ui_story_5032_50320502_60_dialog_content = "Te ayudaré hasta que Windstone vuelva a funcionar y la ciudad vuelva a estar a salvo.",
  ui_story_5032_50320502_61_dialog_content = "Estoy muy agradecido, Su Alteza.",
  ui_story_5032_50320502_62_dialog_content = "Puede que sea un fugitivo, pero permítame darle las gracias como laird de Harbor City.",
  ui_story_5032_50320502_63_dialog_content = "Prescindamos de las formalidades. Recargue la piedra lo antes posible.",
  ui_story_5032_50320502_64_dialog_content = "Tenga la seguridad de que he estado trabajando para despertar el suelo sellado.",
  ui_story_5032_50320502_65_dialog_content = "Me alegro de no haberme equivocado contigo. Cuando te conocí, pude sentir que eres diferente de los otros nobles.",
  ui_story_5032_50320502_66_dialog_content = "Perdóname por no confiar completamente en nadie nuevo de Lumopolis.",
  ui_story_5032_50320502_67_dialog_content = "Porque estoy seguro de que muchos en el Consejo de Ancianos codician el poder que protege Harbor City.",
  ui_story_5032_50320502_68_dialog_content = "Ay, si tan solo hubiera confiado más en ti desde el principio y no hubiera sospechado que eras egoísta como esos nobles...",
  ui_story_5032_50320502_69_dialog_content = "Quizás todo hubiera salido mejor entonces.",
  ui_story_5032_50320502_70_dialog_content = "Pero todavía hay una oportunidad.",
  ui_story_5032_50320502_71_dialog_content = "Entiendo cómo te sientes acerca de lo que el Consejo de Ancianos podría pensar sobre el núcleo de energía o Windstone.",
  ui_story_5032_50320502_72_dialog_content = "Yo, sin embargo, nunca intentaré socavar lo que son los cimientos de Harbor City.",
  ui_story_5032_50320502_73_dialog_content = "Después de todo, los eclipses son el enemigo común y recibirás un juicio justo por tus errores.",
  ui_story_5032_50320502_74_dialog_content = "Pero por ahora, puedo prometer que ningún Eclipsite se te acercará.",
  ui_story_5032_50320502_75_dialog_content = "Gracias, Su Alteza.",
  ui_story_5032_50320502_76_dialog_content = "Comencemos, entonces.",
  ui_story_5032_50320502_77_dialog_content = "Pasa una nueva página en la historia de Harbor City.",
  ui_story_5032_50320601_1_dialog_content = "El reinicio de Windstone, ahora comienza.",
  ui_story_5032_50320601_2_dialog_content = "Reiniciando...",
  ui_story_5032_50320601_3_dialog_content = "Genes Aurorianos apropiados detectados... Iniciando extracción de Lumina.",
  ui_story_5032_50320601_4_dialog_content = "Sí, este es el lugar. Sigue lo que está en el libro... Tose... Y redirige el flujo de energía.",
  ui_story_5032_50320601_5_dialog_content = "Solo... usa el dispositivo en el terreno sellado.",
  ui_story_5032_50320601_6_dialog_content = "Solicitud de redirección detectada. Redirigir la fuente de energía.",
  ui_story_5032_50320601_7_dialog_content = "Conectando...",
  ui_story_5032_50320601_8_dialog_content = "1%... 7%... 19%...",
  ui_story_5032_50320601_9_dialog_content = "¿Esperamos a que termine el proceso ahora?",
  ui_story_5032_50320601_10_dialog_content = "Exactamente.",
  ui_story_5032_50320601_11_dialog_content = "Si el reinicio tiene éxito, el Windstone adoptará el <color=#FFB400>energía absorbida</color> desde el núcleo como la nueva fuente.",
  ui_story_5032_50320601_12_dialog_content = "Luego, aquellos crónicamente atribulados por <color=#FFB400>síndrome modal</color> finalmente será libre... *tosiendo*",
  ui_story_5032_50320601_13_dialog_content = "Sí... Eso también debería mejorar tu condición, ¿verdad?",
  ui_story_5032_50320601_14_dialog_content = "Jaja, probablemente.",
  ui_story_5032_50320601_15_dialog_content = "No tengo idea de cuánto mejor seré, pero definitivamente mejor de lo que soy ahora.",
  ui_story_5032_50320601_16_dialog_content = "Después del desastre que causé, ya no puedo liderar Harbor City.",
  ui_story_5032_50320601_17_dialog_content = "Es cierto que tu acción violó seriamente tus obligaciones como laird, pero fue básicamente por el bien de la gente.",
  ui_story_5032_50320601_18_dialog_content = "Se lo explicaré al Señor de la Ciudad para obtener un juicio justo.",
  ui_story_5032_50320601_19_dialog_content = "Je, de hecho eres diferente, Su Alteza. Permítanme expresar mi gratitud nuevamente.",
  ui_story_5032_50320601_20_dialog_content = "Si no tienes adónde ir, Elvis... podrías considerar subir a bordo del Emerald.",
  ui_story_5032_50320601_21_dialog_content = "¿Vaya? Pero no soy un artista de circo, Jeno.",
  ui_story_5032_50320601_22_dialog_content = "Es genial. Puedes aprender.",
  ui_story_5032_50320601_23_dialog_content = "Solo necesitamos un domador alternativo, de todos modos.",
  ui_story_5032_50320601_24_dialog_content = "Eso significa que tendré que trabajar muy duro, entonces.",
  ui_story_5032_50320601_25_dialog_content = "(Elvis se ve mucho más relajado. Supongo que se reconciliaron).",
  ui_story_5032_50320601_26_dialog_content = "<color=#e8d9bb>¡Zumbido!</color>",
  ui_story_5032_50320601_27_dialog_content = "¿Por qué Windstone hace tanto ruido?",
  ui_story_5032_50320601_28_dialog_content = "¿Qué está pasando?",
  ui_story_5032_50320601_29_dialog_content = "Advertencia. Error de redirección de energía.",
  ui_story_5032_50320601_30_dialog_content = "Código de error 102. Energía incompatible con <color=#FFB400>Piedra de viento</color>.",
  ui_story_5032_50320601_31_dialog_content = "¡Imposible! ¡Mi investigación mostró que la energía del núcleo de energía es la más compatible con la piedra!",
  ui_story_5032_50320601_32_dialog_content = "¡No entres en pánico, Elvis!",
  ui_story_5032_50320601_33_dialog_content = "Revisa la piedra y mira si hay algo que podamos hacer.",
  ui_story_5032_50320601_34_dialog_content = "Yo... ¡¿Qué es esto?!",
  ui_story_5032_50320601_35_dialog_content = "¿Qué ocurre?",
  ui_story_5032_50320601_36_dialog_content = "La tasa de salida del núcleo de energía fluctúa... ¡y se vuelve cada vez más intensa!",
  ui_story_5032_50320601_37_dialog_content = "¡Eso sucede solo cuando la energía no es lo suficientemente pura!",
  ui_story_5032_50320601_38_dialog_content = "Advertencia. Error crítico en la redirección de energía.",
  ui_story_5032_50320601_39_dialog_content = "Código de error 600. La entrada de energía excede <color=#FFB400>Piedra de viento</color> capacidad.",
  ui_story_5032_50320601_40_dialog_content = "Detenga la entrada de energía de inmediato para evitar repercusiones graves.",
  ui_story_5032_50320601_41_dialog_content = "¡Cállate, Elvis, o explotará!",
  ui_story_5032_50320601_42_dialog_content = "Lo estoy intentando...",
  ui_story_5032_50320601_43_dialog_content = "¡¡¡Puaj!!!",
  ui_story_5032_50320601_44_dialog_content = "Vicio, protege PlayerName!",
  ui_story_5032_50320601_45_dialog_content = "Ponte detrás de nosotros, PlayerName!",
  ui_story_5032_50320601_46_dialog_content = "¡Elvis!",
  ui_story_5032_50320601_47_dialog_content = "No te acerques... La energía... ¡está empezando a perderse!",
  ui_story_5032_50320601_48_dialog_content = "¡No puedo detenerlo!",
  ui_story_5032_50320601_49_dialog_content = "¡No importa el cetro, solo déjalo caer!",
  ui_story_5032_50320601_50_dialog_content = "<color=#e8d9bb>¡¡¡BOOM!!!</color>",
  ui_story_5032_50320601_51_dialog_content = "¡Oh!",
  ui_story_5032_50320601_52_dialog_content = "*Tose*",
  ui_story_5032_50320601_53_dialog_content = "¡¿Estás bien, Jeno?!",
  ui_story_5032_50320601_54_dialog_content = "*Tose*... Estoy bien, sigo viva.",
  ui_story_5032_50320601_55_dialog_content = "Si fuera más lento, estarías muerto.",
  ui_story_5032_50320601_56_dialog_content = "¡El Windstone... está fuera de control...!",
  ui_story_5032_50320601_57_dialog_content = "¡La piedra de viento! ¿Está bien el Windstone?",
  ui_story_5032_50320601_58_dialog_content = "¡Elvis!",
  ui_story_5032_50320601_59_dialog_content = "Aquí está... Afortunadamente, no está dañado, pero toda su energía se ha perdido.",
  ui_story_5032_50320601_60_dialog_content = "¡Quizás todavía se pueda reiniciar!",
  ui_story_5032_50320601_61_dialog_content = "¿Reiniciado?",
  ui_story_5032_50320601_62_dialog_content = "Mira, Elvis, el terreno sellado se ha arruinado más allá del reconocimiento por la explosión.",
  ui_story_5032_50320601_63_dialog_content = "Los dispositivos antiguos están destrozados. ¿Cómo vamos a reiniciar?",
  ui_story_5032_50320601_64_dialog_content = "Yo... ¡Dame más tiempo y encontraré una manera!",
  ui_story_5032_50320601_65_dialog_content = "¡Ayuda ayuda! ¡Eclipsitos!",
  ui_story_5032_50320601_66_dialog_content = "¿Eclipsitos?",
  ui_story_5032_50320601_67_dialog_content = "El sonido parece provenir del pueblo.",
  ui_story_5032_50320601_68_dialog_content = "*Tose*... ¡Oh no, los Eclipsites deben haber roto el sello porque el Windstone perdió toda la energía!",
  ui_story_5032_50320601_69_dialog_content = "<color=#e8d9bb>Mientras tanto, en Ciudad Puerto</color>",
  ui_story_5032_50320601_70_dialog_content = "¿Por qué salen tantos eclipses del océano?",
  ui_story_5032_50320601_71_dialog_content = "¡Rápido, ve a la costa! ¡Establece defensas y evacua a la gente!",
  ui_story_5032_50320601_72_dialog_content = "¡Sí señor!",
  ui_story_5032_50320601_73_dialog_content = "¿Aparecen eclipses a lo largo de la costa?",
  ui_story_5032_50320601_74_dialog_content = "Y el sonido de una explosión proveniente del suelo sellado hace un momento... ¿Fracasó Laird Elvis?",
  ui_story_5032_50320601_75_dialog_content = "Tengo que proteger al laird. Con todos los soldados listos para luchar contra los Eclipsites, ahora es el momento.",
  ui_story_5032_50320601_76_dialog_content = "¡Síganme, todos!",
  ui_story_5032_50320601_77_dialog_content = "¡¡¡Sí!!!",
  ui_story_5032_50320601_78_dialog_content = "¡Laird Elvis!",
  ui_story_5032_50320601_79_dialog_content = "¿Patou? ¿Qué estás haciendo aquí?",
  ui_story_5032_50320601_80_dialog_content = "Huff, huff...",
  ui_story_5032_50320601_81_dialog_content = "Seguro que no me lo pusiste fácil para encontrar a Elvis y Patou.",
  ui_story_5032_50320601_82_dialog_content = "Tu cara está torcida.",
  ui_story_5032_50320601_83_dialog_content = "¿Ni siquiera tratando de esconderse?",
  ui_story_5032_50320601_84_dialog_content = "¡Ahora no es el momento para tu sarcasmo!",
  ui_story_5032_50320601_85_dialog_content = "¿No ves que es urgente ahora mismo? ¡No se interponga en el camino!",
  ui_story_5032_50320601_86_dialog_content = "Jeno tiene razón. Harbor City está en peligro.",
  ui_story_5032_50320601_87_dialog_content = "Espere... ¿Por qué está aquí, Su Alteza?",
  ui_story_5032_50320601_88_dialog_content = "Llegaré a eso más tarde. Tenemos asuntos mucho más importantes a la mano.",
  ui_story_5032_50320601_89_dialog_content = "*Tose*... ¿Cómo está Harbor City, Patou?",
  ui_story_5032_50320601_90_dialog_content = "Innumerables eclipses están saliendo del mar, señor. El Windstone es probablemente ineficaz ahora.",
  ui_story_5032_50320601_91_dialog_content = "Tenía miedo de eso...",
  ui_story_5032_50320601_92_dialog_content = "Vicio, PlayerName, volvamos a la ciudad.",
  ui_story_5032_50320601_93_dialog_content = "Hay tantos ciudadanos desarmados. ¡No podemos quedarnos de brazos cruzados!",
  ui_story_5032_50320601_94_dialog_content = "¡Sí, lo tengo!",
  ui_story_5032_50320601_95_dialog_content = "¡Seguro!",
  ui_story_5032_50320601_96_dialog_content = "Pero espera... ¿Qué pasa con el fugitivo de la prisión?",
  ui_story_5032_50320601_97_dialog_content = "Jeno, por favor... Ve con Su Alteza.",
  ui_story_5032_50320601_98_dialog_content = "Y por favor... protege a la gente de Harbor City.",
  ui_story_5032_50320601_99_dialog_content = "No, me quedo aquí contigo.",
  ui_story_5032_50320601_100_dialog_content = "¿No te das cuenta de que estás en tus últimas piernas?",
  ui_story_5032_50320601_101_dialog_content = "No te preocupes, Jeno, todavía puedo ir.",
  ui_story_5032_50320601_102_dialog_content = "*Tose* Yo... tengo que volver. Debería haber pistas sobre cómo reiniciar Windstone en los archivos.",
  ui_story_5032_50320601_103_dialog_content = "Si puedo reiniciarlo, los eclipses desaparecerán.",
  ui_story_5032_50320601_104_dialog_content = "Será mejor que encuentres algo para deshacerte de los eclipses.",
  ui_story_5032_50320601_105_dialog_content = "No voy a dejar que un fugitivo se mueva libremente. ¡Loewe y yo te estaremos observando!",
  ui_story_5032_50320601_106_dialog_content = "Je, gracias por el pensamiento.",
  ui_story_5032_50320601_107_dialog_content = "Elvis...",
  ui_story_5032_50320601_108_dialog_content = "Está bien, Jeno. Estaré bien con Patou y otros alrededor.",
  ui_story_5032_50320601_109_dialog_content = "Por favor, cuida de la gente de Harbor City por mí.",
  ui_story_5032_50320601_110_dialog_content = "...",
  ui_story_5032_50320601_111_dialog_content = "Seguro que sabes cómo tirarme las papas calientes.",
  ui_story_5032_50320601_112_dialog_content = "Lo siento... Te lo compensaré cuando esto termine.",
  ui_story_5032_50320601_113_dialog_content = "Siempre y cuando esté dentro de mi capacidad.",
  ui_story_5032_50320601_114_dialog_content = "Bien, te esperaré.",
  ui_story_5032_50320601_115_dialog_content = "Está bien...",
  ui_story_5032_50320601_116_dialog_content = "Um... ¿Por qué tenemos tantos eclipses?",
  ui_story_5032_50320601_117_dialog_content = "¡Mira allá!",
  ui_story_5032_50320601_118_dialog_content = "¡Están creciendo en número!",
  ui_story_5032_50320601_119_dialog_content = "Cómo es eso posible...",
  ui_story_5032_50320601_120_dialog_content = "¡El mar está lleno de eclipses!",
  ui_story_5032_50320601_121_dialog_content = "¡Deja de pensar y empieza a luchar!",
  ui_story_5032_50320601_122_dialog_content = "¿Es posible incluso luchar contra todos ellos?",
  ui_story_5032_50320601_123_dialog_content = "No tenemos más remedio que luchar.",
  ui_story_5032_50320601_124_dialog_content = "Debemos mantenernos firmes y proteger a la gente de Harbor City.",
  ui_story_5032_50320601_125_dialog_content = "¡No retrocederé hasta que los civiles sean evacuados!",
  ui_story_5032_50320601_126_dialog_content = "... Elvis tiene razón. Eres diferente de los otros nobles.",
  ui_story_5032_50320601_127_dialog_content = "Déjame ayudar. Esta fue una vez nuestro hogar, después de todo.",
  ui_story_5032_50320602_1_dialog_content = "Uf... ¡Pooh! ¡Esto es salado!",
  ui_story_5032_50320602_2_dialog_content = "Hay que tener cuidado no solo con los eclipses, sino también con el mar embravecido...",
  ui_story_5032_50320602_3_dialog_content = "Me pregunto si Fia y los demás estarán bien en el <color=#FFB400>Esmeralda</color>.",
  ui_story_5032_50320602_4_dialog_content = "Debería estar bien con Rainbow y Ciel allí, supongo.",
  ui_story_5032_50320602_5_dialog_content = "Realmente no... La Esmeralda es como una isla solitaria con todos estos eclipses en el agua.",
  ui_story_5032_50320602_6_dialog_content = "La gente en tierra aún puede retirarse, pero el Emerald no tiene adónde ir.",
  ui_story_5032_50320602_7_dialog_content = "¡Debemos ir a ayudarlos!",
  ui_story_5032_50320602_8_dialog_content = "Pero, ¿y aquí...?",
  ui_story_5032_50320602_9_dialog_content = "Tengo esto. ¡Con la ayuda de Jeno, estará bien!",
  ui_story_5032_50320602_10_dialog_content = "¡Ve a ayudar a Fia!",
  ui_story_5032_50320602_11_dialog_content = "¡Ok lo tengo!",
  ui_story_5032_50320602_12_dialog_content = "¿Estás seguro de que los dos pueden manejarlo?",
  ui_story_5032_50320602_13_dialog_content = "En seguida.",
  ui_story_5032_50320602_14_dialog_content = "Como su amigo, sé lo duros que son, mejor que nadie.",
  ui_story_5032_50320602_15_dialog_content = "Confía en mí. Llevarán a su tripulación a un lugar seguro.",
  ui_story_5032_50320602_16_dialog_content = "Ya que lo pones así...",
  ui_story_5032_50320602_17_dialog_content = "¡¡¡Gahhhh!!!",
  ui_story_5032_50320602_18_dialog_content = "Tsk...",
  ui_story_5032_50320602_19_dialog_content = "¿Por qué hay tantos eclipses? Ha sido interminable.",
  ui_story_5032_50320602_20_dialog_content = "Han estado atrapados bajo el mar durante tanto tiempo. Sin duda correrían desenfrenados ahora que el sello estaba roto.",
  ui_story_5032_50320602_21_dialog_content = "Puedes imaginarte cuánta energía necesitaba Windstone para mantener un sello tan poderoso.",
  ui_story_5032_50320602_22_dialog_content = "Ahora no es el momento para especulaciones. ¡Tenemos una pelea en nuestras manos!",
  ui_story_5032_50320602_23_dialog_content = "Seguro.",
  ui_story_5032_50320602_24_dialog_content = "Grah...",
  ui_story_5032_50320602_25_dialog_content = "¡Su Alteza!",
  ui_story_5032_50320602_26_dialog_content = "¡Hay demasiados eclipses y la costa es demasiado larga para que podamos establecer una línea de defensa eficaz!",
  ui_story_5032_50320602_27_dialog_content = "Nos superan en número, pero aún podemos tener una oportunidad si concentramos nuestras fuerzas en la ciudad.",
  ui_story_5032_50320602_28_dialog_content = "no puedo hacer ¡Aún no hemos evacuado a todos!",
  ui_story_5032_50320602_29_dialog_content = "Bueno, parece que no hay elección... Haz que los guardias protejan las puertas ya los civiles. ¡Abandonaremos el resto de las áreas de defensa costera en orden!",
  ui_story_5032_50320602_30_dialog_content = "Independientemente, espere hasta que todas las personas hayan sido evacuadas.",
  ui_story_5032_50320602_31_dialog_content = "¡Como usted ordene!",
  ui_story_5032_50320701_1_dialog_content = "¡Graagh!",
  ui_story_5032_50320701_2_dialog_content = "¡Ahhh, seguro que también rompieron esta ventana!",
  ui_story_5032_50320701_3_dialog_content = "Hay agua y vidrios rotos por todas partes. Esto no puede empeorar...",
  ui_story_5032_50320701_4_dialog_content = "¡No puedo permitirme contratar limpiadores, ni puedo limpiar esto yo solo!",
  ui_story_5032_50320701_5_dialog_content = "¡Graaaah!",
  ui_story_5032_50320701_6_dialog_content = "T-Tómatelo con calma, Rainbow. Te ayudaré con el desorden más tarde.",
  ui_story_5032_50320701_7_dialog_content = "Cada vez hay más eclipses, así que tengamos cuidado.",
  ui_story_5032_50320701_8_dialog_content = "Ciel, Fia, por favor suban la ventana como lo hicieron antes.",
  ui_story_5032_50320701_9_dialog_content = "¡Me desharé de estos pelos de punta!",
  ui_story_5032_50320701_10_dialog_content = "¡Grrr!",
  ui_story_5032_50320701_11_dialog_content = "¡R-Rainbow!",
  ui_story_5032_50320701_12_dialog_content = "... Ella se lanzó de cabeza a la batalla como de costumbre.",
  ui_story_5032_50320701_13_dialog_content = "Los eclipses son lo único que tiene en mente cuando los ve.",
  ui_story_5032_50320701_14_dialog_content = "¿Arcoiris estará bien?",
  ui_story_5032_50320701_15_dialog_content = "Ya derrotó a muchos de ellos y está herida.",
  ui_story_5032_50320701_16_dialog_content = "A pesar de que todo eso es autoinfligido en su emoción...",
  ui_story_5032_50320701_17_dialog_content = "Estoy un poco preocupado también.",
  ui_story_5032_50320701_18_dialog_content = "Hmm, culpo a mí por no operar Styx correctamente antes.",
  ui_story_5032_50320701_19_dialog_content = "O no estaría esperando tan impotente...",
  ui_story_5032_50320701_20_dialog_content = "Yo también.",
  ui_story_5032_50320701_21_dialog_content = "Si tan solo no hubiera arrojado a Kyllo al mar.",
  ui_story_5032_50320701_22_dialog_content = "¡Con Kyllo cerca, estos Eclipsites serían presas fáciles!",
  ui_story_5032_50320701_23_dialog_content = "Pobre de mí. Al menos esta debería ser la última ventana, y pronto podremos bloquear los Eclipsites.",
  ui_story_5032_50320701_24_dialog_content = "Está bien, estoy abordando este lado hacia arriba. Dame una mano, Fia...",
  ui_story_5032_50320701_25_dialog_content = "¡Grrr!",
  ui_story_5032_50320701_26_dialog_content = "¡Puaj! ¡Otro eclipse!",
  ui_story_5032_50320701_27_dialog_content = "¡Fuera, Fía!",
  ui_story_5032_50320701_28_dialog_content = "¡Gahh!",
  ui_story_5032_50320701_29_dialog_content = "<size=45>¡Ahhh!</size>",
  ui_story_5032_50320701_30_dialog_content = "¡Fia!",
  ui_story_5032_50320701_31_dialog_content = "¡Oh, no, el Eclipsite está demasiado cerca de ella para que use Aqua Blaster!",
  ui_story_5032_50320701_32_dialog_content = "En ese caso.",
  ui_story_5032_50320701_33_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5032_50320701_34_dialog_content = "¡Grrr!",
  ui_story_5032_50320701_35_dialog_content = "¡Oh!",
  ui_story_5032_50320701_36_dialog_content = "¡Rainbow! ¡Fia! ¿Están bien?",
  ui_story_5032_50320701_37_dialog_content = "Em...",
  ui_story_5032_50320701_38_dialog_content = "Estoy bien. Me duele un poco la cabeza.",
  ui_story_5032_50320701_39_dialog_content = "¿Dónde está Rainbow? Creo que la vi venir en mi dirección.",
  ui_story_5032_50320701_40_dialog_content = "...",
  ui_story_5032_50320701_41_dialog_content = "¡Oh no, Rainbow se desmayó!",
  ui_story_5032_50320701_42_dialog_content = "¡Tiene la espalda ensangrentada!",
  ui_story_5032_50320701_43_dialog_content = "¿Fue golpeada por el Eclipsite?",
  ui_story_5032_50320701_44_dialog_content = "Ella... Ella se lastimó tratando de salvarme...",
  ui_story_5032_50320701_45_dialog_content = "C-Ce, no tenemos nada para detener la hemorragia. Q-que hacer...",
  ui_story_5032_50320701_46_dialog_content = "no pude ayudar PlayerName y mis amigos cuando lucharon contra el gran robot.",
  ui_story_5032_50320701_47_dialog_content = "Ahora no puedo ayudar a Rainbow y Ciel, e incluso hice daño a Rainbow...",
  ui_story_5032_50320701_48_dialog_content = "<anim type=Shake>Boo-hoo... yo... yo...</anim>",
  ui_story_5032_50320701_49_dialog_content = "¡Grrr!",
  ui_story_5032_50320701_50_dialog_content = "¡No, ahora no es el momento de llorar!",
  ui_story_5032_50320701_51_dialog_content = "¡Debo proteger a Rainbow!",
  ui_story_5032_50320701_52_dialog_content = "¡Aléjense, estúpidos eclipses!",
  ui_story_5032_50320701_53_dialog_content = "<color=#e8d9bb>¡Bang, bang, bang!</color>",
  ui_story_5032_50320701_54_dialog_content = "¡Graagh!",
  ui_story_5032_50320701_55_dialog_content = "¡Guau! ¡Funcionó!",
  ui_story_5032_50320701_56_dialog_content = "Sabía que no funcionó la última vez porque el robot era demasiado duro...",
  ui_story_5032_50320701_57_dialog_content = "¡Gah! ¡Gah!",
  ui_story_5032_50320701_58_dialog_content = "¡Cuidado, Fia, aquí vienen de nuevo!",
  ui_story_5032_50320701_59_dialog_content = "Ahhhh... ¡¿Por qué tantos eclipses?!",
  ui_story_5032_50320701_60_dialog_content = "¿Están migrando por el mar o algo así de repente?",
  ui_story_5032_50320701_61_dialog_content = "Quedan tres disparos, con un clip de repuesto...",
  ui_story_5032_50320701_62_dialog_content = "*Sollozos* ¡Esto no es suficiente!",
  ui_story_5032_50320701_63_dialog_content = "¡Grrr!",
  ui_story_5032_50320701_64_dialog_content = "<color=#e8d9bb>¡Bang, bang, bang!</color>",
  ui_story_5032_50320701_65_dialog_content = "Si Kyllo estuviera aquí...",
  ui_story_5032_50320701_66_dialog_content = "Kyllo!",
  ui_story_5032_50320701_67_dialog_content = "¡Lo, lo, lo!",
  ui_story_5032_50320701_68_dialog_content = "¡Gaah!",
  ui_story_5032_50320701_69_dialog_content = "Kyllo? ¡¿E-Estás aquí?!",
  ui_story_5032_50320701_70_dialog_content = "¿Q-Qué clase de bestia maravillosa es esta?",
  ui_story_5032_50320701_71_dialog_content = "es mi amigo Su nombre es Kyllo!",
  ui_story_5032_50320701_72_dialog_content = "¡Impresionante! Está dominando a los Eclipsites.",
  ui_story_5032_50320701_73_dialog_content = "Jeje, por supuesto!",
  ui_story_5032_50320701_74_dialog_content = "¡Kyllo es un exótico evolucionado!",
  ui_story_5032_50320701_75_dialog_content = "¡Eso es pan comido!",
  ui_story_5032_50320701_76_dialog_content = "¡Grrr!",
  ui_story_5032_50320701_77_dialog_content = "Cuidado, Kyllo. ¡Los eclipses se acercan detrás de ti!",
  ui_story_5032_50320701_78_dialog_content = "¡Lo, lo!",
  ui_story_5032_50320701_79_dialog_content = "¿Qué? ¿No puedes dar la vuelta?",
  ui_story_5032_50320701_80_dialog_content = "¿Es demasiado grande para maniobrar en el espacio reducido?",
  ui_story_5032_50320701_81_dialog_content = "ga-",
  ui_story_5032_50320701_82_dialog_content = "¡Ah, tengo que recargar!",
  ui_story_5032_50320701_83_dialog_content = "<color=#e8d9bb>Sonido metálico-</color>",
  ui_story_5032_50320701_84_dialog_content = "¡Vaya, se me han caído todas las balas!",
  ui_story_5032_50320701_85_dialog_content = "¡Oh no, Kyllo!",
  ui_story_5032_50320701_86_dialog_content = "¡Lo!",
  ui_story_5032_50320701_87_dialog_content = "¡Torrente rápido!",
  ui_story_5032_50320701_88_dialog_content = "¡Grrr!",
  ui_story_5032_50320701_89_dialog_content = "¿Eh? E-Eso suena como...",
  ui_story_5032_50320701_90_dialog_content = "¿Todos están bien?",
  ui_story_5032_50320701_91_dialog_content = "Lo siento, llegamos tarde. Demasiados eclipses en el camino.",
  ui_story_5032_50320701_92_dialog_content = "es vicio y PlayerName!",
  ui_story_5032_50320701_93_dialog_content = "Humph, supongo que solo somos antecedentes de Fia.",
  ui_story_5032_50320701_94_dialog_content = "¡Sí, sí, me siento muy triste!",
  ui_story_5032_50320701_95_dialog_content = "¡Los trillizos! ¿Por qué te bajaste de la cubierta?",
  ui_story_5032_50320701_96_dialog_content = "¡Nos topamos con Caelestite y Vice allí arriba!",
  ui_story_5032_50320701_97_dialog_content = "Dijeron que es muy peligroso afuera. Se rompió una especie de sello.",
  ui_story_5032_50320701_98_dialog_content = "¡Y todos los Eclipsites que dormían bajo el mar se despertaron!",
  ui_story_5032_50320701_99_dialog_content = "Así que bloqueamos el acceso desde la cubierta y vinimos a decir—",
  ui_story_5032_50320701_100_dialog_content = "¿eh? Espera, ¿está ese Rainbow tirado ahí?",
  ui_story_5032_50320701_101_dialog_content = "¡Lo es!",
  ui_story_5032_50320701_102_dialog_content = "¿Lo que le ocurrió a ella?",
  ui_story_5032_50320701_103_dialog_content = "E-Ella me protegió...",
  ui_story_5032_50320701_104_dialog_content = "Lo siento mucho.",
  ui_story_5032_50320701_105_dialog_content = "¡Gah! ¡Gah!",
  ui_story_5032_50320701_106_dialog_content = "... Retomaremos esto más tarde.",
  ui_story_5032_50320701_107_dialog_content = "¡Primero tengo que eliminar estos eclipses!",
  ui_story_5032_50320701_X107_dialog_content = "<color=#e8d9bb>Algún tiempo después...</color>",
  ui_story_5032_50320701_108_dialog_content = "S-Entonces, ¿realmente salieron del fondo del océano?",
  ui_story_5032_50320701_109_dialog_content = "Sí. Fuimos testigos de cómo Elvis fallaba en su intento y la ola de eclipses invadía la costa.",
  ui_story_5032_50320701_110_dialog_content = "¿Eso no pondría a Harbor City en gran peligro?",
  ui_story_5032_50320701_111_dialog_content = "Carleen y Jeno lideran las fuerzas que defienden la costa.",
  ui_story_5032_50320701_112_dialog_content = "Y Elvis está tratando de encontrar otra forma de reiniciar el sello.",
  ui_story_5032_50320701_113_dialog_content = "Lo único que podemos hacer es asegurarnos de que todos estén a salvo y ganarle tiempo a Elvis.",
  ui_story_5032_50320701_114_dialog_content = "Gracias por arriesgar sus vidas para venir aquí por nosotros.",
  ui_story_5032_50320701_115_dialog_content = "Fui demasiado imprudente y puse en peligro a Ciel y Fia.",
  ui_story_5032_50320701_116_dialog_content = "Si no llegaste a tiempo...",
  ui_story_5032_50320701_117_dialog_content = "Está bien. Tú harías lo mismo por nosotros si estuviéramos en tu lugar.",
  ui_story_5032_50320701_118_dialog_content = "Y Fia se habría metido en un gran problema si no fueras tú.",
  ui_story_5032_50320701_119_dialog_content = "Gracias, Rainbow.",
  ui_story_5032_50320701_120_dialog_content = "¡Debería agradecerte a ti y a Kyllo por salvarnos a todos!",
  ui_story_5032_50320701_121_dialog_content = "¡Lo!",
  ui_story_5032_50320701_122_dialog_content = "Oh, ¿cómo es que Kyllo está aquí?",
  ui_story_5032_50320701_123_dialog_content = "¿No dejaste que volviera al mar, Fia?",
  ui_story_5032_50320701_124_dialog_content = "Lo, lo, lo",
  ui_story_5032_50320701_125_dialog_content = "Um, Kyllo dice que entró por la ventana que rompió Eclipsites.",
  ui_story_5032_50320701_126_dialog_content = "Se había quedado en las aguas cercanas antes de que de repente tuviera una sensación extraña al acercarse a la Esmeralda.",
  ui_story_5032_50320701_127_dialog_content = "¿Un sentimiento extraño? ¿Que es eso?",
  ui_story_5032_50320701_128_dialog_content = "Lo, lo",
  ui_story_5032_50320701_129_dialog_content = "¿Sentiste que estaba en peligro y seguiste a mi Lumina?",
  ui_story_5032_50320701_130_dialog_content = "¡Lo!",
  ui_story_5032_50320701_131_dialog_content = "¿Sintió que Fia estaba en peligro?",
  ui_story_5032_50320701_132_dialog_content = "¿Es esa una habilidad especial para Kyllo?",
  ui_story_5032_50320701_133_dialog_content = "Probablemente sea porque Kyllo y Fia tienen un vínculo profundo.",
  ui_story_5032_50320701_134_dialog_content = "Así que hay un vínculo psíquico entre ellos.",
  ui_story_5032_50320701_135_dialog_content = "¡Lo!",
  ui_story_5032_50320701_136_dialog_content = "Comprendo.",
  ui_story_5032_50320701_137_dialog_content = "Ya que regresaste, Kyllo, ¿eso significa que sabes dónde está Cloudwhale?",
  ui_story_5032_50320701_138_dialog_content = "Lo, lo...",
  ui_story_5032_50320701_139_dialog_content = "Eh... ¿Qué es eso?",
  ui_story_5032_50320701_140_dialog_content = "¿Has estado vagando porque no pudiste encontrar ninguna pista?",
  ui_story_5032_50320701_141_dialog_content = "No querías verme porque te gritaba... ¡Oye, no soy tan malo!",
  ui_story_5032_50320701_142_dialog_content = "¡Lo!",
  ui_story_5032_50320701_143_dialog_content = "Suenas bastante mala en este momento, Fia.",
  ui_story_5032_50320701_144_dialog_content = "A Kyllo le gustas mucho, así que deberías ser más amable con él.",
  ui_story_5032_50320701_145_dialog_content = "Sí, y Kyllo merecía tu más sincero agradecimiento por salvar a todos también.",
  ui_story_5032_50320701_146_dialog_content = "¡Lo, lo!",
  ui_story_5032_50320701_147_dialog_content = "¿Por qué estás asintiendo?",
  ui_story_5032_50320701_148_dialog_content = "¿No he sido amable contigo?",
  ui_story_5032_50320701_149_dialog_content = "Lo...",
  ui_story_5032_50320701_150_dialog_content = "... Está bien, está bien, lo tengo. ¡J-Solo deja de llorar!",
  ui_story_5032_50320701_151_dialog_content = "¡Lo, lo!",
  ui_story_5032_50320701_152_dialog_content = "¿Lo quieres ahora? Sin prisa...",
  ui_story_5032_50320701_153_dialog_content = "Bueno, está bien, gracias... Ejem.",
  ui_story_5032_50320701_154_dialog_content = "Lo?",
  ui_story_5032_50320701_155_dialog_content = "¡Gracias!",
  ui_story_5032_50320701_156_dialog_content = "<size=45>¡Gracias por salvarnos!</size>",
  ui_story_5032_50320701_157_dialog_content = "¡Lo!",
  ui_story_5032_50320701_158_dialog_content = "Y... intentaré no volver a ser mala contigo, ¿de acuerdo?",
  ui_story_5032_50320701_159_dialog_content = "¡Lo, lo!",
  ui_story_5032_50320701_160_dialog_content = "¡N-No tientes tu suerte!",
  ui_story_5032_50320701_161_dialog_content = "¡Lo, lo, lo!",
  ui_story_5032_50320701_162_dialog_content = "Vale, vale, ¡entendido!",
  ui_story_5032_50320701_163_dialog_content = "¡Cinco bolsas de galletas de animales, solo para ti!",
  ui_story_5032_50320701_164_dialog_content = "¡Lo!",
  ui_story_5032_50320701_165_dialog_content = "¿Por qué esto se siente como un deja vu?",
  ui_story_5032_50320701_166_dialog_content = "¿Qué pasa con todas estas bestias maravillosas? Realmente saben cómo regatear.",
  ui_story_5032_50320701_167_dialog_content = "¡Oh, bestia maravillosa!",
  ui_story_5032_50320701_168_dialog_content = "¡Merylt, Firmet! ¡Bica y otros todavía están en la habitación!",
  ui_story_5032_50320701_169_dialog_content = "¡Oh, no, los eclipses los asustarán!",
  ui_story_5032_50320701_170_dialog_content = "¡No te levantes todavía, Rainbow!",
  ui_story_5032_50320701_171_dialog_content = "Estoy bien. Merylt usó un botiquín conmigo. ¡Me siento mejor ahora!",
  ui_story_5032_50320701_172_dialog_content = "¡Tengo que salvar a los animales ahora!",
  ui_story_5032_50320701_173_dialog_content = "ga-",
  ui_story_5032_50320701_174_dialog_content = "... Seguro que eligieron el momento perfecto, ¿no?",
  ui_story_5032_50320701_175_dialog_content = "D-Déjanoslo a nosotros, Rainbow.",
  ui_story_5032_50320701_176_dialog_content = "Merylt, Subli, ¿están listas?",
  ui_story_5032_50320701_177_dialog_content = "¡Sí! ¡Hagámoslo!",
  ui_story_5032_50320702_1_dialog_content = "Ya se acabó, Bica, vas a estar bien.",
  ui_story_5032_50320702_2_dialog_content = "¡He eliminado a todos esos tipos malos!",
  ui_story_5032_50320702_3_dialog_content = "Jaja jaja...",
  ui_story_5032_50320702_4_dialog_content = "La pobre sigue temblando.",
  ui_story_5032_50320702_5_dialog_content = "Por que siento que el Eclipsite no es el que asusta a Bica...",
  ui_story_5032_50320702_6_dialog_content = "¡Hay un Glooey aquí, Rainbow!",
  ui_story_5032_50320702_7_dialog_content = "¡Glú!",
  ui_story_5032_50320702_8_dialog_content = "¡Y dos más por aquí!",
  ui_story_5032_50320702_9_dialog_content = "Glú... ¡Glú!",
  ui_story_5032_50320702_10_dialog_content = "Bien, los Glooey también están bien.",
  ui_story_5032_50320702_11_dialog_content = "Así que eso solo deja...",
  ui_story_5032_50320702_12_dialog_content = "¿eh? ¿Qué pasa, Meryl?",
  ui_story_5032_50320702_13_dialog_content = "¡G-Geedo no está, Rainbow!",
  ui_story_5032_50320702_14_dialog_content = "Geedo?",
  ui_story_5032_50320702_15_dialog_content = "Se mantuvo en una botella, por lo que no podía moverse, ¿verdad?",
  ui_story_5032_50320702_16_dialog_content = "Sí... S-Así que los Eclipsites deben haber...",
  ui_story_5032_50320702_17_dialog_content = "No te preocupes. Ciel, Fia y yo buscaremos más adelante.",
  ui_story_5032_50320702_18_dialog_content = "Puedes seguir buscando a los otros animales que se escaparon.",
  ui_story_5032_50320702_19_dialog_content = "O-Está bien.",
  ui_story_5032_50320702_20_dialog_content = "Mantén el ánimo alto, Merylt. ¡Aún tenemos muchos animales perdidos por encontrar!",
  ui_story_5032_50320702_21_dialog_content = "Minifantasma, Gato de tres colas, Bouncybound...",
  ui_story_5032_50320702_22_dialog_content = "Echemos un vistazo a esas habitaciones destrozadas. ¡Tenemos que revisar los almacenes a fondo!",
  ui_story_5032_50320702_23_dialog_content = "A los gatos de tres colas les gusta esconderse en rincones oscuros cuando están asustados.",
  ui_story_5032_50320702_24_dialog_content = "Entiendo.",
  ui_story_5032_50320702_25_dialog_content = "La Esmeralda albergaba tantas bestias maravillosas, por lo que veo.",
  ui_story_5032_50320702_26_dialog_content = "Con razón Fia no quería irse.",
  ui_story_5032_50320702_27_dialog_content = "De hecho... Oh, Merylt.",
  ui_story_5032_50320702_28_dialog_content = "¿Qué clase de bestia maravillosa es Geedo? Podemos ayudarle a encontrarlo.",
  ui_story_5032_50320702_29_dialog_content = "Oh...",
  ui_story_5032_50320702_30_dialog_content = "es... eh...",
  ui_story_5032_50320702_31_dialog_content = "Una criatura acuática parecida a un pez que trajo el maestro de ceremonias Jeno, pero no tenemos idea de su nombre exacto.",
  ui_story_5032_50320702_32_dialog_content = "Así que simplemente lo llamamos Geedo.",
  ui_story_5032_50320702_33_dialog_content = "<size=30>Wow, Merylt logró terminar una conversación completa con PlayerName!</size>",
  ui_story_5032_50320702_34_dialog_content = "<size=30>¡Eso es progreso!</size>",
  ui_story_5032_50320702_35_dialog_content = "<size=30>Probablemente porque Merylt está realmente preocupada por Geedo.</size>",
  ui_story_5032_50320702_36_dialog_content = "<size=30>¡Dejemos a Merylt y Caelestite a la tarea!</size>",
  ui_story_5032_50320702_37_dialog_content = "(... ¿Por qué Frimet y Subli me están sonriendo?)",
  ui_story_5032_50320702_38_dialog_content = "Entonces deberíamos...",
  ui_story_5032_50320702_39_dialog_content = "¡Uh!",
  ui_story_5032_50320702_40_dialog_content = "¡Grrr!",
  ui_story_5032_50320702_41_dialog_content = "¡Rainbow!",
  ui_story_5032_50320702_42_dialog_content = "¡Rainbow!",
  ui_story_5032_50320702_43_dialog_content = "¡Viene de donde está Rainbow!",
  ui_story_5032_50320702_44_dialog_content = "¡Ah, Merylt y sus hermanas se dirigen hacia allí!",
  ui_story_5032_50320702_45_dialog_content = "vamos también PlayerName!",
  ui_story_5032_50320702_46_dialog_content = "¡Seguro!",
  ui_story_5032_50320702_47_dialog_content = "Fia, Ciel, ¿están bien?",
  ui_story_5032_50320702_48_dialog_content = "Fia, ¿dónde está Rainbow?",
  ui_story_5032_50320702_49_dialog_content = "Um... Estoy aquí.",
  ui_story_5032_50320702_50_dialog_content = "... ¿Eh? ¡Q-Qué ojo tan grande!",
  ui_story_5032_50320702_51_dialog_content = "¿Que es esa cosa?",
  ui_story_5032_50320702_52_dialog_content = "Bueno, supongo que es Geedo.",
  ui_story_5032_50320702_53_dialog_content = "¿eh? Geedo?",
  ui_story_5032_50320702_54_dialog_content = "Este tipo es mucho más grande. ¿Cómo podría ser Geedo?",
  ui_story_5032_50320702_55_dialog_content = "Es así... Vi a un Eclipsite sosteniendo una botella y mirando a Geedo a través de ella en esta habitación.",
  ui_story_5032_50320702_56_dialog_content = "Entré para darle una paliza, pero este cobarde tiró y rompió la botella por miedo.",
  ui_story_5032_50320702_57_dialog_content = "Luego salió un destello de Geedo, y esto es lo que vi cuando pude ver de nuevo...",
  ui_story_5032_50320702_58_dialog_content = "¿Cómo puede ser?",
  ui_story_5032_50320702_59_dialog_content = "Gah...",
  ui_story_5032_50320702_60_dialog_content = "¡Oye, deja de moverte! ¡Me estás acosando!",
  ui_story_5032_50320702_61_dialog_content = "...",
  ui_story_5032_50320702_62_dialog_content = "¿Eh? ¡Se detuvo! ¿Este Eclipsite entendió lo que dijo Rainbow?",
  ui_story_5032_50320702_63_dialog_content = "¿Parece que se ha desmayado?",
  ui_story_5032_50320702_64_dialog_content = "Um, me pregunto por qué este Eclipsite parecía haber estado en agonía.",
  ui_story_5032_50320702_65_dialog_content = "Sostuvo su cabeza y gimió, haciendo que el pequeño espacio fuera aún más estrecho.",
  ui_story_5032_50320702_66_dialog_content = "Pero también estoy un poco ocupado en este momento. De lo contrario, estaría encantado de sacarlo de su miseria de inmediato.",
  ui_story_5032_50320702_67_dialog_content = "Er... Me alegro de que estés a salvo, Rainbow.",
  ui_story_5032_50320702_68_dialog_content = "De todos modos, tenemos que encontrar una manera de sacarla de aquí y rápido.",
  ui_story_5032_50320702_69_dialog_content = "Así es. La espalda de Rainbow todavía está herida...",
  ui_story_5032_50320702_70_dialog_content = "*Sollozando* ¡Por favor, date prisa! ¡Se está poniendo más y más apretado aquí!",
  ui_story_5032_50320702_71_dialog_content = "C-¿No puedes intentar comunicarte con Geedo, Fia?",
  ui_story_5032_50320702_72_dialog_content = "¿Ah?",
  ui_story_5032_50320702_73_dialog_content = "¡Oh sí! Puedes decirle a Geedo que deje de crecer, ¿no Fia?",
  ui_story_5032_50320702_74_dialog_content = "¡Date prisa, antes de que Rainbow se aplaste y se convierta en un panqueque!",
  ui_story_5032_50320702_75_dialog_content = "No, espera, también hay un Eclipsite allí... Entonces, ¿quizás un sándwich Rainbow-and-Eclipsite, en lugar de un panqueque?",
  ui_story_5032_50320702_76_dialog_content = "Argh... Eso no suena nada apetitoso.",
  ui_story_5032_50320702_77_dialog_content = "Bien, ¡le daré una oportunidad!",
  ui_story_5032_50320702_78_dialog_content = "Um... H-Hola, Geedo.",
  ui_story_5032_50320702_79_dialog_content = "¿Podrías tal vez, eh... volver a tu tamaño original?",
  ui_story_5032_50320702_80_dialog_content = "¡Eep! ¡Eep!",
  ui_story_5032_50320702_81_dialog_content = "N-No?",
  ui_story_5032_50320702_82_dialog_content = "¡¿Pero por qué?!",
  ui_story_5032_50320702_83_dialog_content = "¡Eep-eep-eep!",
  ui_story_5032_50320702_84_dialog_content = "Ya veo... ¿Así que quieres estirarte un poco porque mantener constantemente tu forma más pequeña es incómodo?",
  ui_story_5032_50320702_85_dialog_content = "¿Pero no sabes que si no dejas de crecer, vas a lastimar a la persona que te salvó?",
  ui_story_5032_50320702_86_dialog_content = "¿Ep?",
  ui_story_5032_50320702_87_dialog_content = "¡Así es! ¡Rainbow no puede cambiar el tamaño de su cuerpo como tú!",
  ui_story_5032_50320702_88_dialog_content = "... Eep-eep.",
  ui_story_5032_50320702_89_dialog_content = "¡Ay! Entonces, ¿estás dispuesto a cooperar?",
  ui_story_5032_50320702_90_dialog_content = "¡Tipo! ¡Ve a buscarme una botella vacía y llénala con un poco de agua!",
  ui_story_5032_50320702_91_dialog_content = "¡Algo así como el que solía sostener a Geedo antes!",
  ui_story_5032_50320702_92_dialog_content = "¡Entendido!",
  ui_story_5032_50320702_93_dialog_content = "Menos mal que no hemos ordenado y tirado la basura del festival, ¿eh?",
  ui_story_5032_50320702_94_dialog_content = "¡Eso es solo porque has estado holgazaneando, Subli! ¡El maestro de ceremonias te puso a TI a cargo de cuidar la basura hace tres días!",
  ui_story_5032_50320702_95_dialog_content = "¡Jejeje! ¡Todo salió bien al final!",
  ui_story_5032_50320702_96_dialog_content = "¿Esto servirá, Fia?",
  ui_story_5032_50320702_97_dialog_content = "¡Eep! ¡Eep!",
  ui_story_5032_50320702_98_dialog_content = "Geedo dice que sí! ¿Qué hacemos a continuación?",
  ui_story_5032_50320702_99_dialog_content = "Eep.",
  ui_story_5032_50320702_100_dialog_content = "¿Apuntarte con la botella?",
  ui_story_5032_50320702_101_dialog_content = "¿Así?",
  ui_story_5032_50320702_102_dialog_content = "¡Eep!",
  ui_story_5032_50320702_103_dialog_content = "¡Ahh!",
  ui_story_5032_50320702_104_dialog_content = "¡Geedo realmente cabe en la botella!",
  ui_story_5032_50320702_105_dialog_content = "¡E-Eso es asombroso!",
  ui_story_5032_50320702_106_dialog_content = "¡Uf... estoy salvado!",
  ui_story_5032_50320702_107_dialog_content = "Gracias, Fía. ¡Eres mi heroe!",
  ui_story_5032_50320702_108_dialog_content = "¡Graagh!",
  ui_story_5032_50320702_109_dialog_content = "¡Vaya! Casi me olvido de ti...",
  ui_story_5032_50320702_110_dialog_content = "¿Graagh?",
  ui_story_5032_50320702_111_dialog_content = "Pasamos por algunos momentos difíciles juntos, amigo mío... Pero parece que aquí es donde termina nuestra amistad.",
  ui_story_5032_50320702_112_dialog_content = "¡Ahora muere!",
  ui_story_5032_50320702_113_dialog_content = "¡Graagh!",
  ui_story_5032_50320702_114_dialog_content = "Este tipo recuperó su mordisco tan pronto como Geedo volvió a la botella, ¿eh?",
  ui_story_5032_50320702_115_dialog_content = "Espera... Ahora que lo mencionas...",
  ui_story_5032_50320702_116_dialog_content = "<size=45>¡Vaya! PlayerName, todos, escuchen!</size>",
  ui_story_5032_50320702_117_dialog_content = "¡Ahhhh! ¡N-No empieces a gritar así! ¡Estamos aquí!",
  ui_story_5032_50320702_118_dialog_content = "De repente recordé algo que mi maestro dijo sobre la Ballena Nube...",
  ui_story_5032_50320702_119_dialog_content = "\"¡Su poder hace que los Eclipsites se encojan de miedo y que su Lumina pueda disipar incluso el Darkflow más denso!\"",
  ui_story_5032_50320702_120_dialog_content = "¿Podría ser que Geedo...",
  ui_story_5032_50320702_121_dialog_content = "¿Es la Ballena Nube que hemos estado buscando todo este tiempo?",
  ui_story_5032_50320702_122_dialog_content = "¡Es posible! La Lumina de Geedo se volvió mucho más difícil de detectar después de que se redujo a su tamaño actual.",
  ui_story_5032_50320702_123_dialog_content = "¡Esta podría ser la razón por la que tu maestro perdió el rastro de la ballena nubosa y pensó que estaba en peligro, Fia!",
  ui_story_5032_50320702_124_dialog_content = "Si Geedo es realmente la Ballena Nube...",
  ui_story_5032_50320702_125_dialog_content = "¡Entonces, según mi maestro, podría salvarnos!",
  ui_story_5032_50320702_126_dialog_content = "¡El poder de Geedo pudo ralentizar los movimientos de Eclipsite antes, convirtiéndolo en un objetivo fácil!",
  ui_story_5032_50320702_127_dialog_content = "¡Eso significa que podría hacer lo mismo con otros Eclipsites!",
  ui_story_5032_50320702_128_dialog_content = "Si podemos llevar a Geedo a un lugar lo suficientemente grande como para que vuelva a su tamaño normal... ¡Su poder podría suprimir los eclipses en un área aún más grande!",
  ui_story_5032_50320702_129_dialog_content = "Geedo vino del océano, ¿verdad? ¿Qué tal si lo llevamos allí?",
  ui_story_5032_50320702_130_dialog_content = "Estás bien, PlayerName! ¿Ver? ¡Incluso usted puede tener buenas ideas de vez en cuando!",
  ui_story_5032_50320702_131_dialog_content = "Pero ya hemos sellado todas las ventanas aquí abajo...",
  ui_story_5032_50320702_132_dialog_content = "Para reabrirlos, tendremos que esperar a que se reparen los sistemas del motor del Emerald.",
  ui_story_5032_50320702_133_dialog_content = "Y según Subli, la cubierta todavía está repleta de eclipses. Forzar nuestro camino a través de ellos sería extremadamente peligroso.",
  ui_story_5032_50320702_134_dialog_content = "¿Puedes pedirle confirmación a Geedo, Fia? Necesitamos saber si es realmente la Ballena Nube y tiene este tipo de poder.",
  ui_story_5032_50320702_135_dialog_content = "Yo... no tengo manera de confirmar eso. Lo siento...",
  ui_story_5032_50320702_136_dialog_content = "¡P-Pero mi intuición me dice que Geedo realmente es el Cloudwhale!",
  ui_story_5032_50320702_137_dialog_content = "Por eso... ¡Por eso creo que aún deberíamos intentarlo!",
  ui_story_5032_50320702_138_dialog_content = "Mmm... ¿Qué te parece? PlayerName?",
  ui_story_5032_50320702_139_dialog_content = "Yo...",
  ui_story_5032_50320702_140_dialog_content = "Estoy de acuerdo. Hagamos un intento.",
  ui_story_5032_50320702_141_dialog_content = "Aunque Fia puede ser inmadura... Y obstinada... E incluso poco confiable a veces...",
  ui_story_5032_50320702_142_dialog_content = "H-Oye! ¿Es esta tu forma de vengarte de mí? PlayerName?!",
  ui_story_5032_50320702_143_dialog_content = "A pesar de todo eso, Fia y yo hemos pasado juntos por muchas situaciones peligrosas, y tengo plena confianza en su habilidad y experiencia como extrozoóloga.",
  ui_story_5032_50320702_144_dialog_content = "Es por eso que estoy dispuesto a confiar en su intuición esta vez.",
  ui_story_5032_50320702_145_dialog_content = "Salir a cubierta sería una sentencia de muerte... Pero si Geedo es realmente la Ballena de las Nubes, ¡podríamos cambiar el rumbo a nuestro favor!",
  ui_story_5032_50320702_146_dialog_content = "PlayerName...",
  ui_story_5032_50320702_147_dialog_content = "Bien,PlayerName, si confías en el juicio de Fia, entonces yo también.",
  ui_story_5032_50320702_148_dialog_content = "Subiré a cubierta con ustedes dos.",
  ui_story_5032_50320702_149_dialog_content = "¡Vice!",
  ui_story_5032_50320702_150_dialog_content = "Ustedes hacen algunos argumentos convincentes, ¿sabes?",
  ui_story_5032_50320702_151_dialog_content = "En lugar de poner todas nuestras esperanzas en los demás... ¡Es mejor entrar en el juego nosotros mismos y aumentar las posibilidades de éxito de todos!",
  ui_story_5032_50320702_152_dialog_content = "Además, sentarse aquí no evitará que la Esmeralda se desgarre en el corto plazo.",
  ui_story_5032_50320702_153_dialog_content = "Arcoiris... ¡Gracias! ¡Gracias a todos por creer en mí!",
  ui_story_5032_50320702_154_dialog_content = "Jaja, no hace falta mucho para emocionarte, ¿verdad, Fia?",
  ui_story_5032_50320702_155_dialog_content = "Muy bien, es suficiente... ¡Comencemos a planificar nuestro próximo movimiento!",
  ui_story_5032_50320702_156_dialog_content = "Estoy seguro de que habrá más Eclipsites en la cubierta de los que podemos imaginar...",
  ui_story_5032_50320801_1_dialog_content = "¡Princesa Carolina! ¡Ha aparecido un Eclipsite de alto nivel cerca de nuestra tercera posición defensiva del lado izquierdo! ¡Están pidiendo refuerzos!",
  ui_story_5032_50320801_2_dialog_content = "Envía el quinto escuadrón guerrillero para ayudarlos.",
  ui_story_5032_50320801_3_dialog_content = "Los Eclipsites parecen estar disminuyendo en número desde la séptima posición defensiva del lado izquierdo y más allá.",
  ui_story_5032_50320801_4_dialog_content = "Diles que envíen exploradores para evaluar la situación y que asignen los refuerzos que puedan a los puntos defensivos centrales.",
  ui_story_5032_50320801_5_dialog_content = "¡Entendido!",
  ui_story_5032_50320801_6_dialog_content = "¿Cómo está procediendo la evacuación de la ciudad?",
  ui_story_5032_50320801_7_dialog_content = "El primer grupo de civiles ha sido escoltado de manera segura al refugio, Princess Carleen.",
  ui_story_5032_50320801_8_dialog_content = "Todavía estamos en proceso de evacuar al resto de la gente.",
  ui_story_5032_50320801_9_dialog_content = "También hemos inspeccionado el refugio y todo parece estar en orden.",
  ui_story_5032_50320801_10_dialog_content = "Bueno. Ya veo.",
  ui_story_5032_50320801_11_dialog_content = "¡Sigue manteniendo la línea! ¡Acabamos de recibir comunicaciones de Lumopolis diciendo que los refuerzos llegarán en breve!",
  ui_story_5032_50320801_12_dialog_content = "¡Entendido!",
  ui_story_5032_50320801_13_dialog_content = "Tengo que decir que estoy sinceramente sorprendido de lo bien que ha ido la evacuación. El primer grupo de refugiados llegó al refugio en tan poco tiempo...",
  ui_story_5032_50320801_14_dialog_content = "A este ritmo, el número de bajas debería ser mucho menor de lo que anticipé.",
  ui_story_5032_50320801_15_dialog_content = "Por cierto. Y tenemos que agradecer a Laird Elvis por esto.",
  ui_story_5032_50320801_16_dialog_content = "El laird realiza simulacros de evacuación regulares, para que las personas sepan exactamente cómo reaccionar durante una emergencia.",
  ui_story_5032_50320801_17_dialog_content = "Nunca pensé que vería el día en que los taladros finalmente se pusieran en uso.",
  ui_story_5032_50320801_18_dialog_content = "¿simulacros de evacuación?",
  ui_story_5032_50320801_19_dialog_content = "Si su Alteza. Laird Elvis se prepara para el peligro incluso en tiempos de paz y presta especial atención al mantenimiento de estos sistemas e instalaciones.",
  ui_story_5032_50320801_20_dialog_content = "Aunque los refugios no se han utilizado en años, les damos mantenimiento al menos una vez al año siguiendo las instrucciones de Laird Elvis.",
  ui_story_5032_50320801_21_dialog_content = "<size=30>¿Es esto también parte de tu plan, Elvis?</size>",
  ui_story_5032_50320801_22_dialog_content = "Te pido perdón, Tu...",
  ui_story_5032_50320801_23_dialog_content = "¡Cuidado, princesa Carleen! ¡Un Eclipsite está cargando directamente hacia ti!",
  ui_story_5032_50320801_24_dialog_content = "¡Gahhhh!",
  ui_story_5032_50320801_25_dialog_content = "¡Ahhhh!",
  ui_story_5032_50320801_26_dialog_content = "¡Todos manténganse tranquilos! ¡No entrar en pánico!",
  ui_story_5032_50320801_27_dialog_content = "M... ¡Mis disculpas, Su Alteza!",
  ui_story_5032_50320801_28_dialog_content = "Te pusieron en peligro porque no pudimos detenerlo...",
  ui_story_5032_50320801_29_dialog_content = "Estoy bien. Ahora regresa a tus publicaciones.",
  ui_story_5032_50320801_30_dialog_content = "No permitas que formalidades como esta te distraigan en el campo de batalla.",
  ui_story_5032_50320801_31_dialog_content = "¡Entendido!",
  ui_story_5032_50320801_32_dialog_content = "¡Ay! H-Ayuda! ¡Refuerzos!",
  ui_story_5032_50320801_33_dialog_content = "¡Algunos eclipses han atravesado nuestra línea defensiva y se dirigen a la ciudad!",
  ui_story_5032_50320801_34_dialog_content = "¡Graagh!",
  ui_story_5032_50320801_35_dialog_content = "Eso es malo. No tenemos soldados de sobra...",
  ui_story_5032_50320801_36_dialog_content = "¡Ven conmigo!",
  ui_story_5032_50320801_37_dialog_content = "¡S-Sí, Su Alteza!",
  ui_story_5032_50320801_38_dialog_content = "¡Flor de hielo!",
  ui_story_5032_50320801_39_dialog_content = "¡Graagh!",
  ui_story_5032_50320801_40_dialog_content = "*Tos*...",
  ui_story_5032_50320801_41_dialog_content = "¡Princesa Carolina! ¿Has resultado herido?",
  ui_story_5032_50320801_42_dialog_content = "No estoy bien. Es solo que... El Darkflow en el aire se ha vuelto tan denso que incluso mis sentidos comienzan a verse afectados.",
  ui_story_5032_50320801_43_dialog_content = "Dado el estado de nuestras fuerzas, una batalla prolongada es altamente desfavorable.",
  ui_story_5032_50320801_44_dialog_content = "¡Graagh!",
  ui_story_5032_50320801_45_dialog_content = "¡Se abrieron paso más eclipses!",
  ui_story_5032_50320801_46_dialog_content = "Nuestras tropas de primera línea también están empezando a disminuir...",
  ui_story_5032_50320801_47_dialog_content = "¡N-No te rindas! ¡Todavía hay civiles detrás de nosotros!",
  ui_story_5032_50320801_48_dialog_content = "¡N-No podemos darnos el lujo de dejar que atraviesen esta línea defensiva!",
  ui_story_5032_50320801_49_dialog_content = "¡Entendido!",
  ui_story_5032_50320801_50_dialog_content = "¡Gahhhh!",
  ui_story_5032_50320801_51_dialog_content = "¡¿Q-Qué es esto?!",
  ui_story_5032_50320801_52_dialog_content = "¡Un eclipse de alto nivel! ¡Ha aparecido otro Eclipsite de alto nivel!",
  ui_story_5032_50320801_53_dialog_content = "¡No rompan la formación, todos! Concentrarse en-!",
  ui_story_5032_50320801_54_dialog_content = "¡Argh!",
  ui_story_5032_50320801_55_dialog_content = "¡C-Capitán!",
  ui_story_5032_50320801_56_dialog_content = "Este eclipse...",
  ui_story_5032_50320801_57_dialog_content = "No sirve de nada. Los soldados normales no tienen ninguna oportunidad contra eso.",
  ui_story_5032_50320801_58_dialog_content = "¡Retírate por ahora y ve a tratar con los otros Eclipsites! ¡No dejes que nadie entre en la ciudad hasta que se complete la evacuación!",
  ui_story_5032_50320801_59_dialog_content = "¡Déjame este Eclipsite a mí!",
  ui_story_5032_50320801_60_dialog_content = "¡Señora Carleen!",
  ui_story_5032_50320801_61_dialog_content = "¡Gahhhhhh!",
  ui_story_5032_50320802_1_dialog_content = "¡Uh!",
  ui_story_5032_50320802_2_dialog_content = "Mi cuerpo aún no se ha recuperado por completo. Mi fuerza no puede seguir...",
  ui_story_5032_50320802_3_dialog_content = "Sin mencionar que el Darkflow es tan denso que incluso mi cuerpo se siente pesado.",
  ui_story_5032_50320802_4_dialog_content = "¡Gahhhh!",
  ui_story_5032_50320802_5_dialog_content = "Incluso si no puedo evitar que Darkflow invada la ciudad... ¡No puedo permitir que este Eclipsite pase por aquí!",
  ui_story_5032_50320802_6_dialog_content = "No tengo otra opción. Sé que le prometí a Vice...",
  ui_story_5032_50320802_7_dialog_content = "Deberías tomártelo con calma por un tiempo, Carleen. No apresure su recuperación.",
  ui_story_5032_50320802_8_dialog_content = "Puede desmayarse debido al drenaje de Lumina si aún no está aclimatado.",
  ui_story_5032_50320802_9_dialog_content = "Así que no te fuerces con tus nuevos poderes hasta que te hayas recuperado, ¿de acuerdo?",
  ui_story_5032_50320802_10_dialog_content = "Eso suena como algo Carleen haría.",
  ui_story_5032_50320802_11_dialog_content = "Bien, ya veo.",
  ui_story_5032_50320802_12_dialog_content = "Me cuidaré. Está seguro.",
  ui_story_5032_50320802_13_dialog_content = "Lo siento, Vice.",
  ui_story_5032_50320802_14_dialog_content = "Pero si retrocedo en este momento, más personas solo saldrán lastimadas.",
  ui_story_5032_50320802_15_dialog_content = "*Inhala* Concéntrate y respira hondo...",
  ui_story_5032_50320802_16_dialog_content = "¡Gahhhh!",
  ui_story_5032_50320802_17_dialog_content = "Resplandor espléndido!",
  ui_story_5032_50320802_18_dialog_content = "¡Gahhhhhh!",
  ui_story_5032_50320802_19_dialog_content = "¡Funcionó!",
  ui_story_5032_50320802_20_dialog_content = "¡Uh!",
  ui_story_5032_50320802_21_dialog_content = "Debería haber sabido que mi nuevo poder no sería tan fácil de controlar...",
  ui_story_5032_50320802_22_dialog_content = "¿Todavía me cuesta forzarlo?",
  ui_story_5032_50320802_23_dialog_content = "¡Gahhhh!",
  ui_story_5032_50320802_24_dialog_content = "¡No puedo esquivar completamente este!",
  ui_story_5032_50320802_25_dialog_content = "¡Pero aún puedo pelear con solo una pierna lesionada!",
  ui_story_5032_50320802_26_dialog_content = "<color=#e8d9bb>Sonido metálico...</color>",
  ui_story_5032_50320802_27_dialog_content = "Uf... Menos mal que llegué a tiempo, o de lo contrario tendría que explicarle todo esto a Schwartz y al resto de esos nobles. Eso no sería divertido, en absoluto...",
  ui_story_5032_50320802_28_dialog_content = "¡Perdóname, princesa Carleen! ¿Qué clase de estilo de lucha es ese?",
  ui_story_5032_50320802_29_dialog_content = "¿No estás preocupado por nosotros? ¡Tendríamos un gran problema si te pasara algo, ya sabes!",
  ui_story_5032_50320802_30_dialog_content = "¿Ah?",
  ui_story_5032_50320802_31_dialog_content = "¡E-Eres tú!",
  ui_story_5032_50320802_32_dialog_content = "¿Qué clase de respuesta es esa?",
  ui_story_5032_50320802_33_dialog_content = "¡Acabo de salvarte la vida! ¡Puedes hacerlo mejor que eso!",
  ui_story_5032_50320802_34_dialog_content = "Vamos, al menos un \"gracias\" estaría bien.",
  ui_story_5032_50320802_35_dialog_content = "...Gracias.",
  ui_story_5032_50320802_36_dialog_content = "¿Está herida, princesa Carleen?",
  ui_story_5032_50320802_37_dialog_content = "Estoy perfectamente bien, Sr. Loewe.",
  ui_story_5032_50320802_38_dialog_content = "Aunque, si ustedes dos fueron capaces de llegar a este lugar, entonces eso significa...",
  ui_story_5032_50320802_39_dialog_content = "Correcto, Princesa Carleen. He encontrado una manera de reactivar Windstone.",
  ui_story_5032_50320802_40_dialog_content = "En nombre de toda Harbor City y su gente, permítame expresarle mi más sincero agradecimiento.",
  ui_story_5032_50320802_41_dialog_content = "Gracias por defender a nuestros soldados, nuestra gente y nuestro hogar.",
  ui_story_5032_50320802_42_dialog_content = "No hay necesidad de tales formalidades. Solo estaba cumpliendo con mis deberes.",
  ui_story_5032_50320802_43_dialog_content = "Arriesgaste tu vida desinteresadamente por el bien de Harbor City y su ciudadanía.",
  ui_story_5032_50320802_44_dialog_content = "Cuando pienso en mi anterior desconfianza hacia ti, me llena de una profunda vergüenza.",
  ui_story_5032_50320802_45_dialog_content = "Por lo menos, acepte mi más sincera gratitud.",
  ui_story_5032_50320802_46_dialog_content = "¡Hola, Loewe! ¡Deja ya de pararte!",
  ui_story_5032_50320802_47_dialog_content = "¿Por qué soy el único que hace todo el trabajo ahora?",
  ui_story_5032_50320802_48_dialog_content = "¡Ven aquí y ayúdame a limpiar el resto de estos sucios eclipses!",
  ui_story_5032_50320802_49_dialog_content = "¡No fui el único asignado para proteger a la princesita, sabes!",
  ui_story_5032_50320802_50_dialog_content = "...",
  ui_story_5032_50320802_51_dialog_content = "... No tienes que gritar.",
  ui_story_5032_50320802_52_dialog_content = "Laird Elvis, la situación ha empeorado mucho más allá de mis expectativas.",
  ui_story_5032_50320802_53_dialog_content = "Envié un mensaje a Lumopolis, pero no tengo ni idea de cuándo llegarán los refuerzos.",
  ui_story_5032_50320802_54_dialog_content = "El Darkflow en el aire también se ha vuelto increíblemente denso. A este ritmo, la vida de todos estará en peligro.",
  ui_story_5032_50320802_55_dialog_content = "A pesar de las decenas de Eclipsitas que hemos derrotado, el Darkflow aún flota pesadamente en el aire sobre Harbor City...",
  ui_story_5032_50320802_56_dialog_content = "No nos queda mucho tiempo. Te dejo el Windstone y el sello, Elvis.",
  ui_story_5032_50320802_57_dialog_content = "Lo entiendo, princesa Carleen. Tomaste las decisiones correctas.",
  ui_story_5032_50320802_58_dialog_content = "Pero quédense tranquilos, ahora que he encontrado una manera de activar Windstone... Todo terminará pronto.",
  ui_story_5032_50320802_59_dialog_content = "¿Qué es exactamente este método del que hablas? ¿Hay algo que pueda hacer para ayudar?",
  ui_story_5032_50320802_60_dialog_content = "Sólo déjeme el resto a mí, Su Alteza.",
  ui_story_5032_50320802_61_dialog_content = "Todo lo que te pido es que sigas al mando de nuestras defensas durante un tiempo.",
  ui_story_5032_50320802_62_dialog_content = "Entiendo. Continuaré liderando a los soldados desde aquí y te daré todo el tiempo que necesites.",
  ui_story_5032_50320802_63_dialog_content = "Le agradezco su confianza y todo lo que ha hecho por Harbor City, Su Alteza.",
  ui_story_5032_50320802_64_dialog_content = "Hay una cosa más, aunque suene injusto, dadas las circunstancias... Le pido humildemente que recuerde su juramento de antes.",
  ui_story_5032_50320802_65_dialog_content = "Que mantendrás el mío y el secreto de Harbor City a salvo, una vez que lleguen los refuerzos de Lumopolis.",
  ui_story_5032_50320802_66_dialog_content = "Te he dado mi palabra de que mantendré en secreto cualquier información relacionada con Windstone, y no tengo intención de romper esa promesa.",
  ui_story_5032_50320802_67_dialog_content = "Gracias, Su Alteza. Con tu carácter noble y digno de confianza, confío plenamente en que algún día serás un gobernante excepcional.",
  ui_story_5032_50320802_68_dialog_content = "Ahora bien, ¿puedo preguntarte si sabes dónde está Jeno en este momento?",
  ui_story_5032_50320802_69_dialog_content = "Jeno? Debería estar en la quinta posición defensiva justo adelante.",
  ui_story_5032_50320802_70_dialog_content = "¿Lo necesitas para algo?",
  ui_story_5032_50320802_71_dialog_content = "Por cierto. ¿Podría enviar tropas adicionales para fortalecer su posición actual? Me temo que tendré que sacarlo del frente durante algún tiempo.",
  ui_story_5032_50320802_72_dialog_content = "Comprendo.",
  ui_story_5032_50320802_73_dialog_content = "Bueno, permítame extenderle mi más sincera gratitud nuevamente.",
  ui_story_5032_50320802_74_dialog_content = "Además, me gustaría disculparme por las lesiones o bajas que usted y sus aliados hayan podido sufrir.",
  ui_story_5032_50320802_75_dialog_content = "Haber sabido que ha sido uno de los mayores honores de mi vida, princesa Carleen. Siempre serás conocido como un querido amigo de Harbor City.",
  ui_story_5032_50320802_76_dialog_content = "<size=30>Y ahora, por fin puedo empezar... a expiar los errores que he cometido.</size>",
  ui_story_5032_50320802_77_dialog_content = "Por favor Disculpame.",
  ui_story_5032_50320802_78_dialog_content = "... Elvis.",
  ui_story_5032_50320802_79_dialog_content = "¿Mmm? ¿Hay algo más en su mente, Su Alteza?",
  ui_story_5032_50320802_80_dialog_content = "... No nada.",
  ui_story_5032_50320802_81_dialog_content = "Por favor tenga cuidado.",
  ui_story_5032_50320802_82_dialog_content = "Su preocupación es muy apreciada, princesa Carleen.",
  ui_story_5032_50320802_83_dialog_content = "Permaneceré alerta.",
  ui_story_5032_50320901_1_dialog_content = "¡Muy bien, repasemos el plan por última vez!",
  ui_story_5032_50320901_2_dialog_content = "En unos minutos, Subli desbloqueará la puerta de la terraza. Cuando lo haga, el \"Escuadrón Geedo\" cargará.",
  ui_story_5032_50320901_3_dialog_content = "PlayerName y Fia estarán en nuestro centro, y se encargarán de comandar y proteger a Geedo.",
  ui_story_5032_50320901_4_dialog_content = "Kyllo, Vice, Merylt y yo los rodearemos y rechazaremos a cualquier atacante.",
  ui_story_5032_50320901_5_dialog_content = "Mientras tanto, Ciel, Frimet y Subli se quedarán bajo cubierta para cerrar la puerta detrás de nosotros y seguir buscando otros animales.",
  ui_story_5032_50320901_6_dialog_content = "¿Alguna pregunta?",
  ui_story_5032_50320901_7_dialog_content = "¡No!",
  ui_story_5032_50320901_8_dialog_content = "N-No hay preguntas aquí.",
  ui_story_5032_50320901_9_dialog_content = "*Trago*",
  ui_story_5032_50320901_10_dialog_content = "Qué sonido tan familiar... ¿Te sientes nerviosa, Fia?",
  ui_story_5032_50320901_11_dialog_content = "NNN-¡¡Para nada!!",
  ui_story_5032_50320901_12_dialog_content = "E-Ese era Kyllo tragando hace un momento, ¡n-no yo!",
  ui_story_5032_50320901_13_dialog_content = "Lo?",
  ui_story_5032_50320901_14_dialog_content = "¡Todo estará bien, Fia! ¡Solo finge que es como ese juego de carnaval y estarás bien!",
  ui_story_5032_50320901_15_dialog_content = "Después de todo, son solo un par de eclipses. ¡Nada de qué preocuparse para gente como nosotros!",
  ui_story_5032_50320901_16_dialog_content = "¡Lo, lo!",
  ui_story_5032_50320901_17_dialog_content = "Eh... ¡Vale!",
  ui_story_5032_50320901_18_dialog_content = "<size=30>Excepto que Carleen y Vice fueron los que pelearon durante la competencia...</size>",
  ui_story_5032_50320901_19_dialog_content = "¿Estaré... realmente estaré bien? Estoy tan nervioso...",
  ui_story_5032_50320901_20_dialog_content = "Y ahora, sin más preámbulos... ¡Que comience la siguiente ronda del juego!",
  ui_story_5032_50320901_21_dialog_content = "¡Abre la puerta, Subli!",
  ui_story_5032_50320901_22_dialog_content = "¡Entendido!",
  ui_story_5032_50320902_1_dialog_content = "¿Podemos realmente derrotar a todos estos eclipses?",
  ui_story_5032_50320902_2_dialog_content = "¡Parece que cada vez aparecen más en la playa!",
  ui_story_5032_50320902_3_dialog_content = "¡Gahhhh!",
  ui_story_5032_50320902_4_dialog_content = "¡Argh! ¡E-Hay más viniendo hacia nosotros desde nuestro flanco!",
  ui_story_5032_50320902_5_dialog_content = "Se acabó para nosotros, ¿no es así...?",
  ui_story_5032_50320902_6_dialog_content = "¿Es así como caerá Harbor City? Todavía no le he dicho mi cariño...",
  ui_story_5032_50320902_7_dialog_content = "Si tienes suficiente fuerza para lloriquear y gemir así, entonces aún deberías tener algo de lucha en ti.",
  ui_story_5032_50320902_8_dialog_content = "¿Eh? ¡¿Quién eres?!",
  ui_story_5032_50320902_9_dialog_content = "Vete, viles criaturas de las profundidades.",
  ui_story_5032_50320902_10_dialog_content = "¡Deja que la Verdad te guíe a tu muerte predestinada!",
  ui_story_5032_50320902_11_dialog_content = "¡Gahhhhhh!",
  ui_story_5032_50320902_12_dialog_content = "¡Oye! ¡Es el maestro de ceremonias del circo!",
  ui_story_5032_50320902_13_dialog_content = "¡Es Jeno! ¡Es uno de los amigos cercanos de Laird Elvis!",
  ui_story_5032_50320902_14_dialog_content = "Lo vi peleando en una de nuestras posiciones defensivas antes. ¿Vino a ayudarnos después de ver lo pocos que quedamos?",
  ui_story_5032_50320902_15_dialog_content = "¡Estamos salvados!",
  ui_story_5032_50320902_16_dialog_content = "¡Guau, el maestro de ceremonias es increíblemente fuerte! ¡Atravesó todos esos Eclipsites en un abrir y cerrar de ojos!",
  ui_story_5032_50320902_17_dialog_content = "Mmm... Patético.",
  ui_story_5032_50320902_18_dialog_content = "Si dejas que Eclipsitas débiles como este te asusten para que te rindas, deberías avergonzarte de llamarte guardia de Harbor City.",
  ui_story_5032_50320902_19_dialog_content = "No olvides todas las caras sonrientes de la gente del pueblo que cuentan contigo para protegerlos.",
  ui_story_5032_50320902_20_dialog_content = "Tus padres, tus hijos, tus amigos, tu familia... Todos ellos están en peligro.",
  ui_story_5032_50320902_21_dialog_content = "Encuentren su coraje y reúnanse. Nunca muestres este tipo de debilidad frente al enemigo.",
  ui_story_5032_50320902_22_dialog_content = "Las palabras pueden ser tan devastadoras como las armas y pueden cambiar el curso de tu destino, así como el de tus compañeros de armas. ¡Ahora cállate y concéntrate en la pelea!",
  ui_story_5032_50320902_23_dialog_content = "¡Entendido!",
  ui_story_5032_50320902_24_dialog_content = "En el siguiente...",
  ui_story_5032_50320902_25_dialog_content = "¡Señor Jeno!",
  ui_story_5032_50320902_26_dialog_content = "¿Mmm? Eres tu...",
  ui_story_5032_50320902_27_dialog_content = "¡Finalmente lo encontré, Sr. Jeno!",
  ui_story_5032_50320902_28_dialog_content = "¿Qué estás haciendo aquí? ¿Dónde está Elvis?",
  ui_story_5032_50320902_29_dialog_content = "Yo también estoy aquí, Jeno.",
  ui_story_5032_50320902_30_dialog_content = "¡Elvis! ¿Estás bien?",
  ui_story_5032_50320902_31_dialog_content = "Es demasiado peligroso aquí. Tienes que volver al puesto de mando y encontrar a Carleen.",
  ui_story_5032_50320902_32_dialog_content = "Ella está a cargo allí, así que debería estar más seguro a su lado...",
  ui_story_5032_50320902_33_dialog_content = "Estaba en el puesto de mando preguntando a Su Alteza sobre su paradero, Jeno. Es por eso que he venido a buscarte.",
  ui_story_5032_50320902_34_dialog_content = "¿Buscándome? ¿Por qué?",
  ui_story_5032_50320902_35_dialog_content = "Tiene que ver con la reactivación de Windstone.",
  ui_story_5032_50320902_36_dialog_content = "Encontré una manera de hacerlo, pero necesito su ayuda.",
  ui_story_5032_50320902_37_dialog_content = "Comprendido. Que necesitas que haga?",
  ui_story_5032_50320902_38_dialog_content = "Primero debemos retirarnos a un lugar más seguro, lejos de cualquier posible interferencia de Eclipsite. Te explicaré todo en el camino.",
  ui_story_5032_50320902_39_dialog_content = "Mmm...",
  ui_story_5032_50320902_40_dialog_content = "Me temo que no.",
  ui_story_5032_50320902_41_dialog_content = "Jeno...",
  ui_story_5032_50320902_42_dialog_content = "Guárdalo. Esta es la única cosa con la que me niego a ayudarte.",
  ui_story_5032_50320902_43_dialog_content = "No se de donde sacaste la idea de hacer esto...",
  ui_story_5032_50320902_44_dialog_content = "Pero cualquiera que sobreesfuerce su Lumina de esta manera probablemente morirá.",
  ui_story_5032_50320902_45_dialog_content = "Con mucho gusto te ayudaré a encontrar otra manera, o incluso estaré a tu lado y lucharé hasta mi último aliento...",
  ui_story_5032_50320902_46_dialog_content = "Pero me niego a llevarte a la muerte de esta manera.",
  ui_story_5032_50320902_47_dialog_content = "No tengo dudas sobre la fuerza de nuestra amistad o tu valentía, Jeno.",
  ui_story_5032_50320902_48_dialog_content = "Pero en estas terribles circunstancias, me temo que no nos queda otra opción.",
  ui_story_5032_50320902_49_dialog_content = "Este plan resultará en el menor número de sacrificios posible. Como laird de Harbor City, me corresponde a mí librar a mi pueblo del peligro.",
  ui_story_5032_50320902_50_dialog_content = "¿Crees que tu muerte sería un \"pequeño sacrificio\"? ¿Te golpeó en la cabeza una de esas máquinas explosivas en los terrenos sellados?",
  ui_story_5032_50320902_51_dialog_content = "¿Tienes alguna idea de lo peligroso que sería si transfiriera tu Lumina restante en tu estado actual?",
  ui_story_5032_50320902_52_dialog_content = "¡Un pequeño paso en falso y su Lumina quedará completamente en descubierto!",
  ui_story_5032_50320902_53_dialog_content = "Los riesgos son realmente grandes, pero todavía hay una pequeña posibilidad de éxito, ¿verdad?",
  ui_story_5032_50320902_54_dialog_content = "Por favor, Jeno.",
  ui_story_5032_50320902_55_dialog_content = "Tengo la máxima confianza en su capacidad para controlarlo adecuadamente.",
  ui_story_5032_50320902_56_dialog_content = "Después de todo, eres uno de los mejores magos y artistas.",
  ui_story_5032_50320902_57_dialog_content = "Es muy peligroso. No tengo manera de garantizar su seguridad.",
  ui_story_5032_50320902_58_dialog_content = "Laird Elvis.",
  ui_story_5032_50320902_59_dialog_content = "Discúlpame un momento, Jeno.",
  ui_story_5032_50320902_60_dialog_content = "¿Qué pasa, Patou?",
  ui_story_5032_50320902_61_dialog_content = "Lamento mucho interrumpir su conversación.",
  ui_story_5032_50320902_62_dialog_content = "Pero ha aparecido otro Eclipsite de alto nivel. ¡Retírese a un lugar seguro por el momento!",
  ui_story_5032_50320902_63_dialog_content = "No hay nada que temer, Patou. Mientras Jeno esté aquí, no sufriré ningún daño.",
  ui_story_5032_50320902_64_dialog_content = "Ahora toma los soldados que puedas encontrar y ve a reforzar nuestras defensas.",
  ui_story_5032_50320902_65_dialog_content = "El poder del Eclipsite de alto nivel puede ser bastante impredecible. Me sentiría más seguro si estuvieras al frente de nuestras defensas.",
  ui_story_5032_50320902_66_dialog_content = "Pero...",
  ui_story_5032_50320902_67_dialog_content = "Rápido, Patou. Nuestros hombres te necesitan en primera línea.",
  ui_story_5032_50320902_68_dialog_content = "... Sí, Laird Elvis.",
  ui_story_5032_50320902_69_dialog_content = "¿Ves ahora, Jeno?",
  ui_story_5032_50320902_70_dialog_content = "Esta inundación interminable de eclipses ahogará nuestras fuerzas restantes más temprano que tarde.",
  ui_story_5032_50320902_71_dialog_content = "Y eso sin mencionar este Darkflow cada vez más intenso, que amenaza con sofocar a cualquiera que sobreviva al ataque.",
  ui_story_5032_50320902_72_dialog_content = "Los refuerzos de la Princesa Carleen están casi agotados, y nuestras posiciones defensivas están cayendo ante los Eclipsites una por una.",
  ui_story_5032_50320902_73_dialog_content = "Por cada segundo que pasamos debatiendo, los Eclipsites destrozan a otro soldado.",
  ui_story_5032_50320902_74_dialog_content = "Y todo este sufrimiento... fue provocado por mis propias manos.",
  ui_story_5032_50320902_75_dialog_content = "¡Pero no tenías idea de que llegaría a esto! ¡No es tu culpa!",
  ui_story_5032_50320902_76_dialog_content = "Jejeje Un error es un error, y alguien debe asumir la responsabilidad por ello. ¿No es esta una de las primeras lecciones que le enseñamos a nuestros más pequeños?",
  ui_story_5032_50320902_77_dialog_content = "Además, sigo siendo el laird de Harbor City. Más que nada, deseo protegerlo, ya mi gente.",
  ui_story_5032_50320902_78_dialog_content = "...",
  ui_story_5032_50320902_79_dialog_content = "Una vez dijiste que querías protegerme. ¿Recuerda?",
  ui_story_5032_50320902_80_dialog_content = "...Sí.",
  ui_story_5032_50320902_81_dialog_content = "Proteger a alguien no significa simplemente mantener viva a esa persona, Jeno... A veces, significa mantener vivo su sueño. ¿No estarías de acuerdo?",
  ui_story_5032_50320902_82_dialog_content = "Mi sueño es que la gente de Harbor City regrese a la vida pacífica y feliz que alguna vez conoció.",
  ui_story_5032_50320902_83_dialog_content = "Pueden experimentar más dolor en el camino y escribir más historias tristes en las páginas de nuestra historia.",
  ui_story_5032_50320902_84_dialog_content = "Pero al menos, tendrán un lugar al que llamar hogar... Un lugar donde sus sonrisas puedan florecer una vez más.",
  ui_story_5032_50320902_85_dialog_content = "Ver una sonrisa en cada uno de sus rostros siempre ha sido mi sueño.",
  ui_story_5032_50320902_86_dialog_content = "Así que te pregunto una vez más, Jeno. ¿Me ayudarás a mantener vivo mi sueño?",
  ui_story_5032_50320902_87_dialog_content = "... ¿Cómo pudiste hacerme esto a mí?",
  ui_story_5032_50320902_88_dialog_content = "¿Qué?",
  ui_story_5032_50320902_89_dialog_content = "Me estás obligando... a ponerte un cuchillo en la garganta y usar toda esta charla sobre sueños y rectitud para justificarlo.",
  ui_story_5032_50320902_90_dialog_content = "Yo... lo siento mucho, Jeno.",
  ui_story_5032_50320902_91_dialog_content = "Por cosas que pasaron hace años, en la Esmeralda, y ahora también...",
  ui_story_5032_50320902_92_dialog_content = "Lo siento mucho, Jeno... por todo.",
  ui_story_5032_50320902_93_dialog_content = "Sé que no soy digno de ser llamado tu amigo, y mucho menos el laird de Harbor City.",
  ui_story_5032_50320902_94_dialog_content = "Mi terquedad y paranoia son las que causaron que todo llegara a esto.",
  ui_story_5032_50320902_95_dialog_content = "También fuiste arrastrado a mis problemas y por eso... Solo puedo disculparme una vez más.",
  ui_story_5032_50320902_96_dialog_content = "Pero si dejo que esta oportunidad se me escape de las manos y permito que los Eclipsites entren en mi casa...",
  ui_story_5032_50320902_97_dialog_content = "Nunca me perdonaré por el resto de mi vida sin valor.",
  ui_story_5032_50320902_98_dialog_content = "Así que llámame egoísta, llámame tonto, llámame como quieras... Pero te lo ruego... Por favor, ayúdame.",
  ui_story_5032_50320902_99_dialog_content = "...",
  ui_story_5032_50320902_100_dialog_content = "*Suspiro* Desde que éramos niños, nunca pude hacerte cambiar de opinión... o rechazarte, para el caso.",
  ui_story_5032_50320902_101_dialog_content = "Lo haré, pero tan pronto como detecte el más mínimo indicio de peligro, detendré todo el ritual.",
  ui_story_5032_50320902_102_dialog_content = "Jejeje... No tengo objeciones.",
  ui_story_5032_50320902_103_dialog_content = "Ahora, ¿cómo deberíamos empezar?",
  ui_story_5032_50321001_1_dialog_content = "El terreno sellado ya ha sido destruido. Para reactivar Windstone, solo tenemos un último método.",
  ui_story_5032_50321001_2_dialog_content = "A saber, el método empleado por nuestros antepasados para activar Windstone en épocas pasadas... Se debe hacer un nuevo pacto con Windstone.",
  ui_story_5032_50321001_3_dialog_content = "Pero, ¿cómo lo potenciaremos?",
  ui_story_5032_50321001_4_dialog_content = "Las reservas de energía del Windstone están casi completamente agotadas, es cierto.",
  ui_story_5032_50321001_5_dialog_content = "Tal vez solo se pueda hacer como antes: usando la Lumina de los Aurorianos para sostenerlo constantemente...",
  ui_story_5032_50321001_6_dialog_content = "Pensándolo bien, realmente soy un fracaso...",
  ui_story_5032_50321001_7_dialog_content = "No... Has hecho todo lo que puedes, Elvis. Esto no es tu culpa.",
  ui_story_5032_50321001_8_dialog_content = "Aun así, hablar de esto no ayudará a nuestra situación. Debemos mantener nuestras mentes en Windstone.",
  ui_story_5032_50321001_9_dialog_content = "Para activar Windstone, mis antepasados crearon el suelo sellado.",
  ui_story_5032_50321001_10_dialog_content = "A través del suelo sellado, Windstone puede establecer una especie de vínculo con los aurorianos, lo que le permite reunir su Lumina.",
  ui_story_5032_50321001_11_dialog_content = "*Tos, tos* Las capacidades del suelo sellado... no son del todo diferentes a las del <color=#FFB400>energía</color> tu mandas",
  ui_story_5032_50321001_12_dialog_content = "Deseas usar mis poderes para simular los efectos del suelo sellado y reactivar Windstone de manera segura. ¿Es asi?",
  ui_story_5032_50321001_13_dialog_content = "Así es.",
  ui_story_5032_50321001_14_dialog_content = "... Está bien, seguiré tu plan.",
  ui_story_5032_50321001_15_dialog_content = "Pero como dije antes: en el momento en que percibo el más mínimo peligro, estoy cortando la conexión entre tú y Windstone.",
  ui_story_5032_50321001_16_dialog_content = "Muy bien... el resto te lo dejo a ti, amigo.",
  ui_story_5032_50321001_17_dialog_content = "¡Por el bien de Harbor City y su gente, el ritual debe tener éxito!",
  ui_story_5032_50321001_18_dialog_content = "Cierra los ojos e imagínate sosteniendo el Windstone en tus manos...",
  ui_story_5032_50321001_19_dialog_content = "Mmm...",
  ui_story_5032_50321001_20_dialog_content = "Sí, solo así. Estoy a punto de comenzar la transferencia, así que trata de no resistirte.",
  ui_story_5032_50321001_21_dialog_content = "Jejeje... Yo no soñaría con eso.",
  ui_story_5032_50321001_22_dialog_content = "Estableciendo la conexión entre tu Lumina y el Windstone...",
  ui_story_5032_50321001_23_dialog_content = "Ugh... *Tos, tos*",
  ui_story_5032_50321001_24_dialog_content = "Muy bien, he hecho lo que me pediste que hiciera.",
  ui_story_5032_50321001_25_dialog_content = "¡Adelante, Elvis!",
  ui_story_5032_50321001_26_dialog_content = "¡Piedra de viento! ¡Comienza la reactivación!",
  ui_story_5032_50321001_27_dialog_content = "Detector <color=#FFB400>energía</color> aporte...",
  ui_story_5032_50321001_28_dialog_content = "Genotipo auroriano detectado... Conexión establecida. Iniciando extracción de Lumina...",
  ui_story_5032_50321001_29_dialog_content = "Ahora todo lo que tengo que hacer... es...",
  ui_story_5032_50321001_30_dialog_content = "¡Gahhhhhh!",
  ui_story_5032_50321001_31_dialog_content = "Se están reuniendo a nuestro alrededor. ¿Sienten la amenaza de la reactivación de Windstone?",
  ui_story_5032_50321001_32_dialog_content = "Déjame estos eclipses a mí.",
  ui_story_5032_50321002_1_dialog_content = "Sólo un poco más...",
  ui_story_5032_50321002_2_dialog_content = "La reactivación del sistema está en curso...",
  ui_story_5032_50321002_3_dialog_content = "*Hackear* Argh...!",
  ui_story_5032_50321002_4_dialog_content = "¡¿Por qué el Windstone está absorbiendo más y más Lumina?!",
  ui_story_5032_50321002_5_dialog_content = "¡Detén la reactivación, Elvis! ¡Tu cuerpo no puede soportar este tipo de tensión!",
  ui_story_5032_50321002_6_dialog_content = "¡Morirás a este ritmo!",
  ui_story_5032_50321002_7_dialog_content = "No hay... ninguna parada ahora...",
  ui_story_5032_50321002_8_dialog_content = "¡Solo espera! ¡Cortaré la conexión entre tú y Windstone!",
  ui_story_5032_50321002_9_dialog_content = "¿Eh?",
  ui_story_5032_50321002_10_dialog_content = "Elvis, ¿te estás resistiendo?",
  ui_story_5032_50321002_11_dialog_content = "No... ¡Es la Piedra del Viento! Se ha apoderado del enlace que creé, ¡así que no puedo romperlo!",
  ui_story_5032_50321002_12_dialog_content = "Pero, ¿cómo podría ser esto? ¡Contéstame, Elvis!",
  ui_story_5032_50321002_13_dialog_content = "Parece que no tiene sentido seguir mintiéndole.",
  ui_story_5032_50321002_14_dialog_content = "Lo cierto es que los terrenos sellados cumplen dos funciones.",
  ui_story_5032_50321002_15_dialog_content = "Una es permitir que los aurorianos usen Lumina para establecer una conexión con Windstone para que puedan controlarlo.",
  ui_story_5032_50321002_16_dialog_content = "El otro es controlar la velocidad a la que Windstone extrae Lumina... para evitar que mate a los aurorianos que lo activan.",
  ui_story_5032_50321002_17_dialog_content = "Me ocultaste la función secundaria de los terrenos sellados...",
  ui_story_5032_50321002_18_dialog_content = "¡Sabías que mis poderes solo podían simular la primera función!",
  ui_story_5032_50321002_19_dialog_content = "Busqué por todas partes una manera de reactivar Windstone... Una que no requiriera los terrenos sellados... Pero al final...",
  ui_story_5032_50321002_20_dialog_content = "Windstone solo se había activado una vez en la historia escrita. El conocimiento sobre el tema era bastante limitado.",
  ui_story_5032_50321002_21_dialog_content = "Mi única opción... era arriesgarme...",
  ui_story_5032_50321002_22_dialog_content = "Incluso si eso significaba... sacrificarme.",
  ui_story_5032_50321002_23_dialog_content = "¡¿Sabías que iba a terminar así, verdad?!",
  ui_story_5032_50321002_24_dialog_content = "Perdóname... Jeno...",
  ui_story_5032_50321002_25_dialog_content = "Esta fue... la única otra manera que pude encontrar...",
  ui_story_5032_50321002_26_dialog_content = "¡Solo sacrificándome y ofreciendo hasta la última onza de Lumina en mi cuerpo... podría garantizar la reactivación de Windstone! *Tos tos*",
  ui_story_5032_50321002_27_dialog_content = "¡¿Cómo pudiste engañarme así?!",
  ui_story_5032_50321002_28_dialog_content = "Así es... Te engañé una vez más.",
  ui_story_5032_50321002_29_dialog_content = "¿Por qué... por qué sigo haciéndote esto?",
  ui_story_5032_50321002_30_dialog_content = "Nunca quise ocultarte nada... Crecer fue lo más difícil que tuve que hacer...",
  ui_story_5032_50321002_31_dialog_content = "Heh... Pero ahora... finalmente puedo expiar mis malas acciones...",
  ui_story_5032_50321002_32_dialog_content = "Este es mi destino... así como el destino de los Modali.",
  ui_story_5032_50321002_33_dialog_content = "Al reactivar Windstone, toda Harbor City estará a salvo una vez más...",
  ui_story_5032_50321002_34_dialog_content = "*Tose*",
  ui_story_5032_50321002_35_dialog_content = "Elvis...",
  ui_story_5032_50321002_36_dialog_content = "¿Eres una especie de idiota?",
  ui_story_5032_50321002_37_dialog_content = "¿J-Jeno?",
  ui_story_5032_50321002_38_dialog_content = "La responsabilidad de proteger Harbor City no es tuya y solo tuya.",
  ui_story_5032_50321002_39_dialog_content = "¡No olvides que Harbor City y Emerald... también son mi hogar!",
  ui_story_5032_50321002_40_dialog_content = "No eres el único en el escenario, ¡así que deja de pensar que el centro de atención te pertenece únicamente a ti!",
  ui_story_5032_50321002_41_dialog_content = "¡No te detengas! ¡No quiero arrastrarte a esto!",
  ui_story_5032_50321002_42_dialog_content = "¡Corta tu conexión!",
  ui_story_5032_50321002_43_dialog_content = "No nos hemos visto en años... No es fácil encontrarnos estos días, ¿sabes...?",
  ui_story_5032_50321002_44_dialog_content = "¿Crees que te dejaré escapar tan fácilmente?",
  ui_story_5032_50321002_45_dialog_content = "Aunque siempre he sido el pasivo e inmaduro...",
  ui_story_5032_50321002_46_dialog_content = "Juré que protegería lo que buscaba proteger.",
  ui_story_5032_50321002_47_dialog_content = "No voy a faltar a mi palabra nunca más.",
  ui_story_5032_50321002_48_dialog_content = "Jeno...",
  ui_story_5032_50321002_49_dialog_content = "Nueva entrada de energía detectada. Estableciendo conexión...",
  ui_story_5032_50321002_50_dialog_content = "Ya es demasiado tarde, Elvis. Tú y yo estamos ahora en el mismo barco que se hunde.",
  ui_story_5032_50321002_51_dialog_content = "Je... Jeje... Que gusto de ti hacer algo como esto.",
  ui_story_5032_50321002_52_dialog_content = "Ya no eres ese niño pequeño que necesita mi protección.",
  ui_story_5032_50321002_53_dialog_content = "Ahora bien... Veamos qué tipo de trucos de magia tienes para ofrecer.",
  ui_story_5032_50321002_54_dialog_content = "Ha... Para mi acto final... Nos convertiré a ambos en la fuente de poder de esta piedra...",
  ui_story_5032_50321002_55_dialog_content = "<color=#e8d9bb>Mientras tanto, a bordo del Esmeralda</color>",
  ui_story_5032_50321002_56_dialog_content = "¡Gahhhh!",
  ui_story_5032_50321002_57_dialog_content = "¡¿Por qué hay tantos eclipses aquí?!",
  ui_story_5032_50321002_58_dialog_content = "¡E-Hay más de ellos trepando por el casco del barco!",
  ui_story_5032_50321002_59_dialog_content = "¡Las aguas están llenas de eclipses! ¡¡Soy demasiado joven para que me coman vivo!!",
  ui_story_5032_50321002_60_dialog_content = "¡¡¡Gahhhh!!!",
  ui_story_5032_50321002_61_dialog_content = "¡Fia!",
  ui_story_5032_50321002_62_dialog_content = "¡Rainbow!",
  ui_story_5032_50321002_63_dialog_content = "¡Mirar! ¡No hay eclipses en la proa del barco! ¡Tienes que ir allí y liberar a Geedo!",
  ui_story_5032_50321002_64_dialog_content = "¡Te abriré un camino!",
  ui_story_5032_50321002_65_dialog_content = "¡Yo... tengo que ser fuerte! ¡Por el bien de Geedo!",
  ui_story_5032_50321002_66_dialog_content = "Graah! ¡Rugido!",
  ui_story_5032_50321002_67_dialog_content = "Fuera de mi camino-!",
  ui_story_5032_50321002_68_dialog_content = "¡Llegamos a la proa! ¡Ahora solo tengo que abrir la botella!",
  ui_story_5032_50321002_69_dialog_content = "¡Uh!",
  ui_story_5032_50321002_70_dialog_content = "¿Por qué la tapa está tan apretada?",
  ui_story_5032_50321002_71_dialog_content = "Graaaaah!",
  ui_story_5032_50321002_72_dialog_content = "¡Oh, no! ¡Uno de ellos logró pasar!",
  ui_story_5032_50321002_73_dialog_content = "¡Cuidado, Fía!",
  ui_story_5032_50321002_74_dialog_content = "¡¡¡Waaaah!!!",
  ui_story_5032_50321002_75_dialog_content = "¡Graaaaooo!",
  ui_story_5032_50321002_76_dialog_content = "¡Nooo!",
  ui_story_5032_50321002_77_dialog_content = "¡Fia! Cuídate de mi!!!",
  ui_story_5032_50321002_78_dialog_content = "¡Ah—!",
  ui_story_5032_50321002_79_dialog_content = "PlayerName! ¡¿Qué estás haciendo aquí abajo también?!",
  ui_story_5032_50321002_80_dialog_content = "¡Me resbalé!",
  ui_story_5032_50321002_81_dialog_content = "¡Nooo! Ahora nunca podré comer los dulces que escondí en mi habitación... ¡¿Es así como termina para mí?!",
  ui_story_5032_50321002_82_dialog_content = "¡Tampoco pude usar todo el dinero que tanto me costó ganar!",
  ui_story_5032_50321002_83_dialog_content = "Glub, glub, glub...",
  ui_story_5032_50321002_84_dialog_content = "(Yo... no puedo respirar...)",
  ui_story_5032_50321002_85_dialog_content = "<color=#e8d9bb>Auge-!</color>",
  ui_story_5032_50321002_86_dialog_content = "A mi alrededor... El sonido del agua rompiendo...",
  ui_story_5032_50321002_87_dialog_content = "Puedo respirar de nuevo... ¿Será que estoy... muerta?",
  ui_story_5032_50321002_88_dialog_content = "no seas tonto PlayerName! ¡Todavía estás vivo, y yo también!",
  ui_story_5032_50321002_89_dialog_content = "¡Abre los ojos y compruébalo por ti mismo! ¡Geedo nos salvó!",
  ui_story_5032_50321002_90_dialog_content = "¡¡E-Es enorme!!",
  ui_story_5032_50321002_91_dialog_content = "¡No tenía idea de que Geedo pudiera llegar a ser tan grande! Además... ¡¿Geedo está volando?!",
  ui_story_5032_50321002_92_dialog_content = "El Cloudwhale es una bestia maravillosa exótica, después de todo. ¡Volar no está tan lejos de la cuestión!",
  ui_story_5032_50321002_93_dialog_content = "Sin embargo, debo admitir que tampoco tenía idea de que Geedo pudiera volar...",
  ui_story_5032_50321002_94_dialog_content = "<color=#e8d9bb>Estruendo...</color>",
  ui_story_5032_50321002_95_dialog_content = "¿Qué fue ese rugido sordo de hace un momento? Además... ¿Soy yo, o sientes que algo tiembla?",
  ui_story_5032_50321002_96_dialog_content = "Uh-oh... Agáchate y agárrate fuerte, PlayerName!",
  ui_story_5032_50321002_97_dialog_content = "¡¿Qué?!",
  ui_story_5032_50321002_98_dialog_content = "¿¿Eh??",
  ui_story_5032_50321002_99_dialog_content = "¡Oooooh!",
  ui_story_5032_50321002_100_dialog_content = "¿Es... está chorreando como una ballena?",
  ui_story_5032_50321002_101_dialog_content = "<color=#e8d9bb>¡Retumbar!</color>",
  ui_story_5032_50321002_102_dialog_content = "¡Qué increíble chorro de agua! ¡Se siente como si estuviéramos parados bajo la lluvia!",
  ui_story_5032_50321002_103_dialog_content = "Grah! Graaaaaah!",
  ui_story_5032_50321002_104_dialog_content = "Graah... Graaaaah...",
  ui_story_5032_50321002_105_dialog_content = "El agua... ¡Parece que está afectando a los eclipses!",
  ui_story_5032_50321002_106_dialog_content = "¿Tenía Fia razón todo el tiempo?",
  ui_story_5032_50321101_1_dialog_content = "*Tosiendo* Los Eclipsites... ¿Por qué sus movimientos parecen tan lentos ahora?",
  ui_story_5032_50321101_2_dialog_content = "El Darkflow parece estar disminuyendo también...",
  ui_story_5032_50321101_3_dialog_content = "¿Podría esa enorme bestia en el cielo ser responsable de esto?",
  ui_story_5032_50321101_4_dialog_content = "¿Es eso... una Ballena Nube?",
  ui_story_5032_50321101_5_dialog_content = "Ahora que lo pienso, esa niña estaba hablando de buscar uno antes... Fia, ¿creo?",
  ui_story_5032_50321101_6_dialog_content = "Y todo este tiempo, pensé que ella era solo una niña ingenua persiguiendo un cuento de hadas...",
  ui_story_5032_50321101_7_dialog_content = "¡Nunca pensé que ella realmente lo encontraría!",
  ui_story_5032_50321101_8_dialog_content = "¿Una ballena nubosa?",
  ui_story_5032_50321101_9_dialog_content = "Sí... Un tipo increíblemente raro de bestia maravillosa, uno tan raro que se ha convertido en materia de leyendas... Incluso yo solo he visto representaciones de él en libros.",
  ui_story_5032_50321101_10_dialog_content = "Aunque su cuerpo se parece al de una ballena, también es capaz de volar y reside muy por encima de las nubes.",
  ui_story_5032_50321101_11_dialog_content = "Su poderosa Lumina es capaz de disuadir a los Eclipsites y disipar incluso el Darkflow más espeso.",
  ui_story_5032_50321101_12_dialog_content = "Fuera de eso, hay muy poco conocimiento sobre las ballenas de las nubes, dado lo raras que son.",
  ui_story_5032_50321101_13_dialog_content = "Comprendo.",
  ui_story_5032_50321101_14_dialog_content = "Todavía te gusta leer sobre leyendas y cuentos de fantasía... *Tos, tos*",
  ui_story_5032_50321101_15_dialog_content = "Como mínimo, parece que no tenemos que preocuparnos por la interferencia de los eclipses cercanos por ahora.",
  ui_story_5032_50321101_16_dialog_content = "Tienes razón... Parece que Harbor City realmente está bendecida por lo divino, después de todo.",
  ui_story_5032_50321101_17_dialog_content = "La ciudad no solo tiene un tonto como laird que está dispuesto a arriesgar su vida por ella... sino que ahora tiene la protección de una de las bestias maravillosas más raras del mundo.",
  ui_story_5032_50321101_18_dialog_content = "Jejeje... No solo eso...",
  ui_story_5032_50321101_19_dialog_content = "La ciudad también tiene un mago lunático... Uno que está dispuesto a acompañar al laird de la ciudad en todos sus estúpidos esfuerzos...",
  ui_story_5032_50321101_20_dialog_content = "Harbor City realmente tiene suerte... Y yo también... *Tos, tos*",
  ui_story_5032_50321101_21_dialog_content = "*Tosiendo* ¡Uf!",
  ui_story_5032_50321101_22_dialog_content = "Haa... ¿Estoy... en mi límite?",
  ui_story_5032_50321101_23_dialog_content = "Túmbate aquí por ahora. Trate de no hablar. Necesitas guardar tu fuerza.",
  ui_story_5032_50321101_24_dialog_content = "Como ya no tenemos que preocuparnos por los Eclipsites, tengo más Lumina de sobra.",
  ui_story_5032_50321101_25_dialog_content = "Tú... ¿vas a aumentar tu propia entrada de Lumina?",
  ui_story_5032_50321101_26_dialog_content = "Urgh... Sentir que mi Lumina se escapa así... Se siente horrible.",
  ui_story_5032_50321101_27_dialog_content = "¿Es esto con lo que has estado lidiando todo este tiempo, Elvis?",
  ui_story_5032_50321101_28_dialog_content = "Por favor... ¡Basta, Jeno! Si continúas... ¡También morirás!",
  ui_story_5032_50321101_29_dialog_content = "Es solo una pequeña Lumina... No dejaré que me dejes atrás otra vez.",
  ui_story_5032_50321101_30_dialog_content = "Esta vez... ¡Me pararé justo frente a ti!",
  ui_story_5032_50321101_31_dialog_content = "*tose* Jeno...",
  ui_story_5032_50321101_32_dialog_content = "Extracción de energía completa.",
  ui_story_5032_50321101_33_dialog_content = "El sistema está listo para activarse.",
  ui_story_5032_50321101_34_dialog_content = "Finalmente te llenaste, ¿eh?",
  ui_story_5032_50321101_35_dialog_content = "¿Quién hubiera imaginado que una piedra tan pequeña podría contener tanta Lumina?",
  ui_story_5032_50321101_36_dialog_content = "*Tosiendo*",
  ui_story_5032_50321101_37_dialog_content = "¡Elvis! ¿Estás bien?",
  ui_story_5032_50321101_38_dialog_content = "*Jadeando* Jeno... Cuando todo se haya arreglado... Por favor, dale el Windstone a Patou en mi lugar.",
  ui_story_5032_50321101_39_dialog_content = "Yo... ya le he dicho... exactamente lo que hay que hacer.",
  ui_story_5032_50321101_40_dialog_content = "Elvis...",
  ui_story_5032_50321101_41_dialog_content = "Prométeme, Jeno... Prométeme que le entregarás el Windstone a Patou.",
  ui_story_5032_50321101_42_dialog_content = "Puedes dárselo tú mismo una vez que se reactive el sello.",
  ui_story_5032_50321101_43_dialog_content = "Por favor, Jeno... Solo ayúdame una última vez... Me siento tan cansada...",
  ui_story_5032_50321101_44_dialog_content = "Desde el día que te dejé... siempre me he sentido... tan cansada...",
  ui_story_5032_50321101_45_dialog_content = "Por favor... Déjame descansar un rato, ¿quieres?",
  ui_story_5032_50321101_46_dialog_content = "...",
  ui_story_5032_50321101_47_dialog_content = "Entiendo.",
  ui_story_5032_50321101_48_dialog_content = "Gracias, Jeno.",
  ui_story_5032_50321101_49_dialog_content = "Gracias por todo.",
  ui_story_5032_50321101_50_dialog_content = "Piedra de viento... Activar.",
  ui_story_5032_50321101_51_dialog_content = "Comando reconocido.",
  ui_story_5032_50321101_52_dialog_content = "¿Qué es esa luz? ¡Es tan brillante!",
  ui_story_5032_50321101_53_dialog_content = "¡Está en la dirección a donde fue Laird Elvis! ¿Podría estar en peligro?",
  ui_story_5032_50321101_54_dialog_content = "¡Mirar! Los eclipses... ¡Se están retirando al mar!",
  ui_story_5032_50321101_55_dialog_content = "¡Estás bien! ¡Incluso los Eclipsites de alto nivel están retrocediendo!",
  ui_story_5032_50321101_56_dialog_content = "¡El Darkflow se está disipando! ¡¡Me siento viva otra vez!!",
  ui_story_5032_50321101_57_dialog_content = "¡Debe ser el Laird Elvis! ¡Debe haber encontrado una manera de derrotar a los Eclipsites!",
  ui_story_5032_50321101_58_dialog_content = "¡Esto tiene que ser obra del Laird Elvis!",
  ui_story_5032_50321101_59_dialog_content = "¿Escuchas eso, Elvis?",
  ui_story_5032_50321101_60_dialog_content = "Tu pueblo está clamando por ti... Están celebrando esta victoria en tu nombre.",
  ui_story_5032_50321101_61_dialog_content = "Lo hiciste. El Windstone y el sello han sido reactivados.",
  ui_story_5032_50321101_62_dialog_content = "Jejeje... Estoy encantada de escucharlo.",
  ui_story_5032_50321101_63_dialog_content = "También dijiste que me compensarías antes, ¿recuerdas?",
  ui_story_5032_50321101_64_dialog_content = "Una vez que se asiente el polvo, planeo recolectar por completo... Así que prepárate.",
  ui_story_5032_50321101_65_dialog_content = "Mi barco necesita reparaciones desesperadamente y tú serás el responsable de que vuelva a estar en condiciones de navegar.",
  ui_story_5032_50321101_66_dialog_content = "Puede que sea un mago, pero prometo no engañarlo sobre el costo de las reparaciones. De hecho, haré que Rainbow elabore una lista detallada para dejar todo perfectamente claro. Todo lo que necesita hacer es tener su billetera lista.",
  ui_story_5032_50321101_67_dialog_content = "Ya veo... Eso no debería ser un problema...",
  ui_story_5032_50321101_68_dialog_content = "Además, dado que no tenemos forma de continuar nuestro recorrido, nos quedaremos en Harbor City por un tiempo más.",
  ui_story_5032_50321101_69_dialog_content = "Mientras tanto, podemos intentar construir ese restaurante de arte del que solíamos hablar.",
  ui_story_5032_50321101_70_dialog_content = "¿Quién sabe? ¿Tal vez pueda servir como nuestro lugar para futuras actuaciones?",
  ui_story_5032_50321101_71_dialog_content = "Además, alguien de tu estatus no debería tener problemas para construir un restaurante aquí...",
  ui_story_5032_50321101_72_dialog_content = "Jeno...",
  ui_story_5032_50321101_73_dialog_content = "¿Sí? Estoy aquí, Elvis.",
  ui_story_5032_50321101_74_dialog_content = "El cielo sobre Harbor City... se está despejando.",
  ui_story_5032_50321101_75_dialog_content = "Esta siempre ha sido... mi vista favorita.",
  ui_story_5032_50321101_76_dialog_content = "<size=30>¿Podrías... pintarlo para mí algún día?</size>",
  ui_story_5032_50321101_77_dialog_content = "Por supuesto. Prometo.",
  ui_story_5032_50321101_78_dialog_content = "¿Recuerdas el cuadro que pediste la última vez? Lo terminé hace mucho tiempo... Ha estado colgado en mi habitación todo este tiempo.",
  ui_story_5032_50321101_79_dialog_content = "Pero puede que no sea exactamente lo que querías. Después de todo, tuve que depender por completo de la memoria para pintarlo.",
  ui_story_5032_50321101_80_dialog_content = "Puedes echar un vistazo por ti mismo más tarde. Si no te gusta, siempre puedo pintarte otro.",
  ui_story_5032_50321101_81_dialog_content = "...",
  ui_story_5032_50321101_82_dialog_content = "... ¿Elvis?",
  ui_story_5032_50321101_83_dialog_content = "...",
  ui_story_5032_50321101_84_dialog_content = "Tch... Eres otra cosa, ¿lo sabías?",
  ui_story_5032_50321101_85_dialog_content = "Siempre haz promesas que no puedas cumplir...",
  ui_story_5032_50321101_86_dialog_content = "Eres tan mentiroso, Elvis...",
  ui_story_5032_50321101_87_dialog_content = "Un mentiroso bueno para nada...",
  ui_story_5032_50321101_88_dialog_content = "<color=#e8d9bb>Cinco días después</color>",
  ui_story_5032_50321101_89_dialog_content = "*Suspiro*",
  ui_story_5032_50321101_90_dialog_content = "Parece que olvidaste tu ropa, PlayerName. Alguien pasó y los dejó.",
  ui_story_5032_50321101_91_dialog_content = "¡T-Tienes razón, casi me olvido de empacarlos! ¡Gracias Vice!",
  ui_story_5032_50321101_92_dialog_content = "La decisión de Carleen de irse a casa fue una sorpresa, así que en mi prisa por empacar todo, casi me perdí algunas cosas.",
  ui_story_5032_50321101_93_dialog_content = "*Suspiro*",
  ui_story_5032_50321101_94_dialog_content = "¿Por qué no vuelves a mirar a tu alrededor y te aseguras de no olvidar nada más? Carleen todavía se está reuniendo con los funcionarios de la ciudad, así que tienes tiempo para una última verificación.",
  ui_story_5032_50321101_95_dialog_content = "Claro, iré a echar un vistazo.",
  ui_story_5032_50321101_96_dialog_content = "*Suspiro*",
  ui_story_5032_50321101_97_dialog_content = "... ¿Qué pasa, Fia?",
  ui_story_5032_50321101_98_dialog_content = "¿Tienes algo en mente, Fia? Has estado frunciendo el ceño desde que nos levantamos esta mañana.",
  ui_story_5032_50321101_99_dialog_content = "Solo estoy pensando en cómo Geedo nos dejó tan repentinamente...",
  ui_story_5032_50321101_100_dialog_content = "¡¿Cómo se supone que voy a explicarle esto a mi maestro?!",
  ui_story_5032_50321101_101_dialog_content = "Lo...",
  ui_story_5032_50321101_102_dialog_content = "Tu maestro debería poder sentir la presencia de Geedo nuevamente, ¿no crees?",
  ui_story_5032_50321101_103_dialog_content = "Estoy seguro de que lo notó en el momento en que liberaste a Geedo de la botella.",
  ui_story_5032_50321101_104_dialog_content = "No lo entiendes, Vice... ¡Si no le muestro la prueba en su cara de que mi misión está completa, no pagará!",
  ui_story_5032_50321101_105_dialog_content = "Fingirá que estoy mintiendo, y todas las recompensas que me prometió por un trabajo bien hecho... ¡Las tirará todas por la borda!",
  ui_story_5032_50321101_106_dialog_content = "Me parece una relación justa y equitativa, Fia.",
  ui_story_5032_50321101_107_dialog_content = "Eso es suficiente de ti, PlayerName!",
  ui_story_5032_50321101_108_dialog_content = "El maestro de Fia suena un poco excesivo, ¿no crees?",
  ui_story_5032_50321101_109_dialog_content = "Qué debemos hacer, PlayerName? ¿Crees que podemos llevar a Fia con nosotros y llevarla a casa en Soroz?",
  ui_story_5032_50321101_110_dialog_content = "De esa manera, podemos actuar como sus testigos.",
  ui_story_5032_50321101_111_dialog_content = "¡Suena bien para mí!",
  ui_story_5032_50321101_112_dialog_content = "¿E-eh? ¡¿En realidad?! ¡Eso será grandioso!",
  ui_story_5032_50321101_113_dialog_content = "¡Muchas gracias Vice! ¡Esta vez haré que el amo pague todo lo que me debe! ¡Muajajaja!",
  ui_story_5032_50321101_114_dialog_content = "Ustedes tres parecen estar muy animados, ¿eh?",
  ui_story_5032_50321101_115_dialog_content = "¡Ay! ¿Acabo de escuchar la voz de Subli?",
  ui_story_5032_50321101_116_dialog_content = "Yo-ho! Aquí tienes.",
  ui_story_5032_50321101_117_dialog_content = "Rainbow nos dijo que te ibas, ¡así que queríamos despedirte nosotros mismos!",
  ui_story_5032_50321101_118_dialog_content = "...",
  ui_story_5032_50321101_119_dialog_content = "¡Viajes seguros, todos!",
  ui_story_5032_50321101_120_dialog_content = "¡Ven a ver nuestro programa la próxima vez que tengas la oportunidad! ¡Te conseguiré una buena oferta en asientos de primera!",
  ui_story_5032_50321101_121_dialog_content = "¡Jajaja! ¡Podríamos aceptar esa oferta!",
  ui_story_5032_50321101_122_dialog_content = "Oye... No veo a Ciel por ninguna parte. ¿Ella no vino contigo, Rainbow?",
  ui_story_5032_50321101_123_dialog_content = "Ciel recibió una citación de emergencia de Illumina ayer. Ella también se fue con mucha prisa.",
  ui_story_5032_50321101_124_dialog_content = "Ya veo... Seguro que Ciel se mantiene ocupado, ¿no? Incluso la llamaron de sus vacaciones...",
  ui_story_5032_50321101_125_dialog_content = "Se suponía que íbamos a empezar las reparaciones en el Emerald hoy...",
  ui_story_5032_50321101_126_dialog_content = "Pero Merylt prácticamente rogó por una última oportunidad de ver a Caelestite, por eso...",
  ui_story_5032_50321101_127_dialog_content = "¡Ay!",
  ui_story_5032_50321101_128_dialog_content = "¡F-Frimet!",
  ui_story_5032_50321101_129_dialog_content = "Jajajaja! Parece que tienes un fan acérrimo, PlayerName.",
  ui_story_5032_50321101_130_dialog_content = "¡Es Correcto!",
  ui_story_5032_50321101_131_dialog_content = "Honestamente... quiero decir, ¿qué tiene de bueno PlayerName ¿de todos modos?",
  ui_story_5032_50321101_132_dialog_content = "¿Qué hay de mí? También ayudé mucho, ¿sabes? ¡Y Kyllo también los ayudó a encontrar a su gato de tres colas!",
  ui_story_5032_50321101_133_dialog_content = "Tienes toda la razón, Fia... ¡Kyllo también merece nuestra gratitud!",
  ui_story_5032_50321101_134_dialog_content = "¿No es así, Kyllo?",
  ui_story_5032_50321101_135_dialog_content = "¡Lo!",
  ui_story_5032_50321101_136_dialog_content = "¡¿Q-Qué?!",
  ui_story_5032_50321101_137_dialog_content = "¡Eso es todo, Frimet! ¡Te mostraré lo fuerte que soy!",
  ui_story_5032_50321101_138_dialog_content = "Dios mío... ¿Eso es todo lo que necesitas para ponerte nervioso?",
  ui_story_5032_50321101_139_dialog_content = "Jejeje, parece que Fia también hizo nuevos amigos.",
  ui_story_5032_50321101_140_dialog_content = "Seguro que se ve así. ¡Estoy tan feliz por ellos!",
  ui_story_5032_50321101_141_dialog_content = "Frimet y sus hermanas pasan la mayor parte de sus días interactuando con miembros de la audiencia... Rara vez tienen la oportunidad de hablar con otros fuera de esa capacidad.",
  ui_story_5032_50321101_142_dialog_content = "Como resultado, en realidad no tienen amigos de su edad.",
  ui_story_5032_50321101_143_dialog_content = "Tienen tanta suerte de haber conocido a alguien como Fia...",
  ui_story_5032_50321101_144_dialog_content = "Así como el resto de ustedes. ¡Todos somos muy afortunados de haber hecho amigos como tú!",
  ui_story_5032_50321101_145_dialog_content = "*Sollozando* Arcoiris...",
  ui_story_5032_50321101_146_dialog_content = "¡Somos nosotros los que tenemos la suerte de haberos conocido a todos, Rainbow!",
  ui_story_5032_50321101_147_dialog_content = "¡Jejeje!",
  ui_story_5032_50321101_148_dialog_content = "Digan, ¿alguno de ustedes ha visto a Carleen por ahí?",
  ui_story_5032_50321101_149_dialog_content = "Carleen todavía debería estar reuniéndose con los miembros de House Modali. Hemos estado esperándola aquí para que termine su negocio.",
  ui_story_5032_50321101_150_dialog_content = "Han pasado tantas cosas, después de todo... Estoy seguro de que hay muchos asuntos que requieren su atención en este momento.",
  ui_story_5032_50321101_151_dialog_content = "<size=30>Así que esta es la vida de una princesa, eh... ¡Qué genial!</size>",
  ui_story_5032_50321101_152_dialog_content = "¿Mmm? ¿Dijiste algo?",
  ui_story_5032_50321101_153_dialog_content = "Ejeje... No deberías hacerle tantas preguntas a una chica, PlayerName!",
  ui_story_5032_50321101_154_dialog_content = "Solo ocúpate de tus propios asuntos, ¿de acuerdo?",
  ui_story_5032_50321101_155_dialog_content = "¡Waah!",
  ui_story_5032_50321101_156_dialog_content = "¡Cuidado, Merylt!",
  ui_story_5032_50321101_157_dialog_content = "En serio, ¿qué crees que estás haciendo, Subli?",
  ui_story_5032_50321101_158_dialog_content = "¡Oye, ella solo está tratando de ayudar a su hermana a su manera! ¡Jajaja!",
  ui_story_5032_50321101_159_dialog_content = "¡Haz tu mejor esfuerzo, Merylt!",
  ui_story_5032_50321101_160_dialog_content = "¿eh? Rainbow-?",
  ui_story_5032_50321101_161_dialog_content = "SS-Lo siento por eso!",
  ui_story_5032_50321101_162_dialog_content = "Está bien, Meryl. La única razón por la que chocaste conmigo es porque Subli te empujó hace un momento.",
  ui_story_5032_50321101_163_dialog_content = "¡No me dolió nada, honestamente!",
  ui_story_5032_50321101_164_dialog_content = "...",
  ui_story_5032_50321101_165_dialog_content = "(Esta... ¡Esta es mi última oportunidad!)",
  ui_story_5032_50321101_166_dialog_content = "U-Um...",
  ui_story_5032_50321101_167_dialog_content = "Te escribí una l-carta, PlayerName.",
  ui_story_5032_50321101_168_dialog_content = "¿Eh? ¿Una carta?",
  ui_story_5032_50321101_169_dialog_content = "¡P-Por favor, no lo abra hasta después de irse!",
  ui_story_5032_50321101_170_dialog_content = "Claro, no hay problema... ¡Gracias!",
  ui_story_5032_50321101_171_dialog_content = "A-También...",
  ui_story_5032_50321101_172_dialog_content = "¿Hay algo más?",
  ui_story_5032_50321101_173_dialog_content = "S-Si no es mucho p-problema... Puedo...",
  ui_story_5032_50321101_174_dialog_content = "<size=30>M-Puedo...</size>",
  ui_story_5032_50321101_175_dialog_content = "Lo siento, ¿qué fue eso?",
  ui_story_5032_50321101_176_dialog_content = "<size=45>¿Puedo visitarte en Eraveil algún día?</size>",
  ui_story_5032_50321101_177_dialog_content = "¡Guau! ¡M-Me asustaste justo ahora!",
  ui_story_5032_50321101_178_dialog_content = "¡Lo siento! ¿Fue raro de mi parte preguntar eso?",
  ui_story_5032_50321101_179_dialog_content = "¡Entiendo totalmente si no está bien! ¡Puedes decirlo y no te molestaré nunca más!",
  ui_story_5032_50321101_180_dialog_content = "Lo siento mucho, sabía que preguntarte solo causaría más problemas...",
  ui_story_5032_50321101_181_dialog_content = "¡Seguro!",
  ui_story_5032_50321101_182_dialog_content = "¿Ah?",
  ui_story_5032_50321101_183_dialog_content = "Por supuesto, ¡puedes venir a verme cuando quieras! Somos amigos, ¿verdad, Merylt?",
  ui_story_5032_50321101_184_dialog_content = "Si alguna vez quieres visitar Eraveil, la puerta siempre está abierta. ¡Incluso puedes traer a algunos de tus amigos si quieres!",
  ui_story_5032_50321101_185_dialog_content = "La reconstrucción ha ido muy bien, así que estoy seguro de que hay muchas habitaciones para que te quedes.",
  ui_story_5032_50321101_186_dialog_content = "¿F-Amigos...?",
  ui_story_5032_50321101_187_dialog_content = "... ¡G-Gracias!",
  ui_story_5032_50321101_188_dialog_content = "Ahora que lo mencionas, probablemente debería pasar por Umbraton en el camino de regreso.",
  ui_story_5032_50321101_189_dialog_content = "Si queremos dar la bienvenida a algún invitado, probablemente necesitemos abastecernos de algo de comida. Ya casi nos quedamos sin herbicida para las malas hierbas también...",
  ui_story_5032_50321101_190_dialog_content = "También nos estamos quedando sin detergente y un montón de otras necesidades diarias... Hmmm...",
  ui_story_5032_50321101_191_dialog_content = "También necesitaremos algunos suministros para ayudarnos a combatir el calor...",
  ui_story_5032_50321101_192_dialog_content = "(Frimet, Subli, creo...)",
  ui_story_5032_50321101_193_dialog_content = "(Creo que sé por qué me gusta tanto esta Caelestite ahora).",
  ui_story_5032_50321101_194_dialog_content = "Frimet... ¡Es resbaladiza como una anguila en un balde de aceite!",
  ui_story_5032_50321101_195_dialog_content = "Bueno, ella es una artista de circo entrenada, después de todo...",
  ui_story_5032_50321101_196_dialog_content = "Urgh... ¡No seré tan fácil con ella la próxima vez! ¡Lo juro!",
  ui_story_5032_50321101_197_dialog_content = "¡Lo!",
  ui_story_5032_50321101_198_dialog_content = "Siento haberos hecho esperar a todos.",
  ui_story_5032_50321101_199_dialog_content = "Parece que me perdí mucha diversión.",
  ui_story_5032_50321101_200_dialog_content = "¡Carleen! ¡Estás de vuelta!",
  ui_story_5032_50321101_201_dialog_content = "No te perdiste mucho, solo Frimet haciendo el ridículo de Fia... ¡Ay!",
  ui_story_5032_50321101_202_dialog_content = "¡Eso realmente dolió! ¡Deja de pisarme el pie!",
  ui_story_5032_50321101_203_dialog_content = "¡Hmph! Eso te enseñará a burlarte de mí, PlayerName.",
  ui_story_5032_50321101_204_dialog_content = "Muy bien, todos, eso es suficiente por ahora.",
  ui_story_5032_50321101_205_dialog_content = "¿Se ha ocupado de todo por tu parte, Carleen?",
  ui_story_5032_50321101_206_dialog_content = "*Suspiro* Puedes decir eso, sí.",
  ui_story_5032_50321101_207_dialog_content = "No pude llegar a un acuerdo con Loewe y Matthieu sobre la mejor manera de proceder. Frustrante como ha sido, ya no desean mantener todo en secreto.",
  ui_story_5032_50321101_208_dialog_content = "Recibieron mi itinerario esta mañana y regresaron a Lumopolis.",
  ui_story_5032_50321101_209_dialog_content = "Padre estaba bastante disgustado cuando lo engañé anteriormente... Todavía tengo que averiguar qué le voy a decir cuando regrese.",
  ui_story_5032_50321101_210_dialog_content = "Así es... básicamente le estabas ocultando la verdad a Lord Schwartz por el bien de Harbor City.",
  ui_story_5032_50321101_211_dialog_content = "Afortunadamente, Matthieu y los demás no saben mucho sobre Windstone.",
  ui_story_5032_50321101_212_dialog_content = "Por lo menos, eso es una cosa menos de qué preocuparse.",
  ui_story_5032_50321101_213_dialog_content = "House Modali está en completo desorden en este momento... Todavía necesitan nombrar un nuevo laird también.",
  ui_story_5032_50321101_214_dialog_content = "Si se corre la voz sobre Windstone, nunca podrán manejar las cosas.",
  ui_story_5032_50321101_215_dialog_content = "Err...",
  ui_story_5032_50321101_216_dialog_content = "¿Significa eso que Elvis todavía no ha mostrado ninguna señal de despertar?",
  ui_story_5032_50321101_217_dialog_content = "Por cierto. Actualmente, él todavía está en un coma profundo.",
  ui_story_5032_50321101_218_dialog_content = "Si no fuera por Jeno ayudándolo a llevar la carga de reactivar Windstone, Elvis ya estaría muerto.",
  ui_story_5032_50321101_219_dialog_content = "Sin embargo, incluso los mejores médicos no tienen forma de despertarlo de un coma como este.",
  ui_story_5032_50321101_220_dialog_content = "*Suspiro* Es muy triste verlo así, y después de todas las batallas que ha vivido...",
  ui_story_5032_50321101_221_dialog_content = "Tal vez... ¿este es el destino de Elvis?",
  ui_story_5032_50321101_222_dialog_content = "El deseo de Elvis de proteger a su gente condujo a este desastre en primer lugar.",
  ui_story_5032_50321101_223_dialog_content = "Y así, la única forma de salvar a su pueblo de su propio mal era sacrificándose a sí mismo.",
  ui_story_5032_50321101_224_dialog_content = "En cierto modo, se puede decir que logró lo que se había propuesto desde el principio.",
  ui_story_5032_50321101_225_dialog_content = "Alguien como él ya debe haber hecho las paces con esto como un posible resultado.",
  ui_story_5032_50321101_226_dialog_content = "...",
  ui_story_5032_50321101_227_dialog_content = "Increíble... Siempre logras hablar tan bien cuando más importa, Fia.",
  ui_story_5032_50321101_228_dialog_content = "No puedo evitar admirarte un poco más después de decir eso.",
  ui_story_5032_50321101_229_dialog_content = "¿Quéeeee? Quieres decir que no podrías llegar a una conclusión tan simple por tu cuenta, PlayerName?",
  ui_story_5032_50321101_230_dialog_content = "No vas a durar un día en la sociedad si no empiezas a pensar un poco más por ti mismo, ¡lo sabes!",
  ui_story_5032_50321101_231_dialog_content = "¡Solo te estaba haciendo un cumplido! ¡Que no se te suba a la cabeza!",
  ui_story_5032_50321101_232_dialog_content = "¡Sigue así, y podría cambiar de opinión acerca de ayudarte a explicarle las cosas a tu maestro!",
  ui_story_5032_50321101_233_dialog_content = "¡¿Q-Qué?! ¡No por favor! ¡Todo menos eso!",
  ui_story_5032_50321101_234_dialog_content = "¡Ya prometiste ayudar! ¡¿Qué tipo de persona serías si no cumplieras tus promesas?!",
  ui_story_5032_50321101_235_dialog_content = "Fia tiene un buen punto, ya sabes.",
  ui_story_5032_50321101_236_dialog_content = "Este podría ser el resultado que Elvis más deseaba.",
  ui_story_5032_50321101_237_dialog_content = "La paz finalmente ha regresado a Harbor City, después de todo.",
